window.POEM_DB=window.POEM_DB||{};POEM_DB["yuan_009"]={"n":"耶律楚材","dyn":"元","poems":[{"t":"鹧鸪天 题七真洞","f":"曲","c":["花草倾颓事已迁。","浩歌遥望意茫然。","江山王气空千劫，桃李春风又一年。","横翠嶂，架寒烟。","野花平碧怨啼鹃。","不知何限人间梦，并触沉思到酒边。"]},{"t":"怀亲二首 其一","f":"七言绝句","c":["黄犬不来愁耿耿，白云望断思依依。","欲凭鳞羽传音信，海水西流雁北飞。"]},{"t":"怀亲二首 其二","f":"五言绝句","c":["黄沙三万里，白发一孀亲。","肠断边城月，徘徊照旅人。"]},{"t":"和黄华老人题献陵吴氏成趣园诗","f":"七言古诗","c":["雪溪词翰辉星斗，纸蠹尘蒙诗一首。","湛然挥墨试续貂，嗫嚅使人难出口。","丁年彭泽解官去，遨游三径真三友。","悠然把菊见南山，畅饮东篱醉重九。","献陵吴氏治荒园，成趣为名良可取。","养高不肯事王侯，闲卧林泉了衰朽。","今年扈从过秦川，可怜尚有萧条柳。","归计甘输吴子先，丽词已后黄华手。","知音谁听断弦琴，临风痛想纱巾酒。","嗟乎世路声利人，不知曾忆渊明否？"]},{"t":"和平阳王仲祥韵","f":"五言古诗","c":["一圣扬天兵，万国皆来臣。","治道尚玄默，政简民风纯。","明明我嗣君，宽诏出丝纶。","洪恩浃四海，圣训宜书绅。","逆取乃顺守，皇威辅深仁。","贪饕致天罚，长吏求良循。","河表背盟约，羽檄飞边尘。","圣驾亲徂征，将安亿兆人。","湛然陪扈从，书剑犹随身。","翠华次平水，草木咸生春。","冰岩上新句，文质能彬彬。","冰雪相照映，珠玉如横陈。","诗笔居独步，唐都一逸民。","圣政罔二三，裁物惟平均。","综名必核实，求儒务求真。","经术勿疏废，笔砚当可亲。","伫待寰宇清，圜丘祀天神。","选举再开辟，仲祥当超伦。","一旦腾达时，献策宜诜诜。"]},{"t":"和李世荣韵","f":"五言古诗","c":["圣主题华旦，熊罴百万强。","兵行从纪律，敌溃自奔忙。","百谷朝沧海，群阴畏太阳。","黎民欢仰德，万国喜观光。","尧舜规模远，萧曹筹策长。","巍然周礼乐，盛矣汉文章。","神武威兼德，徽猷柔济刚。","自甘头戴白，误受诏批黄。","我道将兴启，吾侪有激昂。","厚颜悬相印，否德忝朝纲。","佐主难及圣，为臣每愿良。","翠华来北阙，黄钺讨南疆。","明德传双叶，宽仁洽万方。","九服无不轨，四海愿来王。","兵革虽开创，诗书何可忘。","洪恩浮晓露，严令肃秋霜。","符应千龄运，功垂万世昌。","绵绵延国祚，烨烨受天祥。","多士咸登用，群生无败戕。","此行将告老，松菊未全荒。"]},{"t":"和李世荣见寄","f":"五言古诗","c":["云横北海西，驲骑来天际。","梅轩真可人，新诗远相惠。","其声若良金，其臭如芳蕙。","文艳理无华，词雄言不侈。","笔力似黄山，惊浪云奔势。","犀象牙角新，虿蜂铓尾细。","遥想醉衔杯，梅坞清阴翳。","閒散玉麒麟，可得羁而系。","吾子卧东山，谁治今之世。","好陈十渐书，毋用六奇计。","万里入龙庭，何须叹迢递。","时方涉大川，舟楫须君济。"]},{"t":"和李世荣韵","f":"七言律诗","c":["多谢梅轩不惜春，声诗来寄格清新。","词源莫测波千顷，笔力能扛鼎万钧。","忧国心情常悄悄，闲居容止自申申。","谁知板荡中原后，潇洒河东有若人。"]},{"t":"再用其韵","f":"七言律诗","c":["梅轩相别又三春，别后文章与日新。","不忿散材沾造化，好将幽隐入陶钧。","我游北海年垂老，君卧南阳志未申。","遥想冰魂政无恙，一枝回施陇头人。"]},{"t":"又索六经","f":"七言律诗","c":["我爱平阳李世荣，一番书史再镌铭。","欲令吾子穷三传，故向君家乞六经。","简策灿然新制度，文章宛尔旧仪刑。","莫教幼稚空相忆，日日求书到鲤庭。"]},{"t":"和移剌继先韵三首 其一","f":"七言古诗","c":["泽民我愧无术略，且着诗鸿慰离索。","诗书满载升金山，弦歌不辍踰松漠。","世上元无真是非，安知今是而非昨。","连城美玉涅不缁，百鍊真金光愈烁。","已悟真如匪去来，自然胸次绝忧乐。","断梦还同世事空，浮云恰似人情薄。","尚记吾山旧隐居，松风萧瑟松花落。","枕流漱石轻轩车，吟烟啸月甘藜藿。","春山寂寂春溪深，萧条庭户堪罗雀。","而今不得安疏懒，自笑绦笼困雕鹗。","勉力龙庭上万言，男儿志不忘沟壑。"]},{"t":"和移剌继先韵三首 其二","f":"七言古诗","c":["当年不肯读三略，独抱遗经伴闲索。","流行坎止不尤人，自甘万里涉穷漠。","富贵荣华能几时，生死都来如梦昨。","千年兴废沤浮沈，百岁光阴电飞烁。","常笑梁鸿歌五噫，窃学荣启弹三乐。","未能仁义戢干戈，勉将敦厚惩浇薄。","近有人从故隐来，黄花无恙开篱落。","问渠林肉与丘糟，奚如饭麦而羹藿。","人闻麋鹿满姑苏，阿瞒不复游铜雀。","涂中曳尾希庄龟，江夏沉舟悲祢鹗。","吾山佳处归休乎，鹿逸平林鱼纵壑。"]},{"t":"和移剌继先韵三首 其三","f":"曲","c":["祖道门庭元简略，儿孙草里添芒索。","拟心鹞子过新罗，起念白云横大漠。","迥殊四句有无中，元非三际来今昨。","大海纤尘一点飞，洪炉片雪寒光烁。","宁论业障本来空，半偈徒誇寂灭乐。","细切清风非异事，更将明月?来薄。","玲珑四面亦无门，充塞十方绝壁落。","罗列珍羞渠不食，痴人犹是贪藜藿。","祗图龙颔摘明珠，谁知虎口存活雀。","坐晚犹迷一色边，崎岖鸟道横秋鹗。","可笑人间荆棘林，死者填沟空塞壑。"]},{"t":"和薛伯通韵","f":"七言律诗","c":["滴滴秋光溢远山，穹庐寥落酒瓶乾。","诗章平淡思居易，禅里纵横忆道安。","不忿西风霜叶脱，难禁秋雨菊花残。","闾山旧隐天涯远，梦里思归梦亦难。"]},{"t":"鹿尾","f":"七言律诗","c":["銮舆秋狝猎南冈，鹿尾分甘赐尚方。","浓色殷殷红玉髓，微香馥馥紫琼浆。","韭花酷辣同葱薤，芥屑差辛类桂姜。","何似毡根蘸浓液，邀将诗客大家尝。"]},{"t":"过金山用人韵","f":"七言律诗","c":["雪压山峰八月寒，羊肠樵路曲盘盘。","千岩竞秀清人思，万壑争流壮我观。","山腹云开岚色润，松巅风起雨声乾。","光风满贮诗囊去，一度思山一度看。"]},{"t":"过云中赠别李尚书","f":"七言律诗","c":["谁识云中李谪仙，诗如文锦酒如川。","十亩良园君有趣，一廛薄土我无缘。","旧恨常来春梦里，新吟不到客愁边。","明朝分手天涯去，他日相逢又几年。"]},{"t":"和裴子法韵","f":"曲","c":["达磨一派未西来，无限劳生眼未开。","六朝繁盛已矣耳，两晋风流安在哉！","自笑中书老仆射，事佛窃仿王安石。","公案翻腾旧葛藤，林泉准备闲踪迹。","用之勋业垂千秋，发扬孔孟谁为俦。","舍之独善乐真觉，赋诗舒笑临清流。","岂止渊明慕松菊，晋室高贤十八九。","君子道消小人用，贞夫远弃利名酒。","苏、黄冠世能文词，裴、张二相名当时。","祖道禅林恣游戏，尧风舜德甘嘘吹。","达人不为造物役，打破东西与南北。","毛吞巨海也寻常，出没纵横透空色。","真如颇与羲易同，不动确乎无吉凶。","湛然信笔书寱语，临风远寄绿野翁。","赠君一句直截处，祗要教君能养素。","但能死生荣辱哀乐不能羁，存亡进退尽是无生路。"]},{"t":"和许昌张彦升见寄","f":"曲","c":["真人休运应千载，生知神武威中邦。","杜绝奇技贱异物，连城玉斗曾亲撞。","兵出潼关渡天堑，翠华杂映驺虞幢。","生民鼓舞叹奚后，壶浆箪食辕门降。","偏师一鼓汴梁下，逻骑饮马扬子江。","良臣自有魏、郑辈，死谏安用干与逢。","少微昨夜照平水，清河国士真无双。","壮岁游学力稽古，孜孜继晷焚兰釭。","新诗寄我有深意，再三舒卷临幽窗。","安得先生赞王室，委倚奚忧庶政庞。","堪笑纷纷匹夫勇，徒誇巨鼎千钧扛。","何日安车蒲轮诏，公入北阙，葡萄佳酝烂饮玻瓈缸。"]},{"t":"和南质张学士敏之见赠七首 其一","f":"曲","c":["桃源刘，凤楼萧，镌冰斲玉哦通宵。","珠玑错落照兰室，龙蛇偃蹇蟠霜绡。","和我新诗使予起，却得琼瑰酬木李。","边城十载绝知音，琴断七弦鹤亦死。","而今得识君恣容，胸中郁结涣然空。","诗坛君可据上位，笔力我甘居下风。","笔阵文场宽且绰，驰骋看君能矍铄。","学海波澜千顷陂，厌饫经书烂该博。","几时把手潇湘边，生涯自有壶中天。","鸣榔一笑舟浮莲，沧波万里凝苍烟。"]},{"t":"和南质张学士敏之见赠七首 其二","f":"曲","c":["漏沈沈，竹萧萧，蒲团禅定坐终宵。","古庙香炉无气息，一条白练如琼绡。","性海澄澄波不起，宛似冰壶沈玉李。","庸人泥教不知归，七窍凿开混沌死。","虽云至道绝音容，不离幻有成真空。","百尺竿头更移步，普天匝地生清风。","大用全提自宽绰，禅将交锋何矍铄。","醒时呼起梦中人，遍济含生其利博。","本无内外与中边，踏破威音劫外天。","污泥深处种青莲，升平世界沈烽烟。"]},{"t":"和南质张学士敏之见赠七首 其三","f":"曲","c":["雨萧萧，风萧萧，对床谈道彻清宵。","欲画太虚无面目，慎无落笔污冰绡。","人间平地风波起，反笑于陵啖螬李。","富贵荣华都几时，迷者孰能死前死。","须弥芥子云相容，神通妙用不空空。","劫火洞然渠不坏，纸鸢能禦毗蓝风。","龙象腾骧何绰绰，回视驽骀空矍铄。","悟时一语透尘沙，安用才学恃宏博。","维摩方丈傍无边，个中无碍散花天。","回途稳稳步双莲，得玄鸟道横晴烟。"]},{"t":"和南质张学士敏之见赠七首 其四","f":"曲","c":["院深深，籁萧萧，伽陀舒卷度兰宵。","若解荷心系珠露，便能天外裁云绡。","大觉空生一沤起，悟斯独有屏山李。","穿透楞严第一机，方信庵中人不死。","个里家风针不容，梦回六趣大千空。","道人受用本无尽，明月薄?细切风。","香象朋从威绰绰，独跳狂獐空矍铄。","悲心起处了无私，济度尘沙恩广博。","不涉中流离两边，下无大地上无天。","无人无佛台无莲，萋萋碧草生芳烟。"]},{"t":"和南质张学士敏之见赠七首 其五","f":"曲","c":["云飘飘，水萧萧，一灯香火过闲宵。","神清半夜不成梦，书帷风细扬微绡。","运应昌期王者起，自愧文章输杜李。","窃同居易了无生，谁羡葛洪学不死。","一榻蒲团膝足容，翛然丈室塞虚空。","翻腾密藏明佛日，淘汰机缘振祖风。","丹凤冲霄何绰绰，失晓呆郎徒矍铄。","人间取舍本千差，世路穷通如六博。","幽人啸咏水云边，劫外光风自一天。","闲来石上栽红莲，水无波浪火无烟。"]},{"t":"和南质张学士敏之见赠七首 其六","f":"曲","c":["风萧萧，雨萧萧，萧萧风雨悲凉宵。","篱菊残英渍黄玉，林风脱叶飘红绡。","幽人辗转凌晨起，邂逅门前逢短李。","殷衰闻道有三仁，欲说九畴君不死。","穹庐相结为从容，悬河雄辨能谈空。","风神萧散野鹤立，照人玉树临秋风。","落笔新诗一挥绰，不似武人誇矍铄。","银钩笔力掩二王，照夜连城肯轻博。","他年相约秋山边，秋江一派连秋天。","闲听菱女歌采莲，轻舟一醉眠秋烟。"]},{"t":"和南质张学士敏之见赠七首 其七","f":"曲","c":["衣龙钟，鬓飘萧，穹庐停烛坐寒宵。","翰林遣介赠佳句，虿芒鸟迹书生绡。","既倒狂澜再扶起，昔有谪仙原姓李。","今日龙庭忽见君，谁道当年太白死。","文章气象难形容，腾龙翥凤游秋空。","笔力万钧神鬼泣，雷轰电掣驱疾风。","馀裕喜君能绰绰，鼓舞为君予矍铄。","解读奇字笑扬雄，识厌张华能物博。","与君握手天山边，举觞相嘱望青天。","他年雅社结白莲，林泉杖屦冲云烟。"]},{"t":"和张敏之鸣凤曲韵","f":"曲","c":["写蛟螭，咳珠玑，英姿元拣碧梧栖。","彬彬文彩自光辉，有材希晋用，失志欲刘依。","荐君谁肯惜吹嘘，洪才大笔识君稀。","鲲游翻海震，鹏举翥天飞。","问渠蟾窟攀仙桂，何似冥山破铁围。","人间强认假生死，世上本无真是非。","浓欢殢春梦，晚景叹残晖。","梦断日沈真可笑，输却禅人向上机。","遮眼开经卷，蒙头坏衲衣。","息念融凡圣，无心应顺违。","震风威，横担楖栗万山归。"]},{"t":"和孟驾之韵","f":"七言古诗","c":["平阳闻有邹人孙，封书上我仅万言。","讨论坟典造极致，商搉古今穷深源。","文章高出苏黄辈，英雄不效秦仪志。","志图仁义济元元，异比无双瑚琏器。","沦落尘埃德不孤，梅轩结友天一隅。","我惜盐车困骐骥，腾骧未得踏亨涂。","瓮牖绳枢甘俭薄，饥肠雷转充糟粕。","他日佳声闻九天，富贵之来不得却。","丁年黄卷乐平生，乡闾一诺千金轻。","沧浪清处闲濯缨，才名高价如连城。","笔下有神诗有眼，五车书史穷编简。","一举高登甲乙科，曾对阊阖持手版。","天兵一鼓下雎阳，旌旗整整阵堂堂。","玉石俱焚君子隐，北渡来依日月光。","徒步黄尘千里远，犹抱遗经究微婉。","天产昂藏一丈夫，三十未遇非为晚。","闻望卓冠儒林丛，灿然星宿罗心胸。","驰骤大方孰并驾，绝尘奔逸其犹龙。","君似昆吾玉可切，锟铻不是寻常铁。","利颖神锋人未知，宝匣空闲三尺雪。","何时搜出蛰龙鞭，一声霹雳轰青天。","岁旱须君作霖雨，拔茅进用其茹连。","天子明堂求国栋，鹏飞全藉天风送。","凤池波暖百花新，咏游不作江湖梦。"]},{"t":"和陈秀玉绵梨诗韵","f":"曲","c":["石门九月西风高，绵梨万树金垂梢。","清溪千里携赠我，藤筐初发香盈包。","谪仙风度清溪亚，春风曾饮梨花下。","不用红妆唱采莲，醉望青天歌二雅。","我有斗酒清且醇，同君荐此鹅黄新。","初见分香剖金卵，更看削玉飞霜鳞。","缥叶紫条何足语，夜光安可同鱼目。","文园尘渴政难禁，咀嚼冰雪?香玉。"]},{"t":"和冀先生韵","f":"五言古诗","c":["运出三爻兑，龙飞九五乾。","要荒归化育，豪哲入陶甄。","有幸恩涵海，无私德应天。","偏师收百越，一鼓下三川。","天子能身正，元戎不自贤。","重光道同轨，累圣德相联。","策决九重内，功归万乘权。","群雄哀稽颡，多士喜摩肩。","辅弼规左右，丞疑赞后前。","开夷逾汉武，平叛跨周宣。","冠盖通穷域，车书过古埏。","览机云母障，受谏翠华軿。","款塞诸蛮洞，来朝百济船。","降王趋陛阙，强虏列氓编。","净扫妖氛变，潜消烽火烟。","词臣游馆阁，幽隐起林泉。","尧舜文明盛，商姬礼乐全。","九成合古奏，二雅咏新篇。","世卜千百世，年斯亿万年。","宗亲成蒂固，国祚等瓜绵。","圣政舆人颂，天威万古传。","勉旃封禅事，不用策安边。"]},{"t":"和百拙禅师韵","f":"七言律诗","c":["十方世界是全身，气宇如王绝比伦。","与夺机中明主客，正偏位里辨君臣。","眠云卧月辞三岛，鼓腹讴歌预四民。","了了了时谁可晓，闲人元不是闲人。"]},{"t":"题平阳李君实吟醉轩","f":"七言律诗","c":["古晋君实世所知，幽轩佳号两相宜。","长鲸海量嫌甜酒，彩笔天才笑小诗。","七步赋成文灿烂，千钟不惜锦淋漓。","何当杖屦游平水，得预君家吟醉时。"]},{"t":"从圣安澄老借书","f":"七言律诗","c":["湛然寱语寄西堂，此个因缘果异常。","阳老十门刚结案，钦公五派强分赃。","剑逢剑客须拈出，诗遇诗人何必藏。","居士病多谙药性，圣安得效不传方。"]},{"t":"题西庵所藏佛牙二首 其一","f":"七言律诗","c":["殷勤敬礼辟支牙，缘在西庵居士家。","午夜飞光惊晓月，六时腾焰灿朝霞。","一番顶带因初结，七转生天果不差。","庸士执方犹未信，防风安得骨专车。"]},{"t":"题西庵所藏佛牙二首 其二","f":"七言律诗","c":["旃檀奁里贮灵牙，来自中天尊者家。","瑩色冷夺秋夜月，真光明射晚晴霞。","本同舍利元无别，疑是金刚事有差。","犹忆广长舌左右，咀嚼风雨震雷车。"]},{"t":"和移剌继先韵二首 其一","f":"七言律诗","c":["旧山盟约已愆期，一梦十年尽觉非。","瀚海路难人去少，天山雪重雁飞稀。","渐惊白发宁辞老，未济苍生曷敢归。","去国迟迟情几许，倚楼空望白云飞。"]},{"t":"和移剌继先韵二首 其二","f":"七言绝句","c":["不事王侯懒属文，时危何处觅元勋。","他年收拾琴书去，笑傲林泉我与君。"]},{"t":"过阴山和人韵 其一","f":"七言古诗","c":["阴山千里横东西，秋声浩浩鸣秋溪。","猿猱鸿鹄不能过，天兵百万驰霜蹄。","万顷松风落松子，郁郁苍苍映流水。","天丁何事誇神威，天台、罗浮移到此。","云霞掩翳山重重，峰峦突兀何雄雄。","古来天险阻西域，人烟不与中原通。","细路萦纡斜复直，山角摩天不盈尺。","溪风萧萧溪水寒，花落空山人影寂。","四十八桥横雁行，胜游奇观真非常。","临高俯视千万仞，令人凛凛生恐惶。","百里镜湖山顶上，旦暮云烟浮气象。","山南山北多幽绝，几派飞泉练千丈。","大河西注波无穷，千溪万壑皆会同。","君成绮语壮奇诞，造物缩手神无功。","山高四更才吐月，八月山峰半埋雪。","遥思山外屯边兵，西风冷彻征衣铁。"]},{"t":"过阴山和人韵 其二","f":"五言律诗","c":["羸马阴山道，悠然远思寥。","青峦云霭霭，黄叶雨萧萧。","未可行周礼，谁能和舜韶。","嗟吾浮海粟，何碍八风飘。"]},{"t":"过阴山和人韵 其三","f":"七言律诗","c":["八月阴山雪满沙，清光凝目眩生花。","插天绝壁喷晴月，擎海层峦吸翠霞。","松桧丛中疏畎亩，藤萝深处有人家。","横空千里雄西域，江左名山不足誇。"]},{"t":"过阴山和人韵 其四","f":"七言律诗","c":["阴山奇胜讵能名，断送新诗得得成。","万叠峰峦擎海立，千层松桧接云平。","三年沙塞吟魂遁，一夜毡穹客梦清。","遥想长安旧知友，能无知我此时情。"]},{"t":"再用前韵","f":"七言古诗","c":["河源之边鸟鼠西，阴山千里号千溪。","倚云天险不易过，骕骦局蹙追风蹄。","签记长安五陵子，马似游龙车如水。","天王赫怒山无神，一夜雄师飞过此。","盘云细路松成行，出天入井实异常。","王尊疾驱九折坂，此来一顾应哀惶。","峥嵘突出峰峭直，山顶连天才咫尺。","枫林霜叶声萧骚，一雁横空秋色寂。","西望月窟九译重，嗟呼自古无英雄。","出关未盈十万里，荒陬不得车书通。","天兵饮马西河上，欲使西戎献驯象。","旌旗蔽空尘涨天，壮士如虹气千丈。","秦皇、汉武称兵穷，拍手一笑儿戏同。","堑山陵海匪难事，剪斯群丑何无功。","骚人羞对阴山月，壮岁星星发如雪。","穹庐展转清不眠，霜匣闲杀锟铻铁。"]},{"t":"复用前韵唱玄","f":"七言古诗","c":["天涯流落从征西，寒盟辜负梅花溪。","昔年学道颇得趣，鱼兔入手忘筌蹄。","残编断简披庄子，日日须当诵秋水。","谁知海若无津涯，河伯源流止于此。","人閒酱缶纸数重，太玄强草嗤扬雄。","高卧蒿莱傲唐室，清风千古独王通。","曲者自曲直者直，何必区区较绳尺。","一笔划断闲是非，万事都忘乐岑寂。","功名半纸几字行，竞羡成绩书太常。","只知牢筴飨刍豢，不思临刃心悲惶。","何如打坐蒲团上，参透升平本无象。","一瓶一钵更无馀，容膝禅庵仅方丈。","从教人笑彻骨穷，生涯原与千圣同。","鸟道虽玄功尚在，不如行取无功功。","归来踏破澄潭月，大冶洪炉飞片雪。","且听石女鸣巴歌，万里一团无孔铁。"]},{"t":"用前韵送王君玉西征二首 其一","f":"七言古诗","c":["湛然送客河中西，乘兴何妨过虎溪。","清茶佳果饯行路，远胜浊酒烹驼蹄。","结交须结真君子，君子之交淡如水。","一从西域识君侯，倾盖交欢忘彼此。","当年君卧东山重，守雌默默元知雄。","五车书史岂劳力，六韬三略无不通。","诗咏珠玑无价直，青囊更有琴三尺。","奉命西来典重兵，不得茅斋乐真寂。","鱼丽大阵兵成行，行师布置非寻常。","先生应诏入西域，一军骇异皆惊惶。","武皇习战昆明上，欲讨昆明致犀象。","吾皇兵过海西边，气压炎刘千万丈。","先生一展才略穷，百蛮冠带文轨同。","威德洋洋震天下，大功不宰方为功。","隐居自有东山月，风拂松花落香雪。","退身参到未生前，方信秤锤原是铁。"]},{"t":"用前韵送王君玉西征二首 其二","f":"楚辞体","c":["先生应诏将征西，湛然送客涉深溪。","徘徊一舍未忍去，兵车暂驻天驹蹄。","犹忆今春送君子，桃李无言映流水。","寒暑推迁奈老何，秋风革律重来此。","关山险僻重复重，西门雪耻须豪雄。","定远奇功正今日，车书混一华夷通。","先生纯德如矢直，讵为直寻而枉尺。","功成莫恋声利场，便好回头乐玄寂。","故山旧忆松千行，奇峰怪石元异常。","前日盟言犹在耳，猿鹤思怨空悲惶。","我掷直钩鱼不上，须信游鳞畏龙象。","冥鸿一举腾秋空，谁羡文章光万丈。","道兮人作非天穷，区区何必较异同。","语默行藏在乎我，退身奚论无成功。","安东幸有闾山月，万顷松风万山雪。","收拾琴书归去来，修心须要金成铁。"]},{"t":"用前韵感事二首 其一","f":"七言古诗","c":["称斤甘荠卖京西，谁信无人采五溪。","鹏异众禽全六翮，麟殊凡兽具五蹄。","昔年学道宗夫子，盈科后追如流水。","蛰龙犹未试风雷，萍泛蓬飘而至此。","缊袍甘分百结重，不学乱世奸人雄。","忘忧乐道志不二，守穷待变变则通。","岁寒松柏苍苍直，摩云直待高千尺。","桃李无言蹊自成，此君冷淡人何寂。","生平耻与哙伍行，杜门养拙安天常。","泽民致主本予志，素愿未酬予恐惶。","否塞未能交下上，何日亨通变爻象。","不图廊庙为三公，安得林泉参百丈。","居士身穷道不穷，庸人非异是所同。","笔头解作万言策，人皆笑我劳无功。","流落遐荒淹岁月，赢得飘萧双鬓雪。","谋生太拙君勿嗤，不如嗣宗学锻铁。"]},{"t":"用前韵感事二首 其二","f":"七言古诗","c":["金乌日日东飞西，滔滔绿水流长溪。","流波一去不复返，逐日恨无八骏蹄。","穷理达生独孔子，叹夫逝者如斯水。","岁不我与其奈何，两鬓星星尚如此！","曩时凿破藩垣重，泽民济世学英雄。","风云未会我何往，天地大否途难通。","霜匣神剑苍龙直，切玉如泥长数尺。","利器深藏人未知，丰城埋没神光寂。","读书一目下数行，金石其心学正常。","学术忠义两无用，道之将丧予忧惶。","有意攀龙不得上，徒劳牙角拔犀象。","唯思仁义济苍生，岂为珍羞列方丈。","箪瓢陋巷甘孤穷，鸿鹄安与燕雀同。","天与之才不与地，反令竖子成其功。","安得光明依日月，功名未立头如雪。","问君此错若为多，使尽二十四州铁。"]},{"t":"过济源和香山居士韵","f":"五言古诗","c":["覃怀胜游地，济渎垂名久。","忽见乐天吟，笑我输先手。","丽词金玉振，老笔风雷走。","乘兴试续貂，启我谈天口。","平湖涌泉注，清凉瑩无垢。","凭槛瞰涟漪，风髯尘抖擞。","龙孙十万竿，蓊翳浓阴厚。","沁水济源东，天坛王屋右。","秀色已可餐，何须杜康酒。","步步总堪诗，佳篇如素有。","赓酬淡相对，独有龙冈叟。","亭上几徘徊，斜阳西入酉。","晚年归意切，对此空沉首。","何日遂初心，营居碧林后。"]},{"t":"和裴子法见寄","f":"五言古诗","c":["人生都几何，半被功名役。","一旦燕山破，西行过千驿。","颠沛不违仁，先难而后获。","鹓雏捐腐鼠，乌鸢其勿嚇。","扈从出天山，从容游大石。","琴书淡相对，尚未忘丘索。","前岁入关中，戈甲充商虢。","明诏典兰省，自愧承深责。","秦陇成劫灰，京索空陈迹。","长河尚浊流，南山自浓碧。","把酒酹青天，兴亡吊今昔。","长安非衣君，壮年学问积。","天上玉麒麟，英才可珍惜。","诗魂素月高，饮量沧海窄。","清谈咳珠玉，便腹笥经籍。","服君百韵诗，谢子万言策。","易道已变屯，世爻当应革。","淮阴正虚襟，左车宜筹画。","须要莲峰手，乾坤再开辟。","昂藏绿野翁，真我龙门客。"]},{"t":"用李德恒韵寄景贤","f":"七言律诗","c":["牢落十年扈御营，瑶琴忘尽水仙声。","酷思诗酒闲中乐，见说干戈梦里惊。","林下因缘千古重，人间富贵一钱轻。","此身未退心先退，独有龙冈识我情。"]},{"t":"过天德和王辅之四首 其一","f":"七言律诗","c":["天纵吾君大圣人，天兵所指弭烟尘。","三齐电扫何须郦，六国雷驱不用秦。","诛佞未闻曾请剑，劾奸谁肯试埋轮。","伴食黄阁空无辅，自笑龙钟一老臣。"]},{"t":"过天德和王辅之四首 其二","f":"七言律诗","c":["六师严驾渡长河，师不留行谁敢何！","千里旌旗翻锦浪，一声金鼓振寒波。","殷亡谁道三仁在，康灭空传五子歌。","唾手要荒归一统，汉唐鸿业未能过。"]},{"t":"过天德和王辅之四首 其三","f":"七言律诗","c":["积年叨禄领台司，位重才微甚不宜。","地上流钱惭晏算，樽前决胜愧良帷。","过实声问传人口，似直愚忠结主知。","三径荒凉松菊在，他时舍此复何之。"]},{"t":"过天德和王辅之四首 其四","f":"七言律诗","c":["整老先生本素臣，洪才大笔力千钧。","沽名不筑传岩版，贾世谁垂渭水纶。","舟泛五湖希范蠡，腰悬六印笑苏秦。","韦编三绝耽羲易，萧散风神真隐人。"]},{"t":"槐安席上和张梅韵","f":"七言律诗","c":["甘荠五溪人不采，两京高价卖秤斤。","君方沦落羞看我，我亦飘零懒问君。","人远空残眉上黛，愁深不整鬓边云。","谁怜古戍寒窗下，新样梭成织锦文。"]},{"t":"思亲有感二首 其一","f":"七言律诗","c":["游子栖迟久不归，积年温清阙慈闱。","囊中昆仲亲书帖，箧内萱堂手制衣。","黄犬不来愁耿耿，白云空望思依依。","欲凭鳞羽传安信，绿水西流雁北飞。"]},{"t":"思亲有感二首 其二","f":"七言律诗","c":["伶仃万里度西陲，壮岁星星两鬓丝。","白雁来时思北阙，黄花开日忆东篱。","可怜游子投营晚，正是孀亲倚户时。","异域风光恰如故，一消魂处一篇诗。"]},{"t":"思友人","f":"七言律诗","c":["落日萧萧万马声，东南回首暮云横。","金朋兰友音书绝，玉轸朱弦尘土生。","十里春风别野店，五年秋色到边城。","云山不碍归飞梦，夜夜随风到玉京。"]},{"t":"赠李郡王笔","f":"七言律诗","c":["管城从我自燕都，流落遐荒万里馀。","半札秋毫裁翡翠，一枝霜竹剪琼琚。","锋端但可题尘景，笔下安能划太虚。","聊复赠君为土物，中书休笑不中书。"]},{"t":"寄云中卧佛寺照老","f":"七言律诗","c":["像教中微祖意沈，卢能嫡子起予深。","看经不怕牛皮透，着眼常听露柱吟。","行道权居卧佛寺，活机特异死禅心。","凭君摘取空华实，好种人閒无影林。"]},{"t":"寄平阳净名院润老","f":"七言律诗","c":["昔年平水便相寻，握手临风话素心。","刻烛赋成无字句，按徽弹彻没弦琴。","风来远渡晚潮急，雨过寒塘秋水深。","此乐莫教儿辈觉，又成公案满丛林。"]},{"t":"赠云川张道人","f":"七言律诗","c":["云川道士有诗声，刻篆雕虫醉未醒。","素扇自甘赎碧笠，玄鹤不肯换黄庭。","春秋荣悴悲椿木，晦朔生凋笑瑞蓂。","何似扩开真日月，区区爝火任荧荧。"]},{"t":"赞李俊英所藏观音像","f":"七言律诗","c":["白衣大士足威神，莲智兴悲讵可陈。","金色界中垂万臂，碧莲花上露全身。","镇州铸就金难似，天竺镌来玉未真。","不识观音真面目，莺吟燕语过残春。"]},{"t":"题西庵归一堂","f":"七言律诗","c":["三圣真元本自同，随时应物立宗风。","道儒表里明坟典，佛祖权宜透色空。","曲士寡闻能异议，达人大观解相融。","长沙赖有莲峰掌，一拨江河尽入东。"]},{"t":"和景贤还书韵二首 其一","f":"曲","c":["居士今年又出关，琴书真味伴予闲。","?成草略初无意，语阙治择误犯颜。","漆水自惭贻口实，龙冈却得破诗悭。","衰翁幸乞赎前过，一炷清香论八还。"]},{"t":"和景贤还书韵二首 其二","f":"七言律诗","c":["渊明幽隐掩柴关，琴已忘弦人亦闲。","静倚书窗独寄傲，笑观庭树自怡颜。","五音格外声何限，百草头边法不悭。","蠹谱断弦无用处，因风得得寄书还。"]},{"t":"外道李浩求归再用韵示景贤","f":"七言律诗","c":["自从一箭透重关，触处忘缘触处闲。","莫问羔裘横毳衲，从教华发映苍颜。","水声说法起予甚，山色呈机不我悭。","寄客天涯乐如许，问渠何必更南还。"]},{"t":"外道李浩和景贤霏字韵予再和呈景贤","f":"七言律诗","c":["尘缘划断已忘机，布鼓徒敲和者稀。","中隐强陪人事过，禅心不与世情违。","昔年勋业真堪笑，旧日家山懒欲归。","我爱北天真境界，乾坤一色雪花霏。"]},{"t":"和杨居敬韵二首 其一","f":"七言律诗","c":["自愧才术草芥微，偶然千载遇明时。","惟希一统皇家义，何暇重思晁氏危。","仁义且图扶孔孟，纵横安肯效秦仪。","行看尧舜泽天下，万国咸宁庶绩熙。"]},{"t":"和杨居敬韵二首 其二","f":"七言律诗","c":["诏下龙庭万国欢，野花啼鸟总欣然。","熙朝龟卜符千亿，圣主龙飞第一年。","至道变通皆有数，浮生富贵本由天。","谁人得似杨公子，傲世高吟数百篇。"]},{"t":"过天宁寺用彦老韵二首 其一","f":"七言律诗","c":["十年不得舞衣班，行尽天涯万里山。","黄阁伴食空皓首，苍生未济漫胡颜。","新朝兵革征方急，旧隐烟霞尚未还。","衮衮簿书尘满眼，衰翁奚暇谒松关。"]},{"t":"过天宁寺用彦老韵二首 其二","f":"七言绝句","c":["今日从征亦偶然，天宁遐想思悬悬。","贪荣不得还山去，须信衰翁未古贤。"]},{"t":"过天山周敬之席上和人韵二首 其一","f":"七言律诗","c":["沦落天涯数十秋，区区班笔早年投。","采薇山下慵拈草，洗耳溪边懒饮牛。","振武扬威难射虎，忘机绝虑不惊鸥。","当年射策承明殿，未必轻轻输吕筹。"]},{"t":"过天山周敬之席上和人韵二首 其二","f":"七言律诗","c":["憩马居延酒半醺，寂寥寒馆变春温。","未能鹏翼腾溟海，不得鸿音过雁门。","千里云烟青冢暗，一天风雪黑山昏。","天涯幸遇知音士，子细论文共一樽。"]},{"t":"和人韵","f":"七言律诗","c":["四海皇皇无所归，梦魂常绕故园飞。","海山不羡学居易，华表留言笑令威。","毛落难寻苏子节，囊空犹有老莱衣。","静思二十年间事，扰扰纷纷尽觉非。"]},{"t":"丁亥过沙井和移剌子春韵二首 其一","f":"七言律诗","c":["科登甲乙战文围，吾子才名予独知。","巢许身心君易乐，萧曹勋业我难为。","有恒得见实无憾，知己相逢未忍离。","携手河梁重话旧，胡然羞和子卿诗。"]},{"t":"丁亥过沙井和移剌子春韵二首 其二","f":"七言律诗","c":["行藏俯仰且随时，缊袍怀珠人未知。","燕雀既群难立志，凤凰不至拟胡为。","可嗟世态频更变，何奈人生多别离。","莫忘天山风雪里，湛然驼背和君诗。"]},{"t":"王屋道中","f":"七言律诗","c":["胜克河中号令齐，神兵入自太行西。","昏昏烟锁天坛暗，漠漠云埋王屋低。","风软却教冰泛水，寒轻还使雪成泥。","行吟想像覃怀景，多少梅花坼玉溪。"]},{"t":"和解天秀韵","f":"七言律诗","c":["猛士弯弓挽六钧，长驱入汴政施仁。","前朝运谢山河古，圣世时亨雨露新。","未遇自甘焚绿绮，知音不必惜阳春。","朝廷将下搜贤诏，莫恋烟霞老此身。"]},{"t":"用万松老人韵作十诗寄郑景贤 其一","f":"五言律诗","c":["毡庐同抵足，谈道月西沈。","议论馨香发，文章蕴藉深。","正便边氏腹，不上谪仙襟。","自得逍遥意，何须泊邓林。"]},{"t":"用万松老人韵作十诗寄郑景贤 其二","f":"五言律诗","c":["丰城三尺剑，神气尚埋沈。","确论穿杨的，生机劈筈深。","天真贮便腹，浩气塞征襟。","伫看泽天下，清风冠士林。"]},{"t":"用万松老人韵作十诗寄郑景贤 其三","f":"五言律诗","c":["破船无渗漏，流水不能沈。","雾锁青山秀，花藏古径深。","白云陪野兴，晴月洗烦襟。","绝后重苏息，飞花枯木林。"]},{"t":"用万松老人韵作十诗寄郑景贤 其四","f":"五言律诗","c":["隐隐三星出，依依片月沈。","鹤飞辽海阔，猿啸楚山深。","柳色云沾袖，芦花雪满襟。","普天秋意露，一叶坠梧林。"]},{"t":"用万松老人韵作十诗寄郑景贤 其五","f":"五言律诗","c":["玄珠罗帐密，寒鼎篆烟沈。","翡翠疏帘隔，琉璃古殿深。","本来无垢体，何必拂尘襟。","斫却蟾中桂，方成假若林。"]},{"t":"用万松老人韵作十诗寄郑景贤 其六","f":"五言律诗","c":["鳌饵不须针，聊将玉线沈。","须弥犹未大，渤海岂为深。","悟后牛穿鼻，迷时马有襟。","弋人何所慕，幽鸟在嵩林。"]},{"t":"用万松老人韵作十诗寄郑景贤 其七","f":"五言律诗","c":["个事不容针，迷途自陆沈。","西天三步远，东海一杯深。","凉月盛玄钵，轻云剪素襟。","曹溪无一滴，波浪沸禅林。"]},{"t":"用万松老人韵作十诗寄郑景贤 其八","f":"五言律诗","c":["流波无放荡，死水暮平沈。","机尽方钩隐，纶空正钓深。","赤心休惜口，青眼好开襟。","误捉溪中月，人人似翰林。"]},{"t":"用万松老人韵作十诗寄郑景贤 其九","f":"五言律诗","c":["梦觉方知错，生平自屈沈。","涤尘千㵎外，遗照乱松深。","柳带缝穿屣，荷衣缀破襟。","寂寥选佛味，何似宴琼林。"]},{"t":"用万松老人韵作十诗寄郑景贤 其十","f":"五言律诗","c":["渔家何足好，乘兴一钩沈。","路僻苍苔滑，舟横古渡深。","小晴掀箬笠，微雨整蓑襟。","梦断知何处，寒潮没晚林。"]},{"t":"万松老人真赞","f":"曲","c":["每恨恒山，不逢圭老。","四众同缘，万松亲到。"]},{"t":"赠万松老人琴谱诗一首","f":"七言律诗","c":["良夜沈沈人未眠，桐君横膝叩朱弦。","千山皓月和烟静，一曲悲风对谱传。","故纸且教遮具眼，声尘何碍污幽禅。","元来底许真消息，不在弦边与指边。"]},{"t":"寄曲阳戒坛会首大师","f":"七言律诗","c":["四众飞书请万松，不消弹指已成功。","灯笼證据真谈辨，露柱承当不耳聋。","梵行细推无处所，戒坛须信塞虚空。","无为济物谁能悉，惟有东垣月拂风。"]},{"t":"和王巨川韵","f":"七言律诗","c":["圣驾徂征率百工，貔貅亿万入关中。","周秦气焰如云变，唐汉繁华扫地空。","灞水尚存官柳绿，骊山惟有驿尘红。","天兵一鼓长安克，千里威声震陕东。"]},{"t":"释奠","f":"七言律诗","c":["多士云奔奠上下，释迦遗像亦行城。","旌幢错落休迷色，钟磬铿锵岂在声。","宣父素心施有政，能仁深意契无生。","儒流释子无相讽，礼乐因缘尽假名。"]},{"t":"和移剌子春见寄五首 其一","f":"七言律诗","c":["四海皇皇足俊贤，浪陪扶日上青天。","且图约法三章定，宁羡浮荣六印悬。","润色吾术惟恐后，扶持天下敢为先。","过情声闻予深耻，可笑虚名到处传。"]},{"t":"和移剌子春见寄五首 其二","f":"七言律诗","c":["生遇干戈我不辰，十年甘分作俘臣。","施仁发政非无据，论道经邦自有人。","圣世规模能法古，污俗习染得维新。","英雄已入吾皇彀，从此无人更问津。"]},{"t":"和移剌子春见寄五首 其三","f":"七言律诗","c":["且喜朝廷先正名，林泉隐逸总公卿。","群雄一遇风云会，万国咸观日月明。","丹凤固应潜乱世，白麟自今出升平。","伫看北阙垂温诏，夜半前席进贾生。"]},{"t":"和移剌子春见寄五首 其四","f":"七言律诗","c":["举世寥寥识我谁，未学弓矢愧由基。","衰年有幸弹三乐，盛世无才出六奇。","弃物且存光海量，散材获用荷天私。","微臣自忖将何报，信笔裁成颂德诗。"]},{"t":"和移剌子春见寄五首 其五","f":"七言律诗","c":["邂逅沙城识子初，天山风雪醉吟馀。","文章光焰君堪羡，节操仪刑我不如。","曲蘖乡中前进士，风波堆里老中书。","他年归去无相弃，同到闾山旧隐居。"]},{"t":"寄移剌国宝","f":"七言律诗","c":["昔年萍迹旅京华，曾到风流国宝家。","居士为予常吃素，先生爱客必烹茶。","明窗挥麈谈禅髓，净几焚香顶佛牙。","回首五年如一梦，梦中不觉过流沙。"]},{"t":"寄景贤一十首 其一","f":"七言律诗","c":["龙冈能觅淡中欢，心与孤云自在闲。","琴阮生涯事松菊，诗书活计老丘山。","叩弦声自无中出，得句思从天外还。","踏破化工无尽藏，闲人受用亦非悭。"]},{"t":"寄景贤一十首 其二","f":"七言律诗","c":["龙冈、漆水两交欢，纵意琴书做老闲。","未得一言安海内，已输三箭定天山。","肯容诗思妨心慧，岂使声尘碍耳还。","信手拈来无不是，清风明月有何悭。"]},{"t":"寄景贤一十首 其三","f":"七言律诗","c":["人间聚散妄悲欢，何似林泉遁世闲。","十载残躯游瀚海，积年归梦绕闾山。","空岩猿鹤招予往，满架琴书伴我还。","多谢龙冈怜老隐，新诗酬酢路无悭。"]},{"t":"寄景贤一十首 其四","f":"七言律诗","c":["弦索词章且助欢，羡渠临老得安闲。","琴歌爱子弹秋水，佳句服君仰泰山。","声古调凄真可听，辞雄韵险实难还。","先难后易今方省，名士襟怀本不悭。"]},{"t":"寄景贤一十首 其五","f":"七言律诗","c":["宦情触处不成欢，未得浮生半日闲。","荐鹗有书惭北海，泽民无术愧东山。","琴书习气终难忘，岩麓荒园怎得还。","卜隐龙冈成老伴，肯教诗思笔头悭。"]},{"t":"寄景贤一十首 其六","f":"七言律诗","c":["广文怜我失清欢，每著琴书伴我闲。","痛忆金声并玉振，酷思流水与高山。","诗坛吝啬犹深闭，琴债迁延未肯还。","一状如今都领过，龙冈须破两重悭。"]},{"t":"寄景贤一十首 其七","f":"七言律诗","c":["琴书吾子尽幽欢，随分消磨日月闲。","佳句典刑传四海，水仙声韵彻三山。","每惭木李投君去，却得琼瑶报我还。","从此龙冈开廪藏，徽边笔下更无悭。"]},{"t":"寄景贤一十首 其八","f":"七言律诗","c":["世间何事最为欢，争似能偷忙里闲。","得遇夜晴须对月，每逢春盛强登山。","无钱沽酒和衣典，图利吟诗倍本还。","绮语千章琴百曲，莫教风月笑人悭。"]},{"t":"寄景贤一十首 其九","f":"七言律诗","c":["我与先生久已欢，而今皆愿老来闲。","同舟载棹醉观月，并辔骑驴饱看山。","绮句缀成连谱换，纯音弹了着诗还。","琴诗此际慵拈出，可怨龙冈为纸悭。"]},{"t":"寄景贤一十首 其十","f":"七言律诗","c":["闲人闲里竟闲欢，未得回光未是闲。","叩道一螺斟巨海，参玄千里望恒山。","但能透镞穿三句，何必拖泥辨八还。","个事人人皆富有，含生休怨释迦悭。"]},{"t":"和景贤韵三首 其一","f":"七言律诗","c":["龙冈便腹尽诗书，落笔云烟我不如。","一纸安书思塞雁，十年归兴忆鲈鱼。","托身医隐君谋妙，委迹儒冠我计疏。","何日相将归故里，翠微深处卜幽居。"]},{"t":"和景贤韵三首 其二","f":"七言绝句","c":["龙冈走笔和清篇，出示珠玑寄湛然。","字古意新看不足，挑灯寒雨夜无眠。"]},{"t":"和景贤韵三首 其三","f":"七言绝句","c":["摩抚疮痍正似医，微君孰肯拯时危。","万金良策悟明主，厚德深仁四海施。"]},{"t":"和李世荣韵","f":"五言律诗","c":["异同谁足据，俯仰且随缘。","居士难联句，梅轩却解禅。","无云皆皓月，何处不青天。","话到忘言处，迢迢夜不眠。"]},{"t":"和景贤十一首 其一","f":"七言律诗","c":["龙冈居士得贤君，闻道贤君增所闻。","节操鹓雏捐鼠饵，风神野鹤立鸡群。","只知辅嗣能谈易，谁识相如善属文。","拟欲赞君言不尽，区区微意见诗云。"]},{"t":"和景贤十一首 其二","f":"七言律诗","c":["天下奇才郑使君，清名不使世人闻。","五车书笥独穷理，三峡词源迥出群。","未得开怀重话旧，常思抵足共论文。","自从一识龙冈老，馀子纷纷不足云。"]},{"t":"和景贤十一首 其三","f":"七言律诗","c":["一圣龙飞敢择君，嗟予潦倒尚无闻。","苍生未识鸿鹄志，皓首甘游麋鹿群。","黄雀已归奚望报，彩禽飞去不能文。","龙冈特慰孤穷闷，时有新诗报我云。"]},{"t":"和景贤十一首 其四","f":"七言律诗","c":["试和新诗寄郑君，无言谈道不闻闻。","治心更索捐中道，养性浑如鞭后群。","玄语谆谆非是说，真书历历不关文。","儒生刺教嫌虚诞，得意忘言孔子云。"]},{"t":"和景贤十一首 其五","f":"七言律诗","c":["文章自愧不如君，敢以玄言渎所闻。","有道居尘何异俗，无心入兽不惊群。","重玄消息无多子，半纸功名值几文。","回首死生犹是幻，自馀何足更云云。"]},{"t":"和景贤十一首 其六","f":"七言律诗","c":["十年不遇一相知，恰识龙冈恨见迟。","常爱箕山能洗耳，何堪邻舍效颦眉。","荣枯贵贱难逃数，用舍行藏自有时。","心事纷纷无处说，援毫闲和景贤诗。"]},{"t":"和景贤十一首 其七 感事","f":"七言律诗","c":["万里西来过月氏，初离故国思迟迟。","人情惭愧三须面，人世梳妆半额眉。","田上野夫空叹凤，泽边渔父不伤时。","龙冈本具英雄眼，几倩东风寄我诗。"]},{"t":"和景贤十一首 其八 读唐史有感","f":"七言律诗","c":["林甫滔天圣不知，三郎深恨识卿迟。","尘中妃子春罗袜，钱上开元指甲眉。","七夕殿中祈巧夜，三秋原上摘瓜时。","长天忽见飞来雁，垂泪空吟李峤诗。"]},{"t":"和景贤十一首 其九","f":"七言律诗","c":["李杨相继领台司，兵起渔阳祸已迟。","向昔正怜花解语，而今空忆柳如眉。","心伤桃李初开夜，肠断梧桐半落时。","试问宫中谁第一，三郎犹记谪仙诗。"]},{"t":"和景贤十一首 其十","f":"七言律诗","c":["往来寒暑暗推移，下手修行犹太迟。","迷后徒劳常捏目，悟来何必更扬眉。","宗门淘汰宜穷理，道眼因缘贵识时。","祗为龙冈心猛利，湛然刚写不言诗。"]},{"t":"和景贤十一首 其十一","f":"七言律诗","c":["龙冈医隐本知机，薰莸同盘辨者稀。","廊庙虚名无意恋，林泉夙愿与心违。","羡君绰绰有馀裕，笑我皇皇无所归。","尚忆当年垂钓处，一江烟雨静霏霏。"]},{"t":"和王君玉韵","f":"五言律诗","c":["王孙蒙馈饭，灵辄未扶轮。","自笑孤穷客，谁怜衰病身。","黄沙万馀里，白发一孀亲。","肠断山城月，徘徊照远人。"]},{"t":"过东胜用先君文献公韵二首 其一","f":"七言律诗","c":["荒城萧洒枕长河，古字碑文半灭磨。","青冢路遥人去少，黑山寒重雁来多。","正愁晓雪冰生砚，不忿西风叶坠柯。","偶忆先君旧游处，潸然不奈此情何。"]},{"t":"过东胜用先君文献公韵二首 其二","f":"七言律诗","c":["依然千里旧山河，事改时移随变磨。","巢许家风乌可少，萧曹勋业未为多。","可伤陵变须耕海，不待棋终已烂柯。","翻手荣枯成底事，不如归去入无何。"]},{"t":"过夏国新安县","f":"七言律诗","c":["昔年今日渡松关，车马崎岖行路难。","瀚海潮喷千浪白，天山风吼万林丹。","气当霜降十分爽，月比中秋一倍寒。","回首三秋如一梦，梦中不觉到新安。"]},{"t":"过青冢用先君文献公韵","f":"七言律诗","c":["汉室空成一土丘，至今仍未雪前羞。","不禁出塞涉沙碛，最恨临轩辞冕旒。","幽怨半和青冢月，闲云常锁黑河秋。","滔滔天堑东流水，不尽明妃万古愁。"]},{"t":"过青冢次贾抟霄韵二首 其一","f":"七言律诗","c":["当年遗恨叹昭君，玉貌冰肤染塞尘。","边塞未安嫔侮虏，朝廷何事拜功臣。","朝云雁唳天山外，残日猿悲黑水滨。","十里东风青冢道，落花犹似汉宫春。"]},{"t":"过青冢次贾抟霄韵二首 其二","f":"七言律诗","c":["延寿丹青本诳君，和亲犹未敛胡尘。","穹庐自恨嫔戎主，泉壤相逢愧汉臣。","玉骨已消青冢底，香魂犹绕黑河滨。","愁云暗锁天山路，野草闲花也怨春。"]},{"t":"再用韵以美抟霄之德","f":"七言律诗","c":["去岁云川始见君，澄澄胸次净无尘。","山南第一圭璋士，冀北无双柱石臣。","万里云松斜谷外，千竿水竹渭河滨。","他年归隐重相访，无影林间别有春。"]},{"t":"再用韵自叹行藏","f":"七言律诗","c":["箕裘家世忝先君，惭愧飘萧两鬓尘。","自古山河归圣主，从今廊庙弃愚臣。","常思卧隐云乡外，肯效行吟泽国滨。","驿使不来人已老，江南谁寄一枝春。"]},{"t":"再用韵感古","f":"七言律诗","c":["宣尼名教本尊君，贼子干常犯跸尘。","鹿失嬴秦无令主，鼎分炎汉有能臣。","宋朝南渡尤天水，辽室东倾罪海滨。","回首兴亡都莫问，不如沈醉瓮头春。"]},{"t":"再用韵唱玄","f":"七言律诗","c":["重玄不惜说知君，又恐重添眼里尘。","临济喝中分主客，洞山言下辨君臣。","持铃普化摇空里，垂钓华亭没水滨。","勘破遮般闲伎俩，铁林花发劫前春。"]},{"t":"过云川和刘正叔韵","f":"七言律诗","c":["西域风尘汗漫游，十年辜负旧渔舟。","曾观八阵云奔速，亲见三川席卷收。","烟锁居延苏子恨，云埋青冢汉家羞。","深思篱下西风醉，谁羡班超万里侯。"]},{"t":"过云中和张伯坚韵","f":"七言律诗","c":["一扫氐羌破吐浑，群雄悉入北朝吞。","自怜西域十年客，谁识东丹八叶孙。","射虎将军皆建节，飞龙天子未更元。","我惭才略非良器，封禅书成不敢言。"]},{"t":"过云中和张仲先韵","f":"七言律诗","c":["致泽君民本不难，言轻无用愧偷安。","十年潦倒功何在，三径荒凉盟已寒。","岩下藏名思傅说，林间谈道谒丰干。","挂冠神武当归去，自有夔龙辅可汗。"]},{"t":"过云中和王正夫韵","f":"七言律诗","c":["白雪阳春寡和音，谁人解听没弦琴。","诗书事业真堪笑，刀笔功名未可钦。","不信西天三步远，焉知东海一杯深。","元来佛法无多子，何必嵩山谒少林。"]},{"t":"过白登和李振之韵","f":"七言律诗","c":["十年沦落困边城，今日龙钟返帝京。","运拙不须求富贵，时危何处取功名。","腾骧谁识孙阳骥，俊逸深思支遁鹰。","客里逢君赠佳句，知音相见眼偏明。"]},{"t":"过天城和靳泽民韵","f":"七言律诗","c":["西征扈从过龙庭，误得东州浪播名。","琴阮因缘真有味，诗书事业拙谋生。","咄嗟兴废悲三叹，倏忽荣枯梦一惊。","何日解官归旧隐，满园松菊小庵清。"]},{"t":"过武川赠仆散令人","f":"七言律诗","c":["班姬流落到而今，闻道翻身入道林。","歌扇舞裙忘旧业，药炉经卷半新吟。","闲眠白昼三杯醉，静对青松一曲琴。","更看他年栖隐处，蓬山楼阁五云深。"]},{"t":"过燕京和陈秀玉韵五首 其一","f":"七言律诗","c":["回首亲朋半土丘，嗟予十稔浪西游。","半生兵革慵开眼，一纸功名暗点头。","下士笑予谋计拙，至人知我谓心忧。","再行不惮风沙恶，鹤迹云踪任去留。"]},{"t":"过燕京和陈秀玉韵五首 其二","f":"七言律诗","c":["君恩犹未报山丘，自笑遐方汗漫游。","客过玉关惊白发，要游金谷觅苍头。","冷官待罪予为歉，陋巷居贫君不忧。","犹望道行泽四海，敢辞沙漠久淹留。"]},{"t":"过燕京和陈秀玉韵五首 其三","f":"七言律诗","c":["狐死曾闻尚首丘，悲予去国十年游。","昆崙碧耸日落处，渤海西倾天尽头。","君子云亡真我恨，斯文将丧是吾忧。","尚期晚节回天意，隐忍龙庭且强留。"]},{"t":"过燕京和陈秀玉韵五首 其四","f":"七言律诗","c":["馀生不得乐林丘，犹忆丁年选胜游。","几帙残编聊映眼，一张衲被且蒙头。","貔貅已报西门役，柱石犹怀东顾忧。","自料荒疏成弃物，菟裘归计乞封留。"]},{"t":"过燕京和陈秀玉韵五首 其五","f":"七言律诗","c":["空惊沧海变陵丘，白昼分明梦里游。","除妄楔边重出楔，求真头上更安头。","亨通富贵刚生喜，苦恼悲愁强作忧。","斫断葛藤闲伎俩，系驴橛子不须留。"]},{"t":"还燕京题披云楼和诸士大夫韵","f":"七言律诗","c":["闲上披云第一重，离离禾黍汉家宫。","窗开青锁招晴色，帘捲银钩揖晓风。","好梦安排诗句里，闲愁分付酒杯中。","静思二十年间事，聚散悲欢一梦同。"]},{"t":"和威宁珍上人韵","f":"七言律诗","c":["十载西游志已灰，南征又自大梁回。","扶持佛日惭无力，赞翊皇风愧不才。","旧约未能林下去，新诗常寄日边来。","何时杖履烟霞里，一笑伸眉得共陪。"]},{"t":"和李德修韵","f":"七言律诗","c":["明明圣主万邦君，神武彫弓挽六钧。","时有逸人游阙下，更无骚客吊江滨。","衣冠师古承殷辂，历日随时建夏寅。","厚德深仁施万世，巍然一代典谟新。"]},{"t":"和吕飞卿韵","f":"七言律诗","c":["旧说飞卿词翰全，风神浑似晋名贤。","吟诗校子三十里，押韵输君一着先。","笔迹查牙森似戟，词源浩瀚注如川。","好诗好字独予得，准备携将帝里传。"]},{"t":"再用韵赠国华","f":"七言律诗","c":["学道宗儒难两全，湛然深许国华贤。","儒门已悟如心恕，道藏能穷象帝先。","似海词源涵万水，如鲸饮量吸长川。","而今一识君侯面，始信清名不浪传。"]},{"t":"谢飞卿饭","f":"七言律诗","c":["一鞭羸马渡天山，偶到云川暂解鞍。","独守空房方丈稳，更无薄酒一杯残。","诗书半蠹绝来客，釜甑生尘笑冷官。","赖有觉非怜野拙，长须为我馈盘餐。"]},{"t":"再用韵记西游事","f":"七言律诗","c":["河中花木蔽春山，烂赏东风纵宝鞍。","留得晚瓜过腊半，藏来秋果到春残。","亲尝芭榄宁论价，自酿蒲萄不纳官。","常叹不才还有幸，滞留遐域得佳餐。"]},{"t":"再用韵赠抟霄","f":"七言律诗","c":["凛凛风神白玉山，罢游鹰犬逞金鞍。","瑶琴高挂么弦绝，羲易频翻断简残。","息念如僧还有发，忘形见客似无官。","伽陀诵罢炉薰冷，一钵疏羹当晓餐。"]},{"t":"再用韵谢非熊召饭","f":"七言律诗","c":["行尽遐陬万里山，十年飘泊困征鞍。","春风燕语归心切，夜月猿啼客梦残。","圣世因时行夏正，愚臣嗜数愧春官。","谁知贤帅开青眼，扫洒西庵召我餐。"]},{"t":"再用韵唱玄","f":"七言律诗","c":["藤条击破铁围山，倒跨白牛不鞲鞍。","讲疏僧归经卷乱，坐禅人起佛灯残。","为学未必如为道，选佛从教胜选官。","百事湛然都不念，祗知渴饮与饥餐。"]},{"t":"再用韵","f":"七言律诗","c":["云山叠叠复云山，瘦马芦鞭矮面鞍。","瀚海去程千驿远，扬州归梦五更残。","尘缘淡处应忘世，逸兴浓时好解官。","二顷良田何必觅，春山笋蕨亦供餐。"]},{"t":"和抟霄韵代水陆疏文因其韵为诗十首 其一","f":"七言律诗","c":["资生无畏济人深，便见能仁六度心。","尘世捐财矜苦厄，寒林洒饭拔幽沈。","既临巨海钩神物，试叩洪钟伺好音。","今日湛然攀旧例，珠缨休惜挂祗林。"]},{"t":"和抟霄韵代水陆疏文因其韵为诗十首 其二","f":"七言律诗","c":["新朝威德感人深，渴望云霓四海心。","东夏再降烽火灭，西门一战塞烟沈。","颙观颁朔施仁政，伫待更元布德音。","好放湛然云水去，庙堂英俊正如林。"]},{"t":"和抟霄韵代水陆疏文因其韵为诗十首 其三","f":"七言律诗","c":["论道西庵爱慕深，推诚片片露丹心。","瑶琴莫抚相如引，宝鼎休焚韩寿沈。","花气浑如三角串，松风全似五弦音。","清谈终日忘归思，不觉昏鸦噪晚林。"]},{"t":"和抟霄韵代水陆疏文因其韵为诗十首 其四","f":"七言律诗","c":["五派分流道愈深，尘中谁识本来心。","穿心土椀元无漏，没底胶船却不沈。","山色水光呈妙相，鸟啼猿啸露圆音。","云霞活计无求饱，何事狂童作肉林。"]},{"t":"和抟霄韵代水陆疏文因其韵为诗十首 其五","f":"七言律诗","c":["前生未了妄缘深，薄宦相萦负夙心。","只见渊明能印弃，谁知居士解舟沈。","穷通荣辱皆真梦，毁誉称讥尽假音。","中隐冷官闲况味，归心无日不山林。"]},{"t":"和抟霄韵代水陆疏文因其韵为诗十首 其六","f":"七言律诗","c":["居士才微学未深，静思宁不愧中心。","难忘北海千钟酒，虚负西庵一炷沈。","绮语效颦赓险韵，瑶琴学步鼓纯音。","此番公案休拈出，祗恐相传入笑林。"]},{"t":"和抟霄韵代水陆疏文因其韵为诗十首 其七","f":"七言律诗","c":["新诗欬玉起予深，独有抟霄我许心。","真迹居尘聊俯仰，高名与世任浮沈。","同成雅会清茶话，共赏枯桐白雪音。","他日归休约何处，燕山参谒万松林。"]},{"t":"和抟霄韵代水陆疏文因其韵为诗十首 其八","f":"七言律诗","c":["贤帅文章蕴藉深，云川倾盖便同心。","掀髯谈道檠灯灺，抵足论文塞月沈。","有眼句中君得意，无弦琴上我知音。","乘舟误捉波中月，莫学当年李翰林。"]},{"t":"和抟霄韵代水陆疏文因其韵为诗十首 其九","f":"七言律诗","c":["浪迹西游岁月深，临风谁识湛然心。","斯文将丧儒风歇，真智难明佛日沈。","佳茗暂尝轰雪浪，正声聊作鼓雷音。","年来逸兴十分切，准备求真入道林。"]},{"t":"和抟霄韵代水陆疏文因其韵为诗十首 其十","f":"七言律诗","c":["渔矶旧隐荻花深，尘世宁忘昔日心。","两岸清风单舸稳，满江明月一钩沈。","饥来煮稻无兼味，醉后鸣榔笑五音。","闲卧烟蓑春梦断，不知潮起没青林。"]},{"t":"寄贾抟霄乞马乳","f":"七言律诗","c":["天马西来酿玉浆，革囊倾处酒微香。","长沙莫吝西江水，文举休空北海觞。","浅白痛思琼液冷，微甘酷爱蔗浆凉。","茂陵要洒尘心渴，愿得朝朝赐我尝。"]},{"t":"谢马乳复用韵二首 其一","f":"七言律诗","c":["生涯箪食与囊浆，空忆朝回衣惹香。","笔去馀才犹可赋，酒来多病不能觞。","松窗雨细琴书润，槐馆风微枕簟凉。","正与文君谋此渴，长沙美湩送予尝。"]},{"t":"谢马乳复用韵二首 其二","f":"七言律诗","c":["肉食从容饮酪浆，差酸滑腻更甘香。","革囊旋造逡巡酒，桦器频倾潋滟觞。","顿解老饥能饱满，偏消烦渴变清凉。","长沙严令君知否，只许诗人合得尝。"]},{"t":"赠抟霄笔","f":"七言律诗","c":["一札霜毫缀玉枝，管城家世出东涯。","锋端有口能谈景，纸上无声解写诗。","免向江淹求彩管，莫学班氏弃毛锥。","赠君聊助文房用，赋就离骚寄我知。"]},{"t":"再用韵寄抟霄二首 其一","f":"七言律诗","c":["玉立堂堂紫桂枝，云川中隐寓天涯。","风神萧散能谈道，格调清新解作诗。","鄙论我甘蒙酱瓿，雄材君已露囊锥。","澄澄胸次人谁识，祗有清风明月知。"]},{"t":"再用韵寄抟霄二首 其二","f":"七言律诗","c":["斫倒松筠节外枝，谁言法界有边涯。","筌蹄意尽闲周易，脂粉情忘束诂诗。","去岁生涯犹说剑，今年活计更捐锥。","威音那畔真消息，试问瞿昙也不知。"]},{"t":"再用韵别非熊","f":"七言律诗","c":["灵木垂芳桂两枝，非熊佳誉动西涯。","倦听琴阮嫌狂客，饱看经书厌小诗。","成德羡君垂竹帛，虚名嗟我类刀锥。","会难别易堪惆怅，何日重来谁得知。"]},{"t":"爱子金柱索诗","f":"七言律诗","c":["文献阴功绝比伦，昆虫草木尽承恩。","我为北阙十年客，汝是东丹九世孙。","致主泽民宜务本，读书学道好穷源。","他时辅翼英雄主，珥笔承明策万言。"]},{"t":"赠贾非熊抟霄一首","f":"七言律诗","c":["二陆尊贤擅美声，月评难弟亦难兄。","西庵挥麈谈三界，北观携琴论五行。","休道酒仙无太白，须知诗伯有飞卿。","奇人辐辏君门下，占断西州好士名。"]},{"t":"和李振之二首 其一","f":"七言律诗","c":["半纸功名未可呈，无心何处不安生。","十年沧海尘空起，百岁黄粱梦乍惊。","旧径既荒松菊在，丹诚不变鬓髯更。","年来渐有升平望，每恨栖鸡半夜鸣。"]},{"t":"和李振之二首 其二","f":"七言律诗","c":["酷忆遥山寸碧呈，归耕何日乐馀生。","蝇营得失都无念，狗苟荣枯总若惊。","客梦觉来家万里，诗声吟罢月三更。","溟鹏本有冲天志，直待三年再一鸣。"]},{"t":"非熊兄弟饯予之燕再用振之韵","f":"七言律诗","c":["艺逢知己敢相呈，几夜论文喜气生。","笔阵我甘三舍退，诗坛君使四筵惊。","公初倾盖冬将半，予拟乘轺岁欲更。","特与幽人助行色，一声寒角隔烟鸣。"]},{"t":"和连国华三首 其一","f":"七言律诗","c":["岁月如流走兔乌，求真可惜费工夫。","深源到底忘根柢，至道元来贵拙愚。","真理不空宜具眼，太虚无面莫添须。","直须稳坐长安好，切忌途中认画图。"]},{"t":"和连国华三首 其二","f":"七言律诗","c":["安得长绳系日乌，天涯老却旧耕夫。","林泉放旷输君乐，沙漠淹留笑我愚。","虎战每惊涉虎尾，龙飞不得采龙须。","文章毕竟成何事，富贵元知不可图。"]},{"t":"和连国华三首 其三","f":"七言律诗","c":["月上南枝啼夜乌，悲歌弹铗叹征夫。","愁边逐日看周易，梦里随风谒太愚。","纵有征尘遮两眼，却无惭色上三须。","真人已应千年运，伫待河清再出图。"]},{"t":"连国华饯予出天山因用韵","f":"七言律诗","c":["十年不得舞衣班，一忆江南胆欲寒。","黄犬候来秋自老，白云望断信何难。","军中得句常横槊，客里伤心每据鞍。","游子未归情几许，天山风雪正漫漫。"]},{"t":"还燕和美德明一首","f":"七言律诗","c":["纷纷世态眩荣华，静里乾坤本不哗。","琴阮生涯聊自适，诗书事业更何加。","但期圣德泽天下，敢惜馀生寄海涯。","可笑燕然旧游客，倚楼悲我客程赊。"]},{"t":"又和橙子梅韵","f":"七言律诗","c":["可笑人心自短长，谁知个事不囊藏。","化成橙子舌耽味，幻作梅英鼻觉香。","金卵似真随变灭，冰魂元假却芬芳。","唯心识破同根旨，何必临风再举扬。"]},{"t":"和竹林一禅师韵","f":"七言律诗","c":["富贵无心羡五侯，随时俯仰浪西游。","断无事业留千古，静看英雄横九州。","白雁纵传遐域信，黄华却负故园秋。","苍生未济归何益，一见吾山一度羞。"]},{"t":"西庵上人住夏禁足以诗戏之","f":"七言律诗","c":["触处无非选佛堂，东风何处避春光。","郡人无足充千界，大地绝尘塞四方。","举步踢翻沧海月，转身踏破白云乡。","快须击碎闲家具，说向西庵笑一场。"]},{"t":"送韩浩然用马朝卿韵","f":"七言律诗","c":["开怀樽俎笑谈倾，未暇论文君已行。","富贵涂亨渠易致，诗篇韵险我难赓。","已成倾盖金兰友，安用沾襟儿女情。","准拟秋深迓归骑，一樽浊酒远相迎。"]},{"t":"戊子喜雨用马朝卿韵二首 其一","f":"七言律诗","c":["酷暑炎炎正不禁，一声雷震酿轻阴。","救回南亩十分旱，变作西郊三日霖。","遍野桑畴青幄密，连天麦垄绿云深。","王孙喜雨登楼宴，贳酒黄垆解带金。"]},{"t":"戊子喜雨用马朝卿韵二首 其二","f":"七言律诗","c":["生死轮回苦莫禁，不如学道惜分阴。","船乘没底聊相渡，云出无心强作霖。","不死乡中灵草异，长生劫外紫云深。","茅山道士真堪笑，虚费工夫炼五金。"]},{"t":"戊子饯非熊仍以吕望磻溪图为赠","f":"七言律诗","c":["昨夜白麻降日边，文章领袖远朝天。","遥思御座分香赐，更想龙庭命席前。","白面书生酬夙志，黑头边帅领新权。","非熊应笑非熊老，八十犹然钓渭川。"]},{"t":"和宋子玉韵","f":"七言律诗","c":["勇将谋臣满玉京，吾侪袖手待升平。","荆榛至道常嗟我，柱石中原岂舍卿。","日下有人叨肉食，云中高士振诗鸣。","思君兴味如梅渴，海印那能知此情。"]},{"t":"和李邦瑞韵二首 其一","f":"七言律诗","c":["陇右奇才冠士林，万言良策起予深。","泽民致主倾丹恳，邀利沽名匪素心。","我伴簿书无好思，君陪风月有閒吟。","他年共纳林泉下，茅屋松窗品正音。"]},{"t":"和李邦瑞韵二首 其二","f":"七言律诗","c":["谢君千里远相寻，倾盖交欢气义深。","笔砚生涯无异志，金兰气味本同心。","挥毫解赋登高句，缓轸能弹对竹琴。","此去鳞鸿知有便，临风无吝寄芳音。"]},{"t":"和邦瑞韵送奉使之江表","f":"七言律诗","c":["驲骑翩翩出玉京，金符一插照人明。","莫忘北阙龙飞志，要识南陬舌情。","布袖来朝无骑乘，锦衣归去不徒行。","升仙桥畔增春色，郡守传呼接长卿。"]},{"t":"和王正之韵三首 其一","f":"七言律诗","c":["洪才硕德两相宜，雅操真堪据凤池。","富贵未终随梦变，功名何在值时危。","奇词解吐万言策，敏思能吟七步诗。","但倩东风轻着力，摩天鹏翼若云垂。"]},{"t":"和王正之韵三首 其二","f":"七言律诗","c":["自惭不解告嘉谟，十载韬藏僻一隅。","巨海洪深容弃物，新朝宽厚用愚夫。","亨时嘉会千年少，圣主雄材万代无。","文物规模皆法古，伫看明诏起真儒。"]},{"t":"和王正之韵三首 其三","f":"楚辞体","c":["皇天辅德本无亲，乐道奚忧甑满尘。","道泰小人当屏斥，时屯君子自经纶。","浮云富贵元千变，昨梦繁华得几春。","遇不遇兮皆是命，吾侪休羡锦衣新。"]},{"t":"祝忘忧居士寿","f":"七言律诗","c":["酷似燕山窦十郎，灵椿初老桂枝芳。","两朝厚遇垂千稔，一日清明满四方。","玉佩丁东照兰省，斑衣摇曳悦萱堂。","他年参到平常处，便是长生不老乡。"]},{"t":"蜡梅二首 其一","f":"七言律诗","c":["越岭仙姿迥异常，洞庭春染六铢裳。","枝横碧玉天然瘦，蕾破黄金分外香。","反笑素英浑淡抹，却嫌红艳太浓妆。","临风浥此蔷薇露，醉墨淋漓寄渺茫。"]},{"t":"蜡梅二首 其二","f":"七言律诗","c":["冰姿梦里慕姚黄，滴蜡凝酥别样妆。","生妒白红太浓淡，懒施朱粉自芬芳。","寒英深染蔷薇露，冷艳微熏笃耨香。","受用清绝恣吟绕，惜花一念未全忘。"]},{"t":"谢禅师□公寄闾山紫玉","f":"七言律诗","c":["方外闲人天一隅，因风寄我紫云腴。","起予妙理欺欢伯，涤我枯肠压酪奴。","琥珀精神浑彷佛，葡萄滋味较锱铢。","禅师远弃桃源路，日日寻山摘此无。"]},{"t":"和郑寿之韵","f":"七言律诗","c":["圣主龙飞日月新，微才忝预股肱臣。","民财已阜钱如水，驲骑长闲塞不尘。","威镇西陲输定远，宴开东阁慕平津。","何如收拾琴书去，林下衣冠作舜民。"]},{"t":"寄沙井刘子春","f":"七言律诗","c":["寄语沙城老故人，别来嬴得鬓边尘。","马蹄踏破关中月，新句吟空河表春。","名利相萦余有歉，琴书自乐子非贫。","何时策杖君家去，再试渊明漉酒巾。"]},{"t":"和琴士苗兰韵","f":"七言律诗","c":["徒步南来爱陆机，公馀邂逅似相期。","高山韵吼千岩木，流水声号半夜陂。","圣德宛如歌治化，南风犹似抚疮痍。","曲终声散无人会，撩我高吟一首诗。"]},{"t":"和人韵二首 其一","f":"七言律诗","c":["西域诸蕃古未知，来生远过禹封畿。","名山准拟金泥检，古塞无劳羽檄飞。","世乐讵能敌静乐，蓑衣到底胜朝衣。","年来痛忆闾山景，月照茅亭水一围。"]},{"t":"和人韵二首 其二","f":"七言律诗","c":["干戈未敛我伤神，自恨虚名误此身。","否德讵能师百辟，微才安可步三辰。","箕裘谩叹青毡旧，勋业空惊白发新。","安得夔龙立廊庙，扶持尧舜济斯民。"]},{"t":"和武川严亚之见寄五首 其一","f":"七言律诗","c":["当年西域未知名，四海无人识晋卿。","扈从銮舆三万里，谟谋凤阙九重城。","衣冠异域真余志，礼乐中原乃我荣。","何日功成归旧隐，五湖烟浪乐馀生。"]},{"t":"和武川严亚之见寄五首 其二","f":"七言律诗","c":["亚之平水久驰名，壮岁题桥慕长卿。","厌世德风如偃草，惊人诗价比连城。","功名未立不为慊，仁义能行亦足荣。","此理幽微人不识，莫言儒道拙谋生。"]},{"t":"和武川严亚之见寄五首 其三","f":"七言律诗","c":["今年又得亚之诗，每叹风云会遇迟。","拙运且淹童子役，雄才宜作帝王师。","羡君笔下挥千字，知子胸中蕴六奇。","静对西风和新句，凄然南望动深思。"]},{"t":"和武川严亚之见寄五首 其四","f":"七言律诗","c":["误忝纶恩斗印悬，乏才羞到玉墀前。","劾奸封事梦犹诤，许国忠诚老益坚。","仁政发从天北畔，捷音来自海西边。","从今率土沾王化，礼乐车书共一天。"]},{"t":"和武川严亚之见寄五首 其五","f":"七言律诗","c":["寥落龙沙寄此生，情钟我辈岂无情。","参商管鲍贤朋友，南北机云好弟兄。","莲叶飘香思晚浦，梅花飞雪梦春城。","故园日夜归心切，未济斯民不敢行。"]},{"t":"己丑过鸡鸣山","f":"七言律诗","c":["三年四度过鸡鸣，我仆徘徊马倦登。","寂寞柴门空有舍，萧条山寺静无僧。","残花溅泪千程别，啼鸟伤心百感生。","今古兴亡都莫问，穹庐高卧醉腾腾。"]},{"t":"寄天山周敬之","f":"七言律诗","c":["当年倾盖识君初，烂饮天山驻使车。","秋去安仁空有赋，雁来公瑾又无书。","林峦红叶知人老，篱落黄花亦我疏。","为向天涯道岑寂，强吟新句附双鱼。"]},{"t":"邦瑞乞访亲因用其韵","f":"七言律诗","c":["干戈扰扰战交侵，一纸安书值万金。","凡子生还愁未解，萱堂仙去恨尤深。","涕零倚木西风怨，肠断闻铃夜雨淋。","养老送终真有憾，号天如割望云心。"]},{"t":"和李邦瑞韵","f":"七言律诗","c":["赵老名言本两忘，庭前空有柏苍苍。","西江吸尽慵开口，北载添来亦括囊。","明月清风何所碍，落花流水不相妨。","须知居士元无病，底用千年旧药方。"]},{"t":"过清源赠法云禅师","f":"七言律诗","c":["汾水禅师个里人，杖藜寻我过清源。","半盂红果情何厚，一盏青灯话细论。","山水景中君适意，兵戈堆里我消魂。","他年相约云深处，松竹萧萧静掩门。"]},{"t":"赠五台长老","f":"七言律诗","c":["高冈登陟马玄黄，落日西风过晋阳。","道士忻迎捧林果，儒冠远迓挈壶浆。","五台强壮头如雪，开化轻安鬓未霜。","谁会二师深密意，赵州元不下禅床。"]},{"t":"赠蒲察元帅七首 其一","f":"七言律诗","c":["闲骑白马思无穷，来访西城绿发翁。","元老规模妙天下，锦城风景压河中。","花开杷榄芙渠淡，酒泛葡萄琥珀浓。","痛饮且图容易醉，欲凭春梦到卢龙。"]},{"t":"赠蒲察元帅七首 其二","f":"曲","c":["积年飘泊困边尘，闲过西隅谒故人。","忙唤贤姬寻器皿，便呼辽客奏筝?。","葡萄架底葡萄酒，杷榄花前杷榄仁。","酒酽花繁正如许，莫教辜负锦城春。"]},{"t":"赠蒲察元帅七首 其三","f":"七言律诗","c":["主人知我怯金觞，特为先生一改堂。","细切黄橙调蜜煎，重罗白饼糁糖霜。","几盘绿橘分金缕，一椀清茶点玉香。","明日辞君向东去，这些风味几时忘。"]},{"t":"赠蒲察元帅七首 其四","f":"七言律诗","c":["使君排饭宴南溪，不枉从君鸟鼠西。","春薤旋浇浓鹿尾，腊糟微浸软驼蹄。","丝丝鱼脍明如玉，屑屑鸡生烂似泥。","白面书生知此味，从今更不嗜黄齑。"]},{"t":"赠蒲察元帅七首 其五","f":"七言律诗","c":["筵前且尽主人心，明烛厌厌饮夜深。","素袖佳人学汉舞，碧髯官妓拨胡琴。","轻分茶浪飞香雪，旋擘橙杯破软金。","五夜欢心犹未已，从教斜月下疏林。"]},{"t":"赠蒲察元帅七首 其六","f":"七言律诗","c":["主人开宴醉华胥，一派丝篁沸九衢。","黯紫葡萄垂马乳，轻黄杷榄灿牛酥。","金波泛蚁斟欢伯，雪浪浮花点酪奴。","忙里偷闲谁若此，西行万里亦良图。"]},{"t":"赠蒲察元帅七首 其七","f":"七言律诗","c":["闲乘羸马过蒲华，又到西阳太守家。","玛瑙瓶中簪乱锦，琉璃钟里泛流霞。","品尝春色批金橘，受用秋香割木瓜。","此日幽欢非易得，何妨终老住流沙。"]},{"t":"庚辰西域清明","f":"七言律诗","c":["清明时节过边城，远客临风几许情。","野鸟间关难解语，山花烂漫不知名。","葡萄酒熟愁肠乱，玛瑙杯寒醉眼明。","遥想故园今好在，梨花深院鹧鸪声。"]},{"t":"用盐政姚德宽韵","f":"七言律诗","c":["乃祖开元柱石臣，云孙髣髴玉麒麟。","从来德炙舆人口，此日恩沾圣世春。","欲草荐书学北海，未开东阁愧平津。","而今且试调羹手，伫看沙堤继旧尘。"]},{"t":"用昭禅师韵二首 其一","f":"七言律诗","c":["银钩全似赵周臣，诗比黄华格调新。","道眼点开言外句，禅心说破劫前春。","山中跛挈无为客，林下逍遥自在人。","不犯清波垂钓处，卧龙随手出龙津。"]},{"t":"用昭禅师韵二首 其二","f":"七言绝句","c":["圣德洋洋雨露零，虫鱼草木总欢荣。","妖氛敛祸尧风扇，外道消声佛日明。"]},{"t":"和薛正之见寄","f":"七言律诗","c":["贤臣圣主正时遭，建策龙庭莫惮劳。","大壑波深翻巨鲤，高空风顺遇鸿毛。","一番制度新才术，百代文章旧雅骚。","勉力自强宜不息，功名何啻泰山高。"]},{"t":"乞扇","f":"七言律诗","c":["屈眴圆裁白玉盘，幽人自剪素琅玕。","全胜织女绞绡帕，高出湘妃玳瑁斑。","座上清风香细细，怀中明月净团团。","愿祈数柄分居士，颠倒阴阳九夏寒。"]},{"t":"壬午西域河中游春十首 其一","f":"七言律诗","c":["幽人呼我出东城，信马寻芳莫问程。","春色未如华藏富，湖光不似道心明。","土床设馔谈玄旨，石鼎烹茶唱道情。","世路崎岖太尖险，随高逐下坦然平。"]},{"t":"壬午西域河中游春十首 其二","f":"七言律诗","c":["三年春色过边城，萍迹东归未有程。","细细和风红杏落，涓涓流水碧湖明。","花林啜茗添幽兴，绿亩观耕称野情。","何日要荒同入贡，普天钟鼓乐清平。"]},{"t":"壬午西域河中游春十首 其三","f":"七言律诗","c":["春雁楼边三两声，东天回首望归程。","山青水碧伤心切，李白桃红照眼明。","几树绿杨摇客恨，一川芳草惹羁情。","天兵几日归东阙，万国欢声贺太平。"]},{"t":"壬午西域河中游春十首 其四","f":"七言律诗","c":["河中二月好踏青，且莫临风叹客程。","溪畔数枝红杏浅，墙头半点小桃明。","谁知西域逢佳景，始信东君不世情。","圆沼方池三百所，澄澄春水一时平。"]},{"t":"壬午西域河中游春十首 其五","f":"七言律诗","c":["二月河中草木青，芳菲次第有期程。","花藏径畔春泉碧，云散林梢晚照明。","含笑山桃还似识，相亲水鸟自忘情。","遐方且喜丰年兆，万顷青青麦浪平。"]},{"t":"壬午西域河中游春十首 其六","f":"七言律诗","c":["异域春郊草又青，故园东望远千程。","临池嫩柳千丝碧，倚槛妖桃几点明。","丹杏笑风真有意，白云送雨太无情。","归来不识河中道，春水潺潺满路平。"]},{"t":"壬午西域河中游春十首 其七","f":"七言律诗","c":["四海从来皆弟兄，西行谁复叹行程。","既蒙倾盖心相许，得遇知音眼便明。","金玉满堂违素志，云霞千顷适高情。","庙堂自有夔龙在，安用微生措治平。"]},{"t":"壬午西域河中游春十首 其八","f":"七言律诗","c":["寓迹尘埃且乐生，垂天六翮敛鹏程。","无缘未得风云会，有幸能瞻日月明。","出处随时全道用，穷通逐势叹人情。","凭谁为发丰城剑，一扫妖氛四海平。"]},{"t":"壬午西域河中游春十首 其九","f":"七言律诗","c":["不如归去乐馀龄，百岁光阴有几程。","文史三冬输曼倩，田园二顷忆渊明。","宾朋冷落绝交分，亲戚团栾说话情。","植杖耘耔聊自适，笑观南亩绿云平。"]},{"t":"壬午西域河中游春十首 其十","f":"七言律诗","c":["衰翁老矣倦功名，繁简行军笑李程。","牛粪火熟石炕暖，蛾连纸破瓦窗明。","水中漉月消三毒，火里生莲屏六情。","野老不知天子力，讴歌鼓腹庆升平。"]},{"t":"游河中西园和王君玉韵四首 其一","f":"七言律诗","c":["万里东皇不失期，园林春老我来迟。","漫天柳絮将飞日，遍地梨花半谢时。","异域风光特秀丽，幽人佳句自清奇。","临风畅饮题玄语，方信无为无不为。"]},{"t":"游河中西园和王君玉韵四首 其二","f":"七言律诗","c":["清明出郭赴幽期，千里江山丽日迟。","花叶不飞风定后，香尘微敛雨馀时。","彫镌冰玉诗尤健，挥扫龙蛇字愈奇。","好字好诗独我得，不来赓和拟胡为。"]},{"t":"游河中西园和王君玉韵四首 其三","f":"七言律诗","c":["异域逢君本不期，湛然深恨识君迟。","清诗厌世光千古，逸笔惊人自一时。","字老本来遵雅淡，吟成元不尚新奇。","出伦诗笔服君妙，笑我区区亦强为。"]},{"t":"游河中西园和王君玉韵四首 其四","f":"七言律诗","c":["风云佳遇未能期，自是鱼龙上钓迟。","岩穴潜藏难遁世，尘嚣俯仰且随时。","百年富贵真堪叹，半纸功名未足奇。","伴我琴书聊自适，生涯此外更何为。"]},{"t":"河中游西园四首 其一","f":"七言律诗","c":["河中春晚我邀宾，诗满云笺酒满巡。","对景怕看红日暮，临池羞照白头新。","柳添翠色侵凌草，花落馀香著莫人。","且著新诗与芳酒，西园佳处送残春。"]},{"t":"河中游西园四首 其二","f":"七言律诗","c":["河中风物出乎伦，闲命金兰玉斝巡。","半笑梨花琼脸嫩，轻颦杨柳翠眉新。","衔泥紫燕先迎客，偷蕊黄蜂远趁人。","日日西园寻胜概，莫教辜负客城春。"]},{"t":"河中游西园四首 其三","f":"七言律诗","c":["几年萍梗困边城，闲步西园试一巡。","圆沼印空明镜瑩，芳莎藉地翠茵新。","幽禽有意如留客，野卉多情解笑人。","屈指知音今有几，与谁同享瓮头春。"]},{"t":"河中游西园四首 其四","f":"七言律诗","c":["金鼓銮舆出陇秦，驱驰八骏又西巡。","千年际会风云异，一代规模宇宙新。","西域兵来擒伪主，东山诏下起幽人。","股肱元首明良世，高拱垂衣寿万春。"]},{"t":"河中春游有感五首 其一","f":"七言律诗","c":["西胡搆室未全终，又见颓垣绕故墉。","绿苑连延花万树，碧堤回曲水千重。","不图舌鼓谈非马，甘分躬耕学卧龙。","粝食粗衣聊自足，登高舒啸乐吾慵。"]},{"t":"河中春游有感五首 其二","f":"七言律诗","c":["异域河中春欲终，园林深密锁颓墉。","东山雨过空青叠，西苑花残乱翠重。","杷榄碧枝初着子，葡萄绿架已缠龙。","等閒春晚芳菲歇，叶底翩翩困蝶慵。"]},{"t":"河中春游有感五首 其三","f":"七言律诗","c":["坎止流行以待终，幽人射隼上高墉。","穷通世路元多事，艰险机关有几重。","百尺苍枝藏病鹤，三冬蛰窟闭潜龙。","琴书便结忘言友，治圃耘蔬自养慵。"]},{"t":"河中春游有感五首 其四","f":"七言律诗","c":["西域渠魁运已终，天兵所指破金墉。","崇朝驲骑驰千里，一夜捷书奏九重。","鞭策不须施犬马，庙堂良算足夔龙。","北窗高卧薰风里，尽任他人笑我慵。"]},{"t":"河中春游有感五首 其五","f":"七言律诗","c":["重玄叩击数年终，大道难窥万仞墉。","旧信不来青鸟远，故山犹忆白云重。","自知勋业输雏凤，且学心神似老龙。","忙里偷闲谁似我，兵戈横荡得疏慵。"]},{"t":"过闾居河四首 其一","f":"七言律诗","c":["河冰春尽水无声，靠岸钩鱼羡击冰。","乍远南州如梦蝶，暂游北海若飞鹏。","隋堤柳絮风何处，越岭梅花信莫凭。","试暂停鞭望西北，迎风羸马不堪乘。"]},{"t":"过闾居河四首 其二","f":"七言律诗","c":["北方寒凛古来称，亲见阴山冻鼠冰。","战斗檐楹翻铁马，穷通棋势变金鹏。","五车经史都无用，一鹗书章谁可凭。","安得冲天畅予志，云舆六驭信风乘。"]},{"t":"过闾居河四首 其三","f":"七言律诗","c":["一圣龙飞德足称，其亡凛凛涉春冰。","千山风烈来从虎，万里云垂看举鹏。","尧舜徽猷无阙失，良平妙算足依凭。","华夷混一非多日，浮海长桴未可乘。"]},{"t":"过闾居河四首 其四","f":"七言律诗","c":["自愧声名无可称，贤愚混世炭和冰。","窃盐仓鼠初成蝠，喷浪溟鲲未化鹏。","卖剑学耕食粗遣，买山归老价难凭。","秋江月满西风软，何日扁舟独自乘。"]},{"t":"感事四首 其一","f":"七言律诗","c":["富贵荣华若聚沤，浮生浑似水东流。","仁人短命嗟颜氏，君子怀疾叹伯牛。","未得鸣珂游帝阙，何能骑鹤上扬州。","几时摆脱闲缰锁，笑傲烟霞永自由。"]},{"t":"感事四首 其二","f":"七言律诗","c":["当年元拟得封侯，一误儒冠入士流。","赫赫凤鸾捐腐鼠，区区蛮触战蜗牛。","未能离欲超三界，必用麾旄混九州。","致主泽民元素志，陈书自荐我无由。"]},{"t":"感事四首 其三","f":"七言律诗","c":["得不欣欣失不忧，依然不改旧风流。","深藏凤璧无投鼠，好蓄龙泉候买牛。","山寺幽居思少室，梅花归梦绕扬州。","萱堂温凊十年阙，负米供亲愧仲由。"]},{"t":"感事四首 其四","f":"七言律诗","c":["人不知予我不尤，濯缨何必拣清流。","良材未试聊耽酒，利器深藏俟割牛。","旧政欲传新令尹，新朝不识旧荆州。","眉山云迈归商路，痛恪新诗寄子由。"]},{"t":"壬午元日二首 其一","f":"五言律诗","c":["西域风光换，东方音问疏。","屠苏聊复饮，郁垒不须书。","旧岁昨宵尽，新年此日初。","客中今十载，孀母信何如。"]},{"t":"壬午元日二首 其二","f":"七言律诗","c":["万里西征出玉关，诗无佳思酒瓶乾。","萧条异域年初换，坎轲穷途腊已残。","身过碧云游极乐，手遮东日望长安。","年光迅速如流水，不管诗人两鬓斑。"]},{"t":"过沁园有感","f":"七言律诗","c":["昔年曾赏沁园春，今日重来迹已陈。","水外无心修竹古，雪中含恨瘦梅新。","垣颓月榭经兵火，草没诗碑覆劫尘。","羞对覃怀昔时月，多情依旧照行人。"]},{"t":"用刘正叔韵","f":"七言律诗","c":["参叩松轩积有年，光尘融泄一愚贤。","视民每羡如刍狗，治国常思烹小鲜。","只道牛边休执杖，谁知琴上亦忘弦。","湛然稍异香山老，不学空门不学仙。"]},{"t":"西域家人辈酿酒戏书屋壁","f":"七言律诗","c":["西来万里尚骑驴，旋借葡萄酿绿醑。","司马捲衣亲涤器，文君挽袖自当炉。","元知沽酒业缘重，何奈调羹手段无。","古昔英雄初未遇，生涯或亦隐屠沽。"]},{"t":"西域从王君玉乞茶因其韵七首 其一","f":"七言律诗","c":["积年不啜建溪茶，心窍黄尘塞五车。","碧玉瓯中思雪浪，黄金碾畔忆雷芽。","卢仝七椀诗难得，谂老三瓯梦亦赊。","敢乞君侯分数饼，暂教清兴绕烟霞。"]},{"t":"西域从王君玉乞茶因其韵七首 其二","f":"七言律诗","c":["厚意江洪绝品茶，先生分出蒲轮车。","雪花滟滟浮金蕊，玉屑纷纷碎白芽。","破梦一杯非易得，搜肠三椀不能赊。","琼瓯啜罢酬平昔，饱看西山插翠霞。"]},{"t":"西域从王君玉乞茶因其韵七首 其三","f":"七言律诗","c":["高人惠我岭南茶，烂赏飞花雪没车。","玉屑三瓯烹嫩蕊，青旗一叶碾新芽。","顿令衰叟诗魂爽，便觉红尘客梦赊。","两腋清风生坐榻，幽欢远胜泛流霞。"]},{"t":"西域从王君玉乞茶因其韵七首 其四","f":"七言律诗","c":["酒仙飘逸不知茶，可笑流涎见曲车。","玉杵和云舂素月，金刀带雨剪黄芽。","试将绮语求茶饮，特胜春衫把酒赊。","啜罢神清淡无寐，尘嚣身世便云霞。"]},{"t":"西域从王君玉乞茶因其韵七首 其五","f":"曲","c":["长笑刘伶不识茶，胡为买锸谩随车。","萧萧暮雨云千顷，??春雷玉一芽。","建郡深瓯吴地远，金山佳水楚江赊。","红炉石鼎烹团月，一椀和香吸碧霞。"]},{"t":"西域从王君玉乞茶因其韵七首 其六","f":"七言律诗","c":["枯肠搜尽数杯茶，千卷胸中到几车。","汤响松风三昧手，雪香雷震一枪芽。","满囊垂赐情何厚，万里携来路更赊。","清兴无涯腾八表，骑鲸踏破赤城霞。"]},{"t":"西域从王君玉乞茶因其韵七首 其七","f":"七言律诗","c":["啜罢江南一椀茶，枯肠历历走雷车。","黄金小碾飞琼屑，碧玉深瓯点雪芽。","笔阵陈兵诗思勇，睡魔卷甲梦魂赊。","精神爽逸无馀事，卧看残阳补断霞。"]},{"t":"和冲霄韵五首 其一","f":"七言律诗","c":["垂亡圣道赖君鸣，坎轲休嗟道不行。","须信诗魔降笔阵，好将酒战破愁城。","滔滔秋水如人志，薄薄闲云似世情。","一举冲霄知有日，垂天万里看鹏程。"]},{"t":"和冲霄韵五首 其二","f":"七言律诗","c":["古今兴废不堪听，宠辱都如梦一惊。","韬略欣然推后进，琴书足以了馀生。","既知物物头头是，谁问朝朝暮暮情。","散尽迷云何所有，一轮秋月普天明。"]},{"t":"和冲霄韵五首 其三","f":"七言律诗","c":["天涯索寞正穷秋，衰草寒烟无尽头。","叶底哀蛩空促织，云间征雁祗供愁。","酪浆满引浇羊胛，粝食随缘荐鹿脩。","试暂回光乐真觉，人閒万法一时收。"]},{"t":"和冲霄韵五首 其四","f":"七言律诗","c":["星星华发镜中惊，好赋归欤接淅行。","重位宁贪高一品，故园无惮远千程。","晴天花络春山色，落日松和秋水声。","无恙闾峰三百寺，遨游吟啸老馀生。"]},{"t":"和冲霄韵五首 其五","f":"七言律诗","c":["古木残阳映矮岗，雁行天际写秋光。","霜蓑带雨添愁色，晚菊和风送冷香。","浊酒三年浑未试，黄粮九月得初尝。","龙沙且喜身强健，南望幽人天一方。"]},{"t":"和冲霄韵五首 其六","f":"七言律诗","c":["不见高阳旧酒徒，临风惆怅几踟蹰。","无穷真味思焦尾，有限浮生叹白驹。","德望服人输二陆，文章重世愧三苏。","散材潦倒浑无用，空作昂藏一丈夫。"]},{"t":"和冲霄十月桃花韵二首 其一","f":"七言律诗","c":["桃源仙子忆刘郎，不惮严冬雨雪凉。","红雨已先初夏落，妖魂重对小春芳。","冷侵绿萼刚舒脸，寒彻朱衣强喷香。","谁向荒园慰萧索，数枝无语映斜阳。"]},{"t":"和冲霄十月桃花韵二首 其二","f":"七言律诗","c":["春生秋杀乃天常，来往推迁炎与凉。","晚节正当阴气塞，穷冬忽见小桃芳。","岂知卜枣能成实，僭与江梅敢并香。","自愧备员调鼎鼐，不知何事谬阴阳。"]},{"t":"用薛正之韵","f":"七言律诗","c":["无德惭为天下先，湖山归计好加鞭。","霜深尚有篱边菊，风劲全无叶底蝉。","三弄瑶琴歌素月，一樽浊酒醉苍烟。","凤池分付夔龙去，万顷潇湘属湛然。"]},{"t":"和景贤见寄","f":"七言律诗","c":["龙冈参透后三三，髣髴前人何所惭。","妙笔照人惊老字，新诗入手想清谈。","尘中名利予难出，梦里荣华君不耽。","准拟归时便归去，闾山珍重旧禅庵。"]},{"t":"用刘润之乞冠韵","f":"五言律诗","c":["隐逸养幽慵，飘萧两鬓蓬。","角巾折暮雨，醉帽落秋风。","避暑挂石上，衔杯鹿酒中。","忘机任真率，露顶向王公。"]},{"t":"西域河中十咏 其一","f":"五言律诗","c":["寂寞河中府，连甍及万家。","葡萄亲酿酒，杷榄看开花。","饱啖鸡舌肉，分餐马首瓜。","人生唯口腹，何碍过流沙。"]},{"t":"西域河中十咏 其二","f":"五言律诗","c":["寂寞河中府，临流结草庐。","开樽倾美酒，掷网得新鱼。","有客同联句，无人独看书。","天涯获此乐，终老又何如。"]},{"t":"西域河中十咏 其三","f":"五言律诗","c":["寂寞河中府，遐荒僻一隅。","葡萄垂马乳，杷榄灿牛酥。","酿春无输课，耕田不纳租。","西行万馀里，谁谓乃良图。"]},{"t":"西域河中十咏 其四","f":"五言律诗","c":["寂寞河中府，生民屡有灾。","避兵开邃穴，防水筑高台。","六月常无雨，三冬却有雷。","偶思禅伯语，不觉笑颜开。"]},{"t":"西域河中十咏 其五","f":"五言律诗","c":["寂寞河中府，颓垣绕故城。","园林无尽处，花木不知名。","南岸独垂钓，西畴自省耕。","为人但知足，何处不安生。"]},{"t":"西域河中十咏 其六","f":"五言律诗","c":["寂寞河中府，西流绿水倾。","冲风磨旧麦，悬碓杵新粳。","春月花浑谢，冬天草再生。","优游聊卒岁，更不望归程。"]},{"t":"西域河中十咏 其七","f":"五言律诗","c":["寂寞河中府，清欢且自寻。","麻笺聊写字，苇笔亦供吟。","伞柄学钻笛，宫门自斲琴。","临风时适意，不负昔年心。"]},{"t":"西域河中十咏 其八","f":"五言律诗","c":["寂寞河中府，西来亦偶然。","每春忘旧闰，随月出新年。","强策浑心竹，难穿无眼钱。","异同无定据，俯仰且随缘。"]},{"t":"西域河中十咏 其九","f":"五言律诗","c":["寂寞河中府，声名昔日闻。","城隍连畎亩，市井半丘坟。","食饭秤斤卖，金银用麦分。","生民怨来后，箪食谒吾君。"]},{"t":"西域河中十咏 其十","f":"五言律诗","c":["寂寞河中府，遗民自足粮。","黄橙调蜜煎，白饼糁糖霜。","漱旱河为雨，无衣垄种羊。","一从西到此，更不忆吾乡。"]},{"t":"西域和王君玉诗二十首 其一","f":"七言律诗","c":["年来深欲买湖山，贫病难酬绢五千。","归去不从陶令请，知音未遇孟尝贤。","排愁器具思欢伯，送老生涯乏货泉。","惟有诗魂常伴我，閒吟陶写个中玄。"]},{"t":"西域和王君玉诗二十首 其二","f":"七言律诗","c":["一发燕然晓日边，寒云叠叠乱山千。","万重沙漠犹逢友，十室荒村亦有贤。","留客芳樽思北海，惊人奇语忆南泉。","思量万事多浑错，勉力轮锤好扣玄。"]},{"t":"西域和王君玉诗二十首 其三","f":"七言律诗","c":["君侯乘兴写佳篇，我得琼琚价倍千。","妙笔一挥能草圣，新诗独惠过称贤。","半瓶浊酒斟琼斝，七椀清茶泛玉泉。","万里西行真我幸，逢君时复一谈玄。"]},{"t":"西域和王君玉诗二十首 其四","f":"七言律诗","c":["健羡金鞍美少年，盈门剑客列三千。","须知执德元非德，况是无贤敢自贤。","不解弯弓射石虎，谁能击剑跃龙泉。","黑头勋业今何在，壮岁功成愧谢玄。"]},{"t":"西域和王君玉诗二十首 其五","f":"七言律诗","c":["云龙相感本乎天，会合君臣岁一千。","西伯已亡谁老老，卜商何在肯贤贤。","鹓雏未必轻餐鼠，蚯蚓犹知下饮泉。","巧拙是非无定据，到头谁解辨黄玄。"]},{"t":"西域和王君玉诗二十首 其六","f":"七言律诗","c":["奔走红尘积有年，深思雪涧竹竿千。","谁能世上全三乐，好向林间伴七贤。","笔下风生诗似锦，瓮头春涨酒如泉。","诗成酒罢寂无事，净几明窗诵太玄。"]},{"t":"西域和王君玉诗二十首 其七","f":"七言律诗","c":["竹径风来自破禅，修篁青剑叶垂千。","烂吟风月元无碍，高卧烟霞未是贤。","迷处无由逃绊锁，悟来何处不林泉。","纵横触目皆真理，坐卧经行鸟路玄。"]},{"t":"西域和王君玉诗二十首 其八","f":"七言律诗","c":["无灭无生不论年，谁誇桃熟岁三千。","休将真宰陪司命，莫使明星动进贤。","有道不妨居闹市，无心奚碍酌贪泉。","何能远遁尘嚣去，且向人间养素玄。"]},{"t":"西域和王君玉诗二十首 其九","f":"七言律诗","c":["从他豪俊领时权，指顾貔貅数百千。","碌碌馀生甘养拙，明明圣代岂遗贤。","且图混世啜醨酒，勿谓濯缨弃浊泉。","莫道无为云便了，有为何处不逢玄。"]},{"t":"西域和王君玉诗二十首 其十","f":"七言律诗","c":["浮生瞬息度流年，唐汉兴亡不半千。","清洁采薇输二子，英雄济世有三贤。","未能海上寻芝草，且向尘中泛醴泉。","醉兴陶陶略相似，无何乡里亦通玄。"]},{"t":"西域和王君玉诗二十首 其十一","f":"七言律诗","c":["成败兴亡事可怜，劳生扰扰几千千。","调心莫若先离欲，治世无如不尚贤。","小褚岂能怀大器，短绳那得汲深泉。","直须箭透威音外，不用无为不用玄。"]},{"t":"西域和王君玉诗二十首 其十二","f":"七言律诗","c":["得得清欢乐自然，不辞去国客程千。","翻腾旧案因君玉，唱和新诗有景贤。","每遇开樽邀素月，常因盥手掬寒泉。","衰翁自揣何多幸，未死中间乐此玄。"]},{"t":"西域和王君玉诗二十首 其十三","f":"七言律诗","c":["几回午枕不成眠，幽鸟关关近数千。","安世不知安世计，隐居常慕隐居贤。","几行石榻围松径，一簇茅斋绕涧泉。","挂起西轩风似水，閒将羲易索幽玄。"]},{"t":"西域和王君玉诗二十首 其十四","f":"七言律诗","c":["农隐生涯乐自天，药畦香垄仅盈千。","蝇营累世真堪笑，狗苟劳生未若贤。","带月扶犁耕暮野，冲云荷锸拨春泉。","耘耔馀暇蓬窗底，独抱遗经考至玄。"]},{"t":"西域和王君玉诗二十首 其十五","f":"七言律诗","c":["闲闲个事本明圆，一念才兴路八千。","生死既知皆是幻，功名犹恋岂能贤？","兴来畅饮斟晴月，醉后高歌枕碧泉。","触处逢渠何所碍，不玄玄处亦玄玄。"]},{"t":"西域和王君玉诗二十首 其十六","f":"七言律诗","c":["物物头头总是禅，观音应现化身千。","杜门晏坐无伤道，遁世幽居也是贤。","祗为看山开翠竹，偶因煎茗汲清泉。","灵云检点真堪笑，不见桃花不悟玄。"]},{"t":"西域和王君玉诗二十首 其十七","f":"七言律诗","c":["蓑衣狂脱暮江边，一醉宁论价十千。","老矣冯唐何所往，归与陶令最为贤。","灵苗细细初盈圃，春水涓涓渐满泉。","酒醒梦回无个事，澄心忘虑体三玄。"]},{"t":"西域和王君玉诗二十首 其十八","f":"七言律诗","c":["九重阊阖列群官，曳佩鸣珂及万千。","云水偷将属野叟，功名回施与时贤。","好凭定慧超三界，不恋轮回没九泉。","迅速光阴莫虚度，回光返照静参玄。"]},{"t":"西域和王君玉诗二十首 其十九","f":"七言律诗","c":["不学经书不说禅，谁论芥子纳三千。","忘形诗句追先觉，适意琴书慕昔贤。","白雪阳春吟雅调，高山流水奏鸣泉。","平生受用元无尽，参透真空未是玄。"]},{"t":"西域和王君玉诗二十首 其二十","f":"七言律诗","c":["鲰生诗僻慕诗仙，乱缀狂吟数百千。","浅陋妄言嗤俊哲，清新绮语愧先贤。","摧残吟鬓星星发，倾倒词源浑浑泉。","韵险言穷无可说，祇凭此句露深玄。"]},{"t":"和杨彦广韵","f":"七言律诗","c":["三台须要趁琵琶，知己相逢两会家。","雕斲勿伤石内玉，纵横须放火中花。","探玄浑似三杯酒，清兴何消七椀茶。","谁识湛然端的处，差徭随分纳些些。"]},{"t":"题平阳李君实此君轩","f":"七言律诗","c":["环榻森森荫好凉，此君风味讵能忘。","虚心悄悄生来劲，直节亭亭老更刚。","虽与蓬蒿均雨露，本同松菊傲风霜。","主人雅志元堪尚，物以群分类以方。"]},{"t":"西域有感","f":"七言律诗","c":["落日城头鸦乱啼，秋风原上马频嘶。","雁行南去潇湘北，萍迹东来鸟鼠西。","百尺栋梁谁着价，三春桃李自成蹊。","功名到底成何事，烂饮玻璃醉似泥。"]},{"t":"早行","f":"七言律诗","c":["马驼残梦过寒塘，低转银河夜已央。","雁迹印开沙岸月，马蹄踏破板桥霜。","汤寒卯酒两三盏，引睡新诗四五章。","古道迟迟四十里，千山清晓日苍凉。"]},{"t":"自叙","f":"七言律诗","c":["信流乘坎过西天，钵里吞针亦偶然。","只道一花刚点额，不知三子暗登肩。","既来此世难逃数，且应前生未了缘。","俗眼见时难放过，并赃陈首万松轩。"]},{"t":"西域元日","f":"七言律诗","c":["凌晨随分备樽罍，辟疫屠苏饮一杯。","迂叟不令书郁垒，痴儿刚要画钟馗。","新愁又逐东风至，旧信难随春日来。","又向边城添一岁，天涯飘泊几时回。"]},{"t":"西域寄中州禅老","f":"七言律诗","c":["吾师道化震清都，奔逸绝尘我不如。","近日虚传三岛信，几年不得万松书。","宗门淘汰犹嫌少，习气薰蒸尚未除。","惆怅天涯沦落客，临风不是忆鲈鱼。"]},{"t":"蒲华城梦万松老人","f":"七言律诗","c":["华亭髣髴旧时舟，又见吾师钓直钩。","只道梦中重作梦，不知愁底更添愁。","曾参活句垂青眼，未得生侯已白头。","撇下尘嚣归去好，谁能骑鹤上扬州。"]},{"t":"寄巨川宣抚","f":"七言律诗","c":["历数兴亡掌上看，提兵一战领清官。","马前草诏珠玑润，纸上挥毫风雨寒。","昔日谈禅明法界，而今崇道倡香坛。","诸行百辅君都占，潦倒鲰生何处安。"]},{"t":"寄南塘老人张子真","f":"七言律诗","c":["张侯风味讵能忘，黄米曾令我一尝。","抵死解官违北阙，达生遁世钓南塘。","知来何假灵龟兆，作赋能陈瑞鹤祥。","岂是西边无土物，不如诗句寄东阳。"]},{"t":"观瑞鹤诗卷独子进治书无诗","f":"七言律诗","c":["丁年兰省识君初，缓步鸣珂游帝都。","象简常陪天仗立，玉骢曾使禁臣趋。","只贪殢酒长安市，不肯题诗瑞应图。","我念李侯端的意，大都好事不如无。"]},{"t":"寄德明","f":"七言律诗","c":["英侯志节本凌云，尚自飘零故国尘。","有道且同麋鹿友，谈玄能说虎狼仁。","幸然不全饱死鬼，可惜空吟笑杀人。","弥勒下生何太早，莫随邪见说无因。"]},{"t":"才卿外郎五年止惠一书","f":"七言律诗","c":["五年只得一书题，路远山长梦亦迷。","睡老黑甜酣顺北，冷官清淡泊辽西。","羡人得志能如虎，笑我乏才粗效鸡。","伫看天兵旋北阙，从今不用玉关泥。"]},{"t":"寄清溪居士秀玉","f":"七言律诗","c":["鹪鹩犹欠一枝栖，不得燕山半土犁。","时复有琴歌碧玉，年来无梦绕清溪。","数行文字聊遮眼，半纸功名苦噬脐。","回首故人今健否，馀生甘老碧云西。"]},{"t":"戏秀玉","f":"七言律诗","c":["清溪掀倒打油房，五卫凋零三径荒。","未信塞翁嗟失马，须知禦寇觅亡羊。","东湖菡萏从君赏，西域蒲萄输我尝。","各在天涯会何日，临风休忘老髯郎。"]},{"t":"寄张子闻","f":"七言律诗","c":["忆昔携琴论太玄，湛然初识子闻贤。","回头葱岭仍千里，分手松轩已五年。","东望卢龙倾玉表，西来青鸟阙金笺。","几时重会燕山道，一曲临风奏水仙。"]},{"t":"寄用之侍郎","f":"七言律诗","c":["蓬莱怜我寄芳笺，劝我无忘仁义先。","几句良言甜似蜜，数行温语煖于绵。","从来谁识龟毛拂，到底难调胶柱弦。","用我必行周孔教，舍予不负万松轩。"]},{"t":"和正卿待制韵","f":"七言律诗","c":["布袖龙钟两眼尘，丹诚如旧白头新。","暮云西畔犹怀汉，晓日东边才是秦。","酒贱不妨连夜醉，花繁长发四时春。","花繁酒贱无佳思，谁念天涯万里人。"]},{"t":"寄仲文尚书","f":"七言律诗","c":["仲文曾作黑头公，辅弼明时播美风。","治粟货泉流冀北，提刑奸迹屏胶东。","笑观桃李新恩遍，拜扫松楸老计终。","西域故人增喜色，万全良策不谋同。"]},{"t":"雪轩老人邦杰久不惠书作诗怨之","f":"七言律诗","c":["当时倾盖便忘年，别后春风五度迁。","万里西行愁似海，千山东望远如天。","不闻旧信传梅岭，试道新诗怨雪轩。","更上危楼一回首，朝云深处是燕然。"]},{"t":"谢王清甫惠书","f":"七言律诗","c":["西征万里扈銮舆，高阁文章束石渠。","只道昔年周梦蝶，却疑今日我为鱼。","一簪华发垂垂老，两眼黄尘事事疏。","多谢贵人怜远客，东风时有寄来书。"]},{"t":"思亲二首 其一","f":"七言律诗","c":["老母琴书老自娱，吾山侧近结蘧庐。","鬓边尚结辟兵发，箧内犹存教子书。","幼稚已能学土梗，老兄犹未忆鲈鱼。","谁知万里思归梦，夜夜随风到故居。"]},{"t":"思亲二首 其二","f":"七言律诗","c":["昔年不肯卧茅庐，赢得飘萧两鬓疏。","醉里莫知身似蝶，梦中不觉我为鱼。","故园屈指八千里，老母行年六十馀。","何日挂冠辞富贵，少林佳处卜新居。"]},{"t":"思亲用旧韵二首 其一","f":"七言律诗","c":["前年驿骑过西陲，闻道萱堂鬓已丝。","琴断五弦忘旧谱，菊荒三径负疏篱。","筵前戏笑知何日，膝下嬉游看几时。","欲附一书无处寄，愁边空咏满囊诗。"]},{"t":"思亲用旧韵二首 其二","f":"七言律诗","c":["天涯惟仗梦魂归，破梦春风透客帏。","灯下几时哦丽句，筵前何日舞斑衣。","垂垂塞北行人老，得得江南远信稀。","回首故园千万里，倚楼空望白云飞。"]},{"t":"思亲有感","f":"七言律诗","c":["骨肉星分天一涯，萱堂何处忆孤儿。","排愁正赖无声乐，遗兴学吟有眼诗。","丽句日逐三上尔，香醪时复一中之。","前年汉使来西域，笑我星星两鬓丝。"]},{"t":"再过西域山城驿","f":"七言律诗","c":["去年驰传暮城东，夜宿萧条古驿中。","别后尚存柴户疏，重来犹有瓦窗蓬。","主人欢喜铺毛毯，驿吏苍忙洗瓦钟。","但得微躯且强健，天涯何处不相逢。"]},{"t":"辛巳闰月西域山城值雨","f":"七言律诗","c":["冷云携雨到山城，未敢冲泥傍险行。","夜听窗声初变雪，晓窥檐溜已垂冰。","泪凝孤枕三停湿，花结残灯一半明。","又向茅亭留一宿，行云行雨本无情。"]},{"t":"十七日早行始忆昨日立春","f":"七言律诗","c":["客中为客已浃旬，岁杪西边访故人。","杷榄花前风弄麦，葡萄架底雨沾尘。","山城肠断得穷腊，村馆销魂偶忘春。","今日唤回十载梦，一盘凉饼翠蒿新。"]},{"t":"十七日驿中作穷春盘","f":"七言律诗","c":["昨朝春日偶然忘，试作春盘我一尝。","木案初开银线乱，砂瓶煮熟藕丝长。","匀和豌豆揉葱白，细剪蒌蒿点韭黄。","也与何曾同是饱，区区何必待膏梁。"]},{"t":"西域蒲华城赠蒲察元帅","f":"七言律诗","c":["骚人岁杪到君家，土物萧疏一饼茶。","相国传呼扶下马，将军忙指买来车。","琉璃钟里葡萄酒，琥珀瓶中杷榄花。","万里遐方获此乐，不妨终老在天涯。"]},{"t":"乞车","f":"七言律诗","c":["君家轮扁本多能，碧轼朱辕照眼明。","居士此回无马坐，郎官不可辄徒行。","陈遵投辖情何重，灵辄扶轮报敢轻。","别更不须寻土物，载将春色去东城。"]},{"t":"戏作二首 其一","f":"七言律诗","c":["苍颜太守领西阳，招引诗人入醉乡。","屈眴轻衫裁鸭绿，葡萄新酒泛鹅黄。","歌姝窈窕髯遮口，舞妓轻盈眼放光。","野客乍来同见惯，春风不足断人肠。"]},{"t":"戏作二首 其二","f":"七言律诗","c":["太守多才民富强，风光特不让苏杭。","葡萄酒熟红珠滴，杷榄花开紫雪香。","异域丝簧无律吕，胡姬声调自宫商。","人生行乐无如此，何必咨嗟忆故乡。"]},{"t":"过太原南阳镇题紫薇观壁三首 其一","f":"七言律诗","c":["廷臣侍从蔑前驱，道侣忻奔迓使车。","县吏喜闻新号令，村民争认旧中书。","累累山果盈磁钵，薄薄浊醪半瓦壶。","隐逸竞询新事迹，几时迁洛卜新都。"]},{"t":"过太原南阳镇题紫薇观壁三首 其二","f":"七言律诗","c":["吾皇巡狩用三驱，万骑千官奉帝车。","北阙春颁劝农诏，南陬夜奏报捷书。","士民安堵耕盈野，老幼迎郊浆满壶。","伫看要荒归一统，天兵不日破东都。"]},{"t":"过太原南阳镇题紫薇观壁三首 其三","f":"七言绝句","c":["三教根源本自同，愚人迷执强西东。","南阳笑倒知音士，反改莲宫作道宫。"]},{"t":"和松月野衲海上人见寄二诗 其一","f":"七言律诗","c":["游子痴愚莫识家，牛车远弃爱羊车。","汪洋渤海龙宫藏，涓滴波澜坎井蛙。","迷后万言犹是少，悟来千里不为赊。","丛林衲子空行脚，绕遍天涯与海涯。"]},{"t":"和松月野衲海上人见寄二诗 其二","f":"七言绝句","c":["小隐居山何太错，居廛大隐绝忧乐。","山林朝市笑呵呵，为报禅人莫动着。"]},{"t":"梦中偶得","f":"七言绝句","c":["昔年钩隐索幽奇，只向纵横枝上觅。","而今拍手笑呵呵，九九元来九十一。"]},{"t":"贾非熊饯余用其韵","f":"七言律诗","c":["銮辔和鸣车指南，廷臣自愧侍龙骖。","平生慷慨贞夫一，万里别来益友三。","老子此行无酒债，故人归计有禅庵。","白云野衲皆宗匠，道服因缘好细参。"]},{"t":"用李德恒韵","f":"七言律诗","c":["吾子栖迟尚布衣，挑灯弹铗壮歌悲。","阮生固已开青眼，马氏元来有白眉。","运拙巢由真可慕，时亨房杜不难为。","男儿用舍奚忧喜，三径耕耘足自资。"]},{"t":"松月老人寄诗因用元韵","f":"七言律诗","c":["谈禅讲教不知家，芳草漫漫去路差。","杓卜虚声禾老鼓，盘星错认洞山麻。","全无去就论空色，谁有心情说照遮。","松月野僧须荐取，钓鱼人是老玄沙。"]},{"t":"和薛正之韵","f":"七言律诗","c":["天涯倚遍塞城楼，凝望冥鸿空自羞。","礼义不张真我恨，干戈未戢是吾忧。","每怜丹凤能择食，常笑黄能误上钩。","何日解荣偿旧约，扁舟蓑笠五湖游。"]},{"t":"用李邦瑞韵","f":"七言律诗","c":["沈沈北海雪波深，老眼增明寸碧琴。","未得一江活物水，何酬四海望云心。","我生有遇千年会，自愧难为三日霖。","吾子佞然虚赞德，临风羞继谪仙吟。"]},{"t":"寄平阳净名润老","f":"七言律诗","c":["驿骑新从平水回，知公无恙笑颜开。","出门不剪闲庭草，退步从生古殿苔。","玉锁何须絟彩凤，金钩毋得钓黄鲐。","夜深织就无纹锦，但有人来寄个来。"]},{"t":"和郑景贤韵","f":"五言律诗","c":["我爱龙冈老，鸣琴自老成。","未弹白雪曲，先爱水仙声。","但欲合纯古，谁能媚世情。","林泉聊自适，何必献承明。"]},{"t":"和李茂才寄景贤韵","f":"七言律诗","c":["醒时还醉醉还醒，尚忆轮台饮兴清。","瀚海波涛君忍听，天山风雪我难行。","好学慷慨英雄操，毋傲辛酸儿女情。","但得胸中空洒洒，天涯何处不安生。"]},{"t":"除戎堂二首 其一","f":"七言律诗","c":["除戎堂主震威名，一扫尘氛消未萌。","不出户庭成庙算，折冲樽俎有奇兵。","何须公瑾长江险，安用蒙恬万里城。","坐镇大河兵偃息，居延不复塞尘惊。"]},{"t":"除戎堂二首 其二","f":"七言律诗","c":["除戎厅事筑城阿，烽火平安师旅和。","远胜长城欺李绩，徒标铜柱笑伏波。","服心不用七擒策，禦侮何劳三箭歌。","高枕幽窗无一事，西人不敢牧长河。"]},{"t":"寄武川摩诃院圆明老人五首 其一","f":"七言律诗","c":["临行不暇别圆明，禅客机关百变生。","明月清风都不会，落花流水两无情。","只知常谒摩诃院，谁道曾离归化城。","宾主相忘非聚散，笑谈松竹自清声。"]},{"t":"寄武川摩诃院圆明老人五首 其二","f":"七言律诗","c":["新诗入手眼增明，老作机锋太峻生。","略叙寒温闲礼数，过承褒赏假人情。","羡君奋迅超真地，笑我徘徊恋化城。","且喜武川归海若，狂流万派尽消声。"]},{"t":"寄武川摩诃院圆明老人五首 其三","f":"七言律诗","c":["我爱圆明道眼明，简书时复寄鲰生。","谈真辨妄输达士，背正归邪笑世情。","且隐骊珠光万丈，奚贪尺璧价连城。","穹庐高枕无馀事，静听潮轰北海声。"]},{"t":"寄武川摩诃院圆明老人五首 其四","f":"七言律诗","c":["归与不得效渊明，细碎功名误此生。","客里正如闲气味，病来犹有好心情。","冰弦罢品昭君曲，醉墨闲题苏武城。","受用观音法无尽，悲笳风送两三声。"]},{"t":"寄武川摩诃院圆明老人五首 其五","f":"七言律诗","c":["一扇儒风佛日明，舍生从此乐馀生。","高人编简寻长味，衲子林泉称野情。","见道谷绵充廪藏，喜闻流散集京城。","自惭无德毗明主，千里虚名浪播声。"]},{"t":"和李汉臣韵四首 其一","f":"七言律诗","c":["梦中身世鬓垂斑，方士从誇药驻颜。","性海一波涵万象，威音双箭透重关。","圆融活水非生灭，浩渺虚舟任往还。","便好灰心养愚拙，须知大智本闲闲。"]},{"t":"和李汉臣韵四首 其二","f":"五言律诗","c":["龙飞登九五，历数与天膺。","休运绵瓜瓞，功臣列土封。","但期酬子志，奚虑枕吾肱。","千载圣人出，休嗟见有恒。"]},{"t":"和李汉臣韵四首 其三","f":"七言绝句","c":["云中栖隐养雄豪，我爱先生一著高。","鼓腹诗鸣光圣世，雄文端可继离骚。"]},{"t":"和李汉臣韵四首 其四","f":"七言绝句","c":["龙庭十载不知疲，自恨无才出六奇。","欲著涓埃裨海岳，虚名闲誉畏人知。"]},{"t":"和北京张天佐见寄","f":"七言律诗","c":["寓迹龙庭积有年，功名已后祖生鞭。","销金众口嫉居士，好事独君慕湛然。","许远云山分袂别，几时风雨对床眠。","琼华赠我将何报，聊寄江南古样弦。"]},{"t":"戊子继武川刘抟霄韵","f":"七言律诗","c":["不得吾山卧翠霞，西行行遍海之涯。","火风地水虽非我，南北东西总是家。","驿骑亲驰涉弱水，星轺躬驾过流沙。","惟期圣德渐遐迩，不惮龙庭万里赊。"]},{"t":"憩解州邵薛村洪福院","f":"七言律诗","c":["天兵南出武阳东，暂解征鞍憩梵宫。","玉像巍巍红叶捧，金容奕奕碧纱笼。","三秦繁盛如席卷，两晋风流扫地空。","惟有真如元不坏，青山依旧白云中。"]},{"t":"邵薛村道士陈公求诗","f":"七言律诗","c":["玄言圣祖五千言，不说飞升不说仙。","烧药炼丹全是妄，吞霞服气苟延年。","须知三教皆同道，可信重玄也似禅。","趋破异端何足慕，纷纷皆是野狐涎。"]},{"t":"过金山和人韵三绝 其一","f":"七言绝句","c":["金山突兀翠霞高，清赏浑如享太牢。","半夜穹庐伏枕卧，乱云深处野猿号。"]},{"t":"过金山和人韵三绝 其二","f":"七言绝句","c":["金山前畔水西流，一片晴山万里秋。","萝月团团上东嶂，翠屏高挂水晶毬。"]},{"t":"过金山和人韵三绝 其三","f":"七言绝句","c":["金山万壑斗声清，山气空濛弄晚晴。","我爱长天汉家月，照人依旧一轮明。"]},{"t":"谢王巨川惠腊梅因用其韵","f":"七言绝句","c":["雪里冰姿破冷金，前村篱落暗香侵。","令人多谢王公子，分惠幽芳寄好音。"]},{"t":"和王巨川题武成王庙","f":"七言绝句","c":["商辛自底灭亡期，保障全空聚茧丝。","谁识华山归马日，易于渭水钓鱼时。"]},{"t":"又用韵 其一","f":"七言绝句","c":["不遇知音钟子期，逢人未敢理冰丝。","年来忘尽悲风操，空忆伤麟叹凤时。"]},{"t":"又用韵和王巨川 其二","f":"七言律诗","c":["今年扈从入西秦，山色犹如昔日新。","诗思远随秦岭雁，征衣全染灞桥尘。","含元殿坏荆榛古，花萼楼空草木春。","千古兴亡同一梦，梦中多少未归人。"]},{"t":"和景贤七绝 其一","f":"七言绝句","c":["一曲悲风为子弹，穹庐聊复助清欢。","自惭未尽桐君趣，老境方知道愈难。"]},{"t":"和景贤七绝 其二","f":"七言绝句","c":["龙庭十载典南讹，再品朱弦韵未和。","美湩千钟聊当酒，纯音三弄且充歌。"]},{"t":"和景贤七绝 其三","f":"七言绝句","c":["今日边城又见君，试弹流水爇梅魂。","声和塞色金徽润，香散穹庐玉鼎温。"]},{"t":"和景贤七绝 其四","f":"七言绝句","c":["雅操真堪坐庙堂，积年仁义佐贤王。","鸣琴谈笑泽天下，始信斯文天不亡。"]},{"t":"和景贤七绝 其五","f":"七言绝句","c":["桐孙元采峄阳林，万里携来表素心。","聊尔赠君为土物，也教人道有知音。"]},{"t":"和景贤七绝 其六","f":"七言绝句","c":["年来衰老四旬馀，愿与人间万事疏。","惟有琴魔降不得，鸣球戛玉彻清虚。"]},{"t":"和景贤七绝 其七","f":"七言绝句","c":["知音重遇已忘忧，况复边山七月秋。","联句弦歌清夜乐，人生适意亦何忧。"]},{"t":"又和景贤四绝 其一","f":"七言绝句","c":["年来世事已参商，但有声尘尚未忘。","若向琴中定优劣，龙冈错认老髯郎。"]},{"t":"又和景贤四绝 其二","f":"七言绝句","c":["抚弄桐君乐自然，寥寥古意讵容传。","伯牙点检真堪笑，不遇知音便绝弦。"]},{"t":"又和景贤四绝 其三","f":"七言绝句","c":["幽人寥落思无穷，付与轩昂一曲终。","欲罢不能行且止，泣麟嗟凤鼓悲风。"]},{"t":"又和景贤四绝 其四","f":"七言绝句","c":["接得新诗想笑谈，奇才独步斗之南。","纵横风月输君手，惟有枯禅不许参。"]},{"t":"和景贤二绝 其一","f":"七言绝句","c":["醉时还许醒时无，谚有斯言正谓予。","未得素鹅白似雪，等闲难与右军书。"]},{"t":"和景贤二绝 其二","f":"七言绝句","c":["龙冈才德古来无，敏捷新诗正起予。","词翰双全妙天下，银钩深似鲁公书。"]},{"t":"和高冲霄二首 其一","f":"七言绝句","c":["十里东风渭水春，临风酹月吊英魂。","直须立事书麟阁，何必题诗寄雁门。"]},{"t":"和高冲霄二首 其二","f":"七言绝句","c":["翠华南渡济苍生，垂老将观德化成。","昨夜行宫传好语，秦川草木也欣荣。"]},{"t":"过天山和上人韵二绝 其一","f":"七言绝句","c":["从征万里走风沙，南北东西总是家。","落得胸中空索索，凝然心是白莲花。"]},{"t":"过天山和上人韵二绝 其二","f":"七言绝句","c":["一入空门我畅哉，浮云名利已忘怀。","无心对镜谁能识，优钵罗花火里开。"]},{"t":"过覃怀二绝 其一","f":"七言绝句","c":["十年寥落隐穹庐，驿使空来好信无。","再过覃怀觅陈迹，冰魂无恙影扶疏。"]},{"t":"过覃怀二绝 其二","f":"七言绝句","c":["信断江南望驿尘，十年辜负岭头春。","而今重到覃怀地，却与梅花作主人。"]},{"t":"王屋道中","f":"七言绝句","c":["雪岭风林度古关，画图曾见晋名贤。","而今好倩丹青手，添我龙钟一湛然。"]},{"t":"过天德用迁上人韵","f":"七言绝句","c":["行尽中原二百州，黄能往往不吞钩。","而今再出天山道，收拾纶竿北海游。"]},{"t":"赠辽西李郡王","f":"七言绝句","c":["我本东丹八叶花，先生贤祖相林牙。","而今四海归王化，明月青天却一家。"]},{"t":"题张道人扇二首 其一","f":"七言绝句","c":["谁裁云扇缀春棕，招引微凉枉费工。","何似踏开真境界，普天匝地起清风。"]},{"t":"题张道人扇二首 其二","f":"七言绝句","c":["真空境界本如如，病眼生花认画图。","至道绝形刚着面，太虚无面更添须。"]},{"t":"题古并覃公秀野园","f":"七言绝句","c":["流水潜穿屋下篱，青山屋上数峰奇。","佳园已有温公句，何必裘公更写诗。"]},{"t":"题昭上人松菊堂","f":"七言绝句","c":["晴烟苍节出墙青，斜日黄华隔槛明。","松菊尚存归未得，湛然真个太憨生。"]},{"t":"题平阳刘子宁玄珠堂","f":"七言绝句","c":["玄珠失却已多时，纵使离娄枉用眉。","谁识这些关捩子，再三捞漉始应知。"]},{"t":"题志公图","f":"七言绝句","c":["昔传难貌志公真，我道斯言尚未亲。","刹刹尘尘无处避，丹青也是本来人。"]},{"t":"题黄山墨竹便面","f":"七言绝句","c":["黄山落笔露全机，底个团圞太崛奇。","点破本来真面目，何妨节外更生枝。"]},{"t":"请住东堂","f":"七言绝句","c":["云中豪杰构东堂，便请禅师蚤发装。","自有东山铁馂馅，不妨拈出大家尝。"]},{"t":"请倪公","f":"七言绝句","c":["倪公本是我同参，道价峥嵘冠斗南。","千里云山旧游地，何妨杖锡住西庵。"]},{"t":"请照老住华塔","f":"七言绝句","c":["华塔当年隐蛰龙，轰雷掣电满云中。","而今却请还山去，折脚铛边煮晓风。"]},{"t":"华塔照上人请为功德主","f":"七言绝句","c":["晋阳名刹近千区，华塔丛林冠一隅。","今日请予来领略，他年乞我一禅庐。"]},{"t":"请岩公禅师诣天德作水陆大会","f":"七言绝句","c":["禅师久住贺兰山，心与白云自在闲。","便好因风到人世，化为甘露满人间。"]},{"t":"和贾抟霄韵二绝 其一","f":"七言绝句","c":["举世昏昏似醉眠，悲哉不肯救头然。","祖师点破新关捩，且指人心教外传。"]},{"t":"和贾抟霄韵二绝 其二","f":"七言绝句","c":["西庵谈道顿忘眠，今日相逢亦偶然。","欲问瞿昙端的处，灯笼露柱却能传。"]},{"t":"和高丽使三首 其一","f":"七言绝句","c":["神武有威元不杀，宽仁常愧数兴戎。","仁绥武震诚无敌，重译来王四海同。"]},{"t":"和高丽使三首 其二","f":"七言绝句","c":["扬兵青海西凉灭，渡马黄河南汴空。","百济称藩新内附，驰轺来自海门东。"]},{"t":"和高丽使三首 其三","f":"七言绝句","c":["壮年吟啸巢由月，晚节吹嘘尧舜风。","两鬓苍苍尘满眼，东人犹未识髯公。"]},{"t":"梦中偶得","f":"五言绝句","c":["我爱湖山好，茆斋绕涧泉。","道人闲受用，不使半文钱。"]},{"t":"和武善夫韵二首 其一","f":"七言律诗","c":["佐主焦劳力已殚，微才安可济时难。","开樽北海希文举，携妓东山笑谢安。","雨露新恩君责重，桑榆老境我年残。","何时致政闾山去，三径依然松菊寒。"]},{"t":"和武善夫韵二首 其二","f":"七言律诗","c":["秋霖初霁觉新凉，午夜东山月吐光。","翠竹无心甘晚节，黄花有意助年芳。","忠诚自许一心赤，老境谁怜两鬓霜。","遥忆吾山归未得，故人书简怨东阳。"]},{"t":"题寒江接舫图","f":"曲","c":["一派潇湘万里山，閒骑冻?照江天。","风帆雪棹知多少，认取华亭没底船。"]},{"t":"题黄梅出山图","f":"七言绝句","c":["佛祖不识山中主，良材可惜遭斤斧。","肩担明月过前峰，一时忘却曹溪语。"]},{"t":"梦中赠圣安澄老","f":"七言绝句","c":["一束三人作一团，了无前后亦无偏。","几乎笑杀庞居士，拟问如何便着拳。"]},{"t":"跋定僧岩","f":"七言绝句","c":["玉岩三尺碧玲珑，入定僧迷一色功。","打入无明山鬼窟，不知何日透真空。"]},{"t":"咏探春花用高冲霄韵","f":"七言绝句","c":["风拂新芳映短墙，典型依约类丁香。","梅花欲谢渠先坼，消得东君为汝忙。"]},{"t":"寄休林老人","f":"七言绝句","c":["世上元无真是非，丛林禅客自多疑。","此诗寄向并州去，笑倒休林老古锥。"]},{"t":"过济源登裴公亭用闲闲老人韵四绝 其一","f":"七言绝句","c":["一抱青山插碧空，平湖春水碧溶溶。","裴公亭下千竿竹，撩我诗情得得浓。"]},{"t":"过济源登裴公亭用闲闲老人韵四绝 其二","f":"七言绝句","c":["珍玉参差照底寒，闲闲佳句继香山。","湛然不揆真堪笑，也敢题诗列壁间。"]},{"t":"过济源登裴公亭用闲闲老人韵四绝 其三","f":"七言绝句","c":["绕垣乔木碧天参，松竹萧萧翳镜潭。","他日携琴来隐此，林间乞我一禅庵。"]},{"t":"过济源登裴公亭用闲闲老人韵四绝 其四","f":"七言绝句","c":["碧湖风定水痕平，雪竹幽禽自好声。","我羡清源高隐士，干戈人世不知兵。"]},{"t":"再用前韵（过济源登裴公亭用闲闲老人韵） 其一","f":"七言绝句","c":["山接晴霄水浸空，山光滟滟水溶溶。","风回一镜柔蓝浅，雨过千峰泼黛浓。"]},{"t":"再用前韵（过济源登裴公亭用闲闲老人韵） 其二","f":"七言绝句","c":["掀髯坐语闲临水，仰面徐行饱看山。","竹里忽闻春雪落，天教著我画图间。"]},{"t":"再用前韵（过济源登裴公亭用闲闲老人韵） 其三","f":"七言绝句","c":["侍中庵底春山色，裴老亭边秋水声。","修竹茂林真隐地，但期天下早休兵。"]},{"t":"再用前韵（过济源登裴公亭用闲闲老人韵） 其四","f":"七言绝句","c":["劫外玄机好细参，他年卜筑绕澄潭。","琴书活计无多子，祗与龙冈共一庵。"]},{"t":"复用前韵 其一","f":"七言绝句","c":["水影连天天渺渺，山光和水水溶溶。","一林修竹摇云碧，百亩凉阴蔽日浓。"]},{"t":"复用前韵 其二","f":"七言绝句","c":["门外回环皆碧水，庭中坐卧得青山。","凭栏尽日搜新句，思入烟霞缥缈间。"]},{"t":"复用前韵 其三","f":"七言绝句","c":["几时投老谒同参，拟向君王乞镜潭。","饭了遨游容膝处，裴公亭与侍中庵。"]},{"t":"复用前韵 其四","f":"七言绝句","c":["四海干戈尚未平，不如归隐听歌声。","情知文武都无用，罢读诗书不学兵。"]},{"t":"再和西庵上人韵","f":"七言绝句","c":["不在寻求不在参，谁分西北与东南。","云川试入西庵去，三圣元来共一庵。"]},{"t":"请真老住华塔","f":"七言绝句","c":["华塔丛林久席虚，真公予请肯来无。","湛然拙偈呈君去，便好携瓶倒上驴。"]},{"t":"请王公住太原开化","f":"七言绝句","c":["大愚不了戾儿孙，开化重兴正赖君。","便请踏开关捩子，何妨地炙与天薰。"]},{"t":"和薛伯通韵四绝 其一","f":"七言绝句","c":["黄花红叶满秋山，月浸银河夜未阑。","寂寞梧桐深院落，有人何处倚阑干。"]},{"t":"和薛伯通韵四绝 其二","f":"七言绝句","c":["碧山妆点塞天秋，老尽黄花蝶也愁。","拚醉东篱颠倒舞，人间富贵一何楼。"]},{"t":"和薛伯通韵四绝 其三","f":"七言绝句","c":["衰年且喜志微伸，镜里惊看白发新。","何日得游云水去，秋江鸥鹭淡相亲。"]},{"t":"和薛伯通韵四绝 其四","f":"七言绝句","c":["虚名羁我未能归，羞见冥冥一雁飞。","拜扫松楸定何日，不堪双泪对君挥。"]},{"t":"和松菊堂主人照老见寄三诗 其一","f":"七言绝句","c":["松菊堂中老故人，芝眉重谒我无因。","林松老节应依旧，篱菊寒英又一新。"]},{"t":"和松菊堂主人照老见寄三诗 其二","f":"七言绝句","c":["晋阳相遇亦前因，分手归来迹已陈。","松菊幽堂应冷淡，与君同话更何人。"]},{"t":"和松菊堂主人照老见寄三诗 其三","f":"七言绝句","c":["俊老荼毗四十年，前身是我误相传。","香山声价喧天下，争似衰翁不会禅。"]},{"t":"洞山五位颂（诗题 正中偏 其一","f":"七言绝句","c":["十月澄江彻底冰，梅花江路破瑶英。","寒斋冷坐人无寐，雪映书窗一夜明。"]},{"t":"洞山五位颂（诗题 偏中正 其二","f":"七言绝句","c":["区区游子困风尘，就路还家触处真。","芳草满川桃李乱，风光全似故园春。"]},{"t":"洞山五位颂（诗题 正中来 其三","f":"七言绝句","c":["石女翩翻鸟道飞，渊明琴上抚冰丝。","缓歌劫外阳春曲，慢看盘中白雪词。"]},{"t":"洞山五位颂（诗题 兼中至 其四","f":"七言绝句","c":["泾渭同流无间断，华夷一统太平秋。","而今水陆舟车混，何碍冰人跨火牛。"]},{"t":"洞山五位颂（诗题 兼中到 其五","f":"七言绝句","c":["水穷山尽悬涯外，海角天涯云更遮。","撒手转身人不识，回途随分纳些些。"]},{"t":"太阳十六题 其一 识自宗","f":"七言绝句","c":["拈花老子徒饶舌，面壁胡僧太赚人。","更着洞山行过水，吾宗从此永沈沦。"]},{"t":"太阳十六题 其二 死中活","f":"七言绝句","c":["百尺竿头须进步，无明鬼窟好抽身。","寒灰定爆真奇味，枯木花开别是春。"]},{"t":"太阳十六题 其三 活中死","f":"七言绝句","c":["韶老须弥论过失，庐陵来价认商量。","可怜一粒灵丹药，咽下喉咙命已亡。"]},{"t":"太阳十六题 其四 不落死活","f":"七言绝句","c":["白云深处有沧波，半醉微醒哭更歌。","孤艇往来无系绊，阴晴天气曝渔蓑。"]},{"t":"太阳十六题 其五 背舍","f":"七言绝句","c":["人亡家破更何依，退步悬崖撒手时。","去岁生涯无寸土，今年活计更忘锥。"]},{"t":"太阳十六题 其六 不背舍","f":"七言绝句","c":["通方大隐好居廛，手段能如火里莲。","九陌香尘乌帽底，一槔春水白鸥前。"]},{"t":"太阳十六题 其七 活分","f":"七言绝句","c":["垂衣端拱愧佳兵，文化优游致太平。","昨夜濛濛春雨足，松筠花草一时荣。"]},{"t":"太阳十六题 其八 杀人剑","f":"七言绝句","c":["雪刃森森倚碧云，佛魔凡圣总亡魂。","水乾沧海鱼龙死，火烈昆冈玉石焚。"]},{"t":"太阳十六题 其九 平常","f":"七言绝句","c":["寒来向火被添绵，夏月临风使扇扇。","渴饮饥餐随分过，闲中打坐困时眠。"]},{"t":"太阳十六题 其十 利道拔生","f":"七言绝句","c":["个个既知迦叶富，人人休怨释迦悭。","破铛煮得空华实，甑里盛将铁汉餐。"]},{"t":"太阳十六题 其十一 言无过失","f":"七言绝句","c":["元知舌上无横骨，须信喉中有转关。","唤鳖为龟人不肯，直教迦叶也眉攒。"]},{"t":"太阳十六题 其十二 透脱","f":"七言绝句","c":["潇湘一片芦花秋，雪浪银涛无尽头。","何须渔歌发清响，鹭鸶飞出白汀洲。"]},{"t":"太阳十六题 其十三 透脱不透脱","f":"七言绝句","c":["重阳九日菊花新，妙契忘言不犯春。","收得安南忧伐北，不知何日得通津。"]},{"t":"太阳十六题 其十四 称扬","f":"七言绝句","c":["从来个事不囊藏，刹刹尘尘为举扬。","近日令严谁敢犯，不教夺市与搀行。"]},{"t":"太阳十六题 其十五 降句之一","f":"七言绝句","c":["鹫岭默然全是影，毗耶杜口本非真。","灯笼露柱呵呵笑，误杀浮生多少人。"]},{"t":"太阳十六题 其十六 降句之二","f":"七言绝句","c":["疏山住住莫葱葱，龙牙且无祖师意。","须信扑牛另有方，不犯锋铓震天地。"]},{"t":"太阳十六题 其十七 方又圆","f":"七言绝句","c":["破船折棹残蓑笠，石女直钩波上月。","方士徒誇铁作金，道人祗要金成铁。"]},{"t":"西域尝新瓜","f":"七言绝句","c":["西征军旅未还家，六月攻城汗滴沙。","自愧不才还有幸，午风凉处剖新瓜。"]},{"t":"天德海上人寄诗用元韵","f":"七言绝句","c":["知子无心谒五侯，浮云富贵岂能留？","华亭夜静西风软，万顷沧波浸月钩。"]},{"t":"寄白云上人用旧韵","f":"七言绝句","c":["上人别后未能参，一首新诗自北南。","萧寺深沉香火冷，白云闲锁旧禅庵。"]},{"t":"武川摩诃院请为功德主","f":"七言绝句","c":["昔日南游又五春，马蹄踏遍武川尘。","而今却到经行处，且与摩诃作主人。"]},{"t":"和房长老二绝 其一","f":"七言绝句","c":["只识瓶盘不识金，瓶盘钗钏本真金。","一从打破疑团后，物物头头总是心。"]},{"t":"和房长老二绝 其二","f":"五言绝句","c":["生死与涅槃，都如昨梦耳。","觉后笑呵呵，无彼亦无此。"]},{"t":"过平阳高庭英索诗强为一绝","f":"七言绝句","c":["一川秋色满东篱，雁字行行自写悲。","试问省庵何所省，黄华红叶总堪诗。"]},{"t":"醉义歌","f":"楚辞体","c":["晓来雨霁日苍凉，枕帏摇曳西风香。","困眠未足正展转，儿童来报今重阳。","吟儿苍苍浑塞色，容怀衮衮皆吾乡。","敛衾默坐思往事，天涯三载空悲伤。","正是幽人叹幽独，东邻携酒来茅屋。","怜予病窜伶仃愁，自言新酿秋泉曲。","凌晨未盥三两卮，旋酌连斟折栏菊。","我本清癯酒户低，羁怀开拓何其速。","愁肠解结千万重，高谈几笑吟秋风。","遥望无何风色好，飘飘渐远尘寰中。","渊明笑问斥逐事，谪仙遥指华胥宫。","华胥咫尺尚未及，人间万事纷纷空。","一器才空开一器，宿酲未解人先醉。","携樽挈榼近花前，折花顾影聊相戏。","生平岂无同道徒，海角天涯我遐弃。","我爱南村农丈人，山溪幽隐潜修真。","老病犹耽黑甜味，古风清远途犹迍。","喧嚣避遁岩麓僻，幽闲放旷云泉滨。","旋舂新黍爨香饭，一樽浊酒呼予频。","欣然命驾匆匆去，漠漠霜天行古路。","穿村迤逦入中门，老幼仓忙不宁处。","丈人迎立瓦杯寒，老母自供山果醋。","扶携齐唱雅声清，酬酢温语如甘澍。","谓予绿鬓犹可需，谢渠黄发勤相谕。","随分穷秋摇酒卮，席边篱畔花无数。","巨觥深斝新词催，闲诗古语玄关开。","开怀嘱酒谢予意，村家不弃来相陪。","适遇今年东鄙阜，黍稷馨香栖畎亩。","相邀斗酒不浃旬，爱君萧散真良友。","我酬一语白丈人，解释羁愁感黄耇。","请君举盏无言他，与君却唱醉义歌。","风云不与世荣别，石火又异人生何。","荣利傥来岂苟得，穷通夙定徒奔波。","梁冀跋扈德何在，仲尼削迹名终多。","古来此事元如是，毕竟思量何怪此。","争如终日且开樽，驾酒乘杯醉乡里。","醉中佳趣欲告君，至乐无形难说似。","泰山载斲为深杯，长河酿酒斟酌之。","迷人愁客世无数，呼来搯耳充罚卮。","一杯愁思初消铄，两盏迷魂成勿药。","尔后连浇三五卮，千愁万恨风蓬落。","胸中渐得春气和，腮边不觉衰颜却。","四时为驭驰太虚，二曜为轮辗空廓。","须臾纵辔入无何，自然汝我融真乐。","陶陶一任玉山颓，藉地为茵天作幕。","丈人我语真非真，真兮此外何足云。","丈人我语君听否，听则利名何足有？","问君何事徒劬劳，此何为卑彼岂高。","蜃楼日出寻变灭，云峰风起难坚牢。","芥纳须弥亦闲事，谁知大海吞鸿毛。","梦里蝴蝶勿云假，庄周觉亦非真者。","以指喻指指成虚，马喻马兮马非马。","天地犹一马，万物一指同。","胡为一指分彼此，胡为一马奔西东。","人之富贵我富贵，我之贫困非予穷。","三界惟心更无物，世中物我成融通。","君不见千年之松化仙客，节妇登山身变石。","木魂石质既我同，有情于我何瑕隙。","自料吾身非我身，电光兴废重相隔。","农丈人千头万绪几时休，举觞酩酊忘形迹。"]},{"t":"自赞二首 其一","f":"曲","c":["别来十年五岁，依旧一模一样。","髭髯垂到腰间，眉毛俨然眼上。","龟毛锥子画虚空，写破湛然闲伎俩。"]},{"t":"自赞二首 其二","f":"曲","c":["有发禅僧，无名居士。","人道甚似，我道便是。","尘尘劫劫露全身，纸上毫端何处避。"]},{"t":"和张敏之诗七十韵三首 其一","f":"五言古诗","c":["壮年多轗轲，晚节叹行藏。","故国颓纲秽，新朝明德香。","雄材能预算，大略固难量。","迭出神兵速，无敌我武扬。","本图服叛逆，何止剪诪张。","西讨穷于阗，东征过乐浪。","彗侵天垒壁，光动太白铓。","整整车徒盛，鳞鳞旗鼓望。","天皇深责重，贤帅庙谟臧。","江左将擒楚，河阳已灭商。","英雄皆入彀，强禦敢跳梁。","采访轩车闹，司农官吏忙。","轻徭常力足，薄赋不财伤。","勋业超秦汉，规模迈帝王。","流言无管蔡，奇计有平良。","增葺新文物，耕耘古战场。","蛟龙方奋迅，雕鹗得翱翔。","偶遇风云会，争依日月光。","永酬千古耻，一怒四夷攘。","虎帐十年梦，龙庭几度霜。","迎降初请命，出郭远相将。","久敌真宜死，宽恩何敢当。","赦书民有幸，歌咏寿无疆。","扶杖听黄诏，称觞进白狼。","散财竭库藏，拔将出戎行。","殷绝仁犹在，周倾道不亡。","来招燕郡内，入觐大食傍。","戎服貂裘紫，星轺駮马苍。","中春辞北望，初夏过西凉。","瀚海汹而涌，阴山彷且徨。","闲云迷去路，疏雨润行装。","出处空兴叹，风光自断肠。","典刑陈故事，利病上封章。","天下援深溺，中州冀小康。","风俗乘丧乱，筹策要优长。","痼疾如神附，游魂笑鬼伥。","仁术能骨肉，灵药起膏肓。","避祸宜缄口，当言肯括囊。","遭谗心欲剖，涉苦胆先尝。","北漠绝穷域，西隅抵大洋。","诗书犹不废，忠信未能忘。","毡补连腮帐，绳穿朽脚床。","郊行长野兴，人静若禅房。","回鹘交游熟，昆崙事迹详。","风烟多黯黯，云水两茫茫。","灾变垂乾象，妖氛翳太阳。","髯龙三岛去，玉叶一枝芳。","明主初登极，愚臣敢进狂。","九畴从帝锡，五事合天常。","大乐陈金石，朝服具冕裳。","降升分上下，进退有低昂。","拓境时方急，郊天且未遑。","应兵无血刃，降虏自壶浆。","按堵无更肆，因敌不馈粮。","宸心尊德义，圣政济柔刚。","恩泽涵诸夏，威棱震八荒。","势连西域重，天助北方强。","举我陪三省，求贤守四方。","锦衣捐毳褐，肉食弃糟糠。","隐逸求新仕，流亡集故乡。","百官欣戴舜，万国愿归唐。","耕钓咸生遂，工商乐未央。","会将封泰岳，行看建明堂。","自叹才雕篆，长惭学面墙。","君恩予久负，贤路我深妨。","覆餗恒忧惧，持盈实恐惶。","故山松径碧，旧隐菊花黄。","太守方遗舄，初平政牧羊。","厚颜居此位，若已纳于隍。","吟啸须归去，香山老侍郎。"]},{"t":"和张敏之诗七十韵三首 其二 再用张敏之韵","f":"五言古诗","c":["我爱张公子，丁年密退藏。","施为宜法则，议论自馨香。","元气却不死，深陂岂可量。","儿时供府荐，壮岁已名扬。","汲汲尊尼父，堂堂类子张。","迁居择邻里，濯足拣沧浪。","作传编毛颖，谈玄说剑铓。","奇才千古重，令问万民望。","气压四明客，调穷三耳臧。","典谟师我舜，雅颂起予商。","绵蕞曾陈汉，仁术屡说梁。","本非中酒困，长为和诗忙。","道长茹连拔，时衰心独伤。","篆文遒似李，隶字楷如王。","青眼予能作，白眉君最良。","万言陈国利，一战捷文场。","出海游龙舞，腾空翥凤翔。","十全君子行，一代士林光。","句法吾师范，诗材我窃攘。","忠心常向日，直节欲淩霜。","文没岁云久，道亡天未将。","狂澜时既倒，木铎子宜当。","德业能纯粹，学术靡理疆。","冲天憎燕雀，当路恶豺狼。","绮语吟千韵，宸笔扫十行。","行藏关治乱，出处卜兴亡。","郡隶清河上，家居杜曲傍。","登科年甫冠，修史发初苍。","仙观尝新欠，宫园醉晚凉。","朝天恭踧踖，退食独彷徨。","得暇多休沐，游山小治装。","一卮持竹叶，左手把无肠。","官酒浇三斗，宫词唾百章。","阮声师校尉，琴诀受嵇康。","似玉风神异，如兰气味长。","坦怀无戚戚，明见笑伥伥。","草檄堪医疾，针诗可治肓。","博闻敌武库，高价重珠囊。","忧患经多故，艰难已备尝。","悲歌声历历，雅调韵洋洋。","造次必于是，中心何日忘。","生涯两书箧，香火一禅床。","海上寻徐福，壶中觅长房。","流传虽若此，真伪甚难详。","水国波奔激，仙乡路渺茫。","孤身朝北阙，皓首叹东阳。","险韵嚼佳句，残英嗅冷芳。","仁人今尚在，箕子本佯狂。","洪范明皇极，彝伦叙有常。","百王遗礼乐，三代旧轩裳。","会补南极缺，能令北斗昂。","无媒言嗫嚅，失志思回遑。","秋老空悲扇，天凉反卖浆。","却来频渭钓，又绝在陈粮。","志道衰犹梦，依仁老更刚。","故家三径远，薄土一廛荒。","混混常无舍，乾乾体自强。","卒躬能省己，行道不踰方。","宁耻身衣褐，谁嗟日食糠。","起歌明月夜，舒啸白云乡。","绮夏终辞汉，巢由固避唐。","名极得三者，柴立机中央。","荣遇传金马，题名刻玉堂。","未窥君所蕴，徒见子之墙。","遣欲绝形累，无贪不行妨。","一瓢渠乐逸，陋巷我忧惶。","牺易韦编暗，麟经古卷黄。","著述遵辅嗣，去取笑公羊。","再辨麟绝笔，重笺城复隍。","焦桐人不识，独有蔡中郎。"]},{"t":"和张敏之诗七十韵三首 其三 读唐史有感复继张敏之韵颇有脂粉气息迁就声韵故也呵呵","f":"五言古诗","c":["唐室承平久，遗贤不遁藏。","罗纨桑幄腻，饼饵麦畴香。","马牧初蕃息，民编莫校量。","边臣闲虎略，卫士敛鹰扬。","禁苑晨钟动，梨园锦障张。","披香风细细，太液水浪浪。","河汉明方润，长庚淡不铓。","羽旄仪两列，冠盖道相望。","谏士陈休戚，廷臣论否臧。","金石歌大雅，琴瑟奏清商。","青鸟迷鸳瓦，乌衣绕画梁。","供张官府备，殽馔大官忙。","共享清时乐，殊无谤议伤。","含元朝百辟，花萼宴诸王。","主上贞观圣，官僚魏郑良。","岁馀开武讲，春首辟文场。","异宝浮淮水，馀粮朽凤翔。","诸羌来入卫，百济请观光。","关塞沈烽火，乡闾息寇攘。","三春常若雨，六月不飞霜。","圣德跻朝夕，仁心本就将。","俯知人意顺，仰视帝心当。","彍骑轻关内，精兵重北疆。","朝廷潜巨蠹，方镇养贪狼。","粉面三千辈，金钗十二行。","持盈当忌满，居治不知亡。","相罢曲江去，权移林甫傍。","华清高屼屼，骊峤碧苍苍。","金屋眠春晓，温泉浴暮凉。","掖庭花烂漫，阁道路彷徨。","官监金犀饰，妖姬珠玉装。","危弦惊醉耳，哀调断柔肠。","灯烛晖鳷鹊，丝簧沸建章。","奢淫几桀纣，纯俭劣成康。","击柝宫城邃，传筹禁漏长。","谋欢长汲汲，沈醉若伥伥。","未悟薪及爇，谁知病已肓。","人横碧玉笛，腰佩绛香囊。","岭表千山远，荔枝三日尝。","仙衣吹渺渺，莲舸泛洋洋。","力士权诚重，杨钊宠不忘。","承恩趍宝座，奏事近牙床。","荧惑频侵斗，秋阳弗集房。","人心咸怨怒，天象不披详。","易水声呜咽，燕山水郁茫。","盗贼充上郡，鼙鼓起渔阳。","杀气凌金阙，繁霜殒玉芳。","环儿刚赐死，天子惧如狂。","战士皆思变，奸臣亦易常。","空闲尘羯鼓，谁舞旧霓裳。","忠义心徒顺，英雄志自昂。","翠华摇曳曳，鸾驭去遑遑。","禁脔庖供豕，村民路进浆。","隘兵蜀道险，糊口益州粮。","灵武兵声振，汾阳意气刚。","复收京阙克，重治寝园荒。","贼势时深蹙，官军力益强。","羽檄传剑阁，龙驾返南方。","御府仍无酒，饥民尚啖糠。","邛都求道士，蓬岛觅仙乡。","符使将归汉，真妃犹忆唐。","金钗分一股，钿合擘中央。","挥涕春风殿，伤心秋月堂。","梧桐笼院砌，桃李映宫墙。","佳梦真难得，幽欢颇有妨。","春宵成怨忆，秋夜愈悲惶。","尚记脩眉绿，犹思半额黄。","强舒鸾被翠，闲杀辇车羊。","陵谷俄惊海，沧浪已变隍。","临风一卮酒，聊复酹三郎。"]},{"t":"次韵黄华和同年九日诗十首 其一","f":"五言律诗","c":["秋香真可人，不为无人改。","自惭寒昔盟，东篱子空待。","我独摇酒卮，不得寒英采。","临风望故园，参商二十载。"]},{"t":"次韵黄华和同年九日诗十首 其二","f":"五言律诗","c":["西风残日秋，有客嗟幽独。","偶尔得香醪，凄然忆霜菊。","世态屡迁变，人生多返复。","十年一梦中，犹未黄粱熟。"]},{"t":"次韵黄华和同年九日诗十首 其三","f":"五言律诗","c":["无花复无蝶，不似今秋穷。","黄花岁岁别，九日年年同。","我居北海南，子在西山东。","公余会何日，一醉闲愁空。"]},{"t":"次韵黄华和同年九日诗十首 其四","f":"五言律诗","c":["当年别吾山，曾与黄华期。","富贵非予志，卜筑临东篱。","今也违初心，知我者其谁。","挂冠犹未遂，寄此相思诗。"]},{"t":"次韵黄华和同年九日诗十首 其五","f":"五言律诗","c":["无意恋三公，有心辞驷马。","洛阳失金谷，闾山有别野。","芳酒泻盈樽，秋香折盈把。","沈醉卧西风，不让梨花下。"]},{"t":"次韵黄华和同年九日诗十首 其六","f":"五言律诗","c":["汨没红尘中，辜负黄华秋。","林泉与朝市，试问孰为优。","胡然久沈首，令我心悠悠。","酷思山水乐，梦寐空神游。"]},{"t":"次韵黄华和同年九日诗十首 其七","f":"五言律诗","c":["岁月不我与，弹指及衰年。","平生谙万事，抵死参重玄。","因缘不可滞，慎毋法自然。","两边都不立，别有壶中天。"]},{"t":"次韵黄华和同年九日诗十首 其八","f":"五言律诗","c":["无知岂真知，无见非真见。","遮照玄纵横，机关千万变。","虎口几横身，临敌经百战。","三折为良医，一交学一便。"]},{"t":"次韵黄华和同年九日诗十首 其九","f":"五言律诗","c":["五流分洞下，一派起湖南。","春水无心碧，秋山著意岚。","临济真颠汉，曹山放酒酣。","许多闲伎俩，仔细好生参。"]},{"t":"次韵黄华和同年九日诗十首 其十","f":"五言律诗","c":["水外犹逢水，山前更有山。","元知非内外，更不在中间。","测海才盈掬，窥天见一斑。","枢机谩竭世，一笔请君删。"]},{"t":"寄云中东堂和尚","f":"七言律诗","c":["云中种出火莲华，到底东堂是作家。","伏手骨挝腰下剑，笑人家具手中蛇。","三玄戈甲徒心乱，五位君臣莫眼花。","只遮些儿难理会，草鞋包裹破袈裟。"]},{"t":"谢万寿润公和尚惠书","f":"七言律诗","c":["多谢堂头远赐书，惊人才笔我难如。","承当禅髓心无愧，供奉佛牙力有馀。","幼子可袭先父业，游人却到旧时居。","个中消息谁能悉，玉女乘风跨铁驴。"]},{"t":"燕京大觉禅寺奥公乞经藏记既成以诗戏之","f":"七言律诗","c":["词源老去苦无多，强著闲文赞释迦。","遒健兔毫生月窟，光明茧纸出新罗。","茶炉几瓣龙涎烬，玉板十分凤墨磨。","此起科差真可笑，湛然陪酒更陪歌。"]},{"t":"寄龙溪老人乞西岩香","f":"七言律诗","c":["寄语龙溪老古锥，西岩风韵我长思。","香钱缓发鸣琴后，瓦鼎浓薰入定时。","比拟梅魂祗独步，品量龙脑可同驰。","湛然鼻孔撩天大，穿过多时不自知。"]},{"t":"谢圣安澄公馈药","f":"七言律诗","c":["一粒灵丹寄我尝，湛然回简谢西堂。","杀活一草真难会，药病相治未易量。","子细嚼时元不碍，浑沦吞下也无妨。","圣安骨董知多少，卖弄千年旧药方。"]},{"t":"和王正夫韵","f":"七言律诗","c":["壮年自笑鬓先霜，喜色眉间一点黄。","退食紫宸居凤阁，朝天丹阙列鸳行。","功名必要光前古，富贵何须归故乡。","济世元知有仁政，活人不假返魂香。"]},{"t":"继孟云卿韵","f":"七言律诗","c":["归欤奚待鬓双皤，无恙闾山耸岌峨。","万壑松风思仰峤，千岩烟雨忆平坡。","开基气概鲸吞海，遁世生涯鼠饮河。","好买扁舟从此逝，醉眠江国一渔蓑。"]},{"t":"次云卿见赠","f":"七言律诗","c":["济济千官侍玉宸，尊贤容众更亲亲。","风云际会千年少，天地恩私四海均。","西狩一苏张掖乱，南巡重变大梁春。","车书南北无多日，万里河山宇宙新。"]},{"t":"和王正夫忆琴","f":"七言律诗","c":["道人尘世厌嚣尘，白雪阳春雅意深。","万顷松风皆有趣，一溪流水本无心。","忘机触处成佳谱，信手拈来总妙音。","陶老无弦犹是剩，何如居士更无琴？"]},{"t":"继宋德懋韵三首 其一","f":"七言律诗","c":["圣人开运忆斯年，睿智文明禀自天。","旁午衣冠游北海，纵横耕钓满居延。","月氏入贡称属国，日本观光列户编。","威震西溟千万里，汉唐鸿业亦虚传。"]},{"t":"继宋德懋韵三首 其二","f":"七言律诗","c":["笑我区区亦强为，故园荒矣欲何之。","读书测海持螺测，学道窥天以管窥。","疲俗不禁新疾苦，滥官难抚旧疮痍。","才微任重宜求退，自有当途国手医。"]},{"t":"继宋德懋韵三首 其三","f":"七言律诗","c":["广平流落寓平城，亲老家贫强苟生。","炎汉萧曹贤政事，李唐房杜美声名。","进求高誉千金重，退隐闲身一叶轻。","应继开元旧勋业，华堂钟鼓对长檠。"]},{"t":"和平阳张彦升见寄","f":"五言古诗","c":["天兵出云中，一战平城破。","居庸守将亡，京畿游骑逻。","有客赴澶渊，无人送临贺。","奸臣兴弑逆，时君远迁播。","圣主得中原，明诏求王佐。","胡然北海游，不得南阳卧。","宠遇命前席，客星侵帝座。","万里金山行，三经玉门过。","于阗岁贡修，燉煌兵势挫。","国维张礼义，民生重食货。","黜陟九等分，幽明三载课。","小人绝觊觎，贤才无轗轲。","功名本忌盈，庙堂难久坐。","老矣盍归来，归欤可重和。","俯仰不心惭，宽弘从面唾。","清浊自沙汰，精粗任扬簸。","赋性嗜疏闲，高眠乐慵惰。","苍鸡粗庖充，黄犊足梨拖。","幼子事耕锄，老妻供碓磨。","随分养馀龄，虽饥而不饿。"]},{"t":"跋白乐天慵屏图","f":"七言绝句","c":["三杯兀兀元如道，一觉昏昏恰似真。","不识香山慵睡意，知音自有个中人。"]},{"t":"和请住东堂疏韵","f":"七言绝句","c":["东堂不肯卧西堂，珍御鲜食别样装。","枉费青帘三百尺，云中公子不来尝。"]},{"t":"寄倪公首座","f":"七言绝句","c":["亨监逃海淹齑瓮，隆老成龙过禹门。","独有倪公尚痴坐，几时承继万松轩。"]},{"t":"和吕飞卿","f":"七言绝句","c":["一试戎衣大定初，达贤不得退閒居。","盟津既渡诸侯喜，亲见王舟跃白鱼。"]},{"t":"戏陈秀玉","f":"七言绝句","c":["不见桃源路渺茫，清溪招引到仙乡。","湛然幸得齁齁饱，擘与些儿不肯尝。"]},{"t":"扈从冬狩","f":"七言古诗","c":["天皇冬狩如行兵，白旄一麾长围成。","长围不知几千里，蛰龙震慄山神惊。","长围布置如圆阵，万里云屯贯鱼进。","千群野马杂山羊，赤熊白鹿奔青獐。","壮士弯弓殒奇兽，更驱虎豹逐贪狼。","独有中书倦游客，放下毡帘诵周易。"]},{"t":"用秀玉韵","f":"七言律诗","c":["七尺乌虬乳节坚，清溪寄我我忻然。","敢轻黑铁三十两，远胜黄金百万钱。","好句君堪坡老敌，清诗予负定公先。","他年携此林泉去，静倚松轩诵大全。"]},{"t":"送西方子尚","f":"七言律诗","c":["西方子尚气凌云，一见忘年各任真。","阴德传家宜有庆，义方垂训不违仁。","雄文固可魁天下，确论曾无诡圣人。","天产英才须有意，好将吾道济斯民。"]},{"t":"用樗轩散人韵谢秀玉先生见惠东坡杖","f":"七言绝句","c":["圆方顶足法高卑，五九苍苍老节奇。","一日湛然获二宝，东坡铁杖寂通诗。"]},{"t":"和邦瑞韵送行","f":"七言律诗","c":["幸有和林酒一樽，地炉煨火为君温。","昔年相见兴三叹，此日临行赠一言。","士行莫忘直报怨，人情须信害生恩。","而今跃入惊人浪，珍重风涛过禹门。"]},{"t":"谢西方器之赠阮杖","f":"七言古诗","c":["睢阳三绝从来传，坡仙铁杖为之先。","宋朝四美岂易得，地君神器称手贤。","了然居士隐洛瀍，读书好古有积年。","擒龙捉日获二宝，宝之凿栋屋壁穿。","龙庭万里叠山川，欲来馈我嗟无缘。","将夺固与此理玄，慇勤携赠陈与田。","陈田今岁来朝天，惠然出赐穹庐前。","乌虬入手苍壁悬，恍然遗世如登仙。","长蛟倚壁光娟娟，鳞介欲生如蜿蜒。","澄澄秋月瑩朝镜，须臾洗尽余腥膻。","足方法地顶法乾，四十五节松柏坚。","七尺乌金三十两，微簧瑟瑟鸣哀蝉。","云顶纤纤空腹圆，十三玉柱鸿翩翩。","耽耽云坐踞猛虎，岩岩山口双双弦。","铁君伴我游林泉，足疾顿减冲云烟。","临风三弄碎琼玉，清商秋水声涓涓。","安仁得此如临渊，子聃求杖不惜钱。","湛然坐受匪劳力，不胜其服心胡然。","西方讽我求终焉，故令二友相招延。","抱桐扶杖闾山巅，举觞笑咏秋风边。"]},{"t":"继希安古诗韵","f":"七言绝句","c":["垂尽丝纶不上钩，冥鸿高举弋无由。","不图垂誉流千古，安肯低眉谒五侯。"]},{"t":"和非熊韵","f":"七言绝句","c":["蛮触功名未足誇，掀髯一笑付南华。","他年击破疑团后，始觉从来尽眼花。"]},{"t":"和非熊韵","f":"七言律诗","c":["蔼蔼英声镇北州，非熊人物本风流。","时逢佳客开青眼，久领元戎尚黑头。","已发丰城神剑出，休嗟暗室夜光投。","驱兵经略关中了，题遍长安旧酒楼。"]},{"t":"过深州慈氏院","f":"七言律诗","c":["今年扈从次饶沟，暂解征鞍慈氏游。","世变劫灰何所有，人随兵火鲜能留。","堂堂圣像孰曾识，烨烨真诠讵可求。","醉墨淋漓洒尘壁，使人知我过深州。"]},{"t":"用李君实韵","f":"七言律诗","c":["多病逢秋苦未宜，天涯屈指故人稀。","尘飞沧海悲人世，梦断黄粱笑锦衣。","静乐浮荣难两得，宦情归兴本相违。","高山流水无穷思，抚弄丝桐为发挥。"]},{"t":"继崔子文韵","f":"七言律诗","c":["崔子龙钟亦可怜，临风相送我胡然。","君来玉塞三千里，余隐龙沙二十年。","美玉讵容藏韫椟，精金到底入钧甄。","他时定下搜贤诏，先到河东汾水边。"]},{"t":"继武善夫韵","f":"七言律诗","c":["老子年来酷爱闲，不堪白发映苍颜。","十年兴废悲歌里，半世干戈寤寐间。","北阙欲辞新凤阁，东州元有旧闾山。","熊经鸟引聊终老，嵓下疏松正好攀。"]},{"t":"鼓琴","f":"曲","c":["宴息穹庐中，饱食无用心。","读书费目力，苦思嫌哦吟。","樗蒲近博徒，围棋杀机深。","洞箫耗余气，?筑恶郑音。","呼童炷梅魂，索我春雷琴。","何止销我忧，还能禁邪淫。","正席设棐几，危坐独整襟。","寻徽促玉轸，调弦思沈沈。","清声鸣鹤鸾，古意锵石金。","秋水洗尘耳，秋风振高林。","清兴腾八表，成连何必寻。","弦指忽两忘，世事如商参。","泥涂视富贵，昼夜等古今。","湛然有幽居，祗在闾山阴。","茅亭绕流泉，松竹幽森森。","携琴当老此，归去投吾簪。"]},{"t":"扈从羽猎","f":"七言古诗","c":["湛然扈从狼山东，御闲天马如游龙。","惊狐突出过飞鸟，霜蹄霹雳飞尘中。","马上将军弓挽月，脩尾蒙茸卧残雪。","玉翎犹带血模糊，騄駬嘶鸣汗微血。","长围四合匝数重，东西驰射奔追风。","鸣鞘一震翠华去，满川枕藉皆豺熊。","自笑中书老居士，拥鼻微吟弓矢废。","向人忍耻乞其馀，瘦兔瘸獐紫驼背。","吾儒六艺闻吾书，男儿可废射御乎！","明年准备秋山底，试一如皋学射雉。"]},{"t":"狼山宥猎","f":"曲","c":["君不见武皇校猎长杨里，子云作赋誇奢靡；","又不见开元讲武骊山傍，庐陵修史讥禽荒。","二君所为不足法，徒令千载人雌黄。","吾皇巡狩行周礼，长围一合三千里。","白羽飞空金镝鸣，狡兔雄狐应弦死。","翠华驻跸传丝纶，四开汤网无掩群。","天子恩波沐禽兽，狼山草木咸忻忻。"]},{"t":"对雪鼓琴","f":"曲","c":["君不见党侯赏雪斟羊羔，蛾眉低唱白云谣。","慷慨樽前一绝倒，高谈阔论誇雄豪。","又不见陶谷开轩收竹雪，旋烧活火烹团月。","笑撚吟须吟雪诗，冷淡生活太清绝。","清欢浊乐争相高，至人视此轻鸿毛。","嗜音酣酒元粗俗，癖茶嚼句空劬劳。","龙庭飞雪风凄冽，天地模糊同一色。","数卮美湩温如春，三弄悲风弦欲折。","酪奴欢伯持降旌，诗声歌韵不敢鸣。","党武陶文都勘破，真识此心无一个。"]},{"t":"寄冰室散人","f":"七言律诗","c":["佳人元不是摩澄，幻术因循污此生。","对雪解歌吟飞絮，灭灯能审断弦声。","凤楼潇洒闲琼馆，冰室深沈冷玉笙。","好访龙溪善知识，传灯何啻总持名。"]},{"t":"寄平阳润和尚","f":"七言律诗","c":["十首新词寄我时，净名手段我独知。","解将没孔铁锤子，打就无声金盏儿。","言外翻腾闲曲调，劫前拈弄古钤锤。","清河露布殽公案，赚得衰翁一首诗。"]},{"t":"红梅二首 其一","f":"七言律诗","c":["瘦损佳人冰雪枝，天教妆抹入时宜。","小桃嫌铺翠云叶，疏杏惊看碧玉枝。","李白诗成怨妃子，吴宫宴罢醉西施。","而今辜负黄昏月，只少西湖处士诗。"]},{"t":"红梅二首 其二","f":"七言律诗","c":["天仙皎皎素罗裳，淡抹浓涂总不妨。","酒晕半潮妃子醉，胭脂初试寿阳妆。","肯同桃杏迷蜂蝶，本与松筠傲雪霜。","顾影也应悲汉室，临风犹似怨三郎。"]},{"t":"吟醉轩","f":"七言律诗","c":["修竹千竿五亩宫，幽居活计兴无穷。","清词丽句梅诗老，白发苍颜欧醉翁。","洒墨疾书千首敏，浮白痛饮百樽空。","醉吟闻有香山老，倒用颠拈意暗同。"]},{"t":"寄西庵上人用旧韵四首 其一","f":"七言绝句","c":["别后无缘得再参，新诗重寄代和南。","他年放我休官去，只向云川结小庵。"]},{"t":"寄西庵上人用旧韵四首 其二","f":"七言绝句","c":["功名我已让曹参，又见曹参定五南。","布袜青鞋从此始，济源闻有侍中庵。"]},{"t":"寄西庵上人用旧韵四首 其三","f":"七言绝句","c":["多幸松轩得罢参，玉泉山水胜江南。","泉边便作归休计，何必香山觅旧庵。"]},{"t":"寄西庵上人用旧韵四首 其四","f":"七言绝句","c":["忆昔吾师放晚参，扬兵西北击东南。","一声霹雳龙飞去，尚有痴人宿草庵。"]},{"t":"和渔阳赵光祖二诗 其一","f":"七言律诗","c":["岩廊深责忝疑丞，位重材轻负宠荣。","猾虏七擒输葛亮，奇谋六出愧陈平。","未行礼乐常如歉，欲挂衣冠似不情。","何日对君言我志，夜阑秉烛笑谈倾。"]},{"t":"和渔阳赵光祖二诗 其二","f":"七言律诗","c":["生民垂欲陟春台，南斗妖氛绝点埃。","典礼已随前代废，遗音犹怨后庭哀。","十年叹我垂垂老，万里怜君得得来。","此语纵无多忌讳，缄题未可对人开。"]},{"t":"自赞","f":"曲","c":["美髯中书，白衣居士。","从他抹粉施朱，一任安名立字。","手中玉麈震雷音，说尽人间无限事。"]},{"t":"再过太原题覃公秀野园","f":"五言古诗","c":["君实洛阳园，花竹秀而野。","先生取此意，开园临古社。","土阶甃以石，茅亭略其瓦。","佳木碧云摇，清泉寒玉泻。","开轩扣琴筑，抚景飞觞斝。","我来正秋晚，残英折盈把。","粲然启一笑，琅然歌二雅。","将归且裴回，幽寻未能舍。","呼酒尽馀兴，索笔为摸写。","缅怀温国公，重名满天下。","寥寥二百年，童卒传司马。","君侯筑兹圃，如有所慕者。","晞颜颜之徒，子亦斯人也。"]},{"t":"和韩浩然韵二首 其一","f":"七言绝句","c":["标格雄雄蕴藉深，乌龙胸臆隐雷音。","一双神器波及我，不负分金结义心。"]},{"t":"和韩浩然韵二首 其二","f":"七言绝句","c":["一曲风高奏古宫，坐䝼神物愧无功。","千金厚惠将何报，鹗表慇勤效孔融。"]},{"t":"张汉臣因入觐索诗","f":"七言律诗","c":["汉臣千里觐龙庭，欲使天皇致太平。","十事便宜言恳切，三千貔虎令严明。","好筹庙算如留相，莫忆鲈鱼似季鹰。","一统要荒君勉力，云台须占最高名。"]},{"t":"和谢昭先韵","f":"楚辞体","c":["失奚为劣得奚优，遇流而行坎则留。","笑视纷纷儿女辈，成是败非徒相尤。","弃人所取取所弃，独识万松为出类。","本欲心空及第归，暮请晨参惟一志。","浮生迅速奔隙驹，无穷尘劫元斯须。","参透威音劫前事，花开枯木谁云枯。","河朔干戈犹未息，西域十年空旅食。","贤人退隐予未能，钧衡旷位虚名极。","真人应运康世屯，数颁宽诏垂丝纶。","沛若恩波沦骨髓，皇皇四海咸蒙春。","汉唐疆宇非为大，戍守西临玉关界。","百济称藩过海门，鄙语粗言其大概。","天皇自将办多多，天兵百万涉长河。","京索为空汴梁下，秦皇汉武畴能过？","凛凛威声震天宇，不杀为功果神武。","朔南一混车书同，皇业巍巍跨千古。","先生吾邦之彦兮，琴书而自怡。","劲挺松柏操，磊落英雄姿。","明正道，无邪思。","一贯诗书继先觉，两全才德真吾师。","王谢来江左，家学易道岂忘贻。","济世须君展骥足，政要再凿人耳目。","小子区区何所祝，但愿天衷俞奏鹗。"]},{"t":"德恒将行以诗见赠因用元韵以见意云","f":"五言律诗","c":["国士朝黄屋，无辞路八千。","徒嗟苏子困，谁识祢生贤。","腰下无金印，山中有翠烟。","英雄须有用，勉力待中年。"]},{"t":"送文叔南行","f":"七言律诗","c":["李子敦纯不入时，而今失志又南归。","纵无手内毛生檄，自有囊中莱子衣。","未得忠贞毗圣主，且将甘旨侍慈闱。","鹓雏不忘冲天志，直待三年更一飞。"]},{"t":"和冯扬善九日韵","f":"七言律诗","c":["冯君今岁又离家，携手赓酬海一涯。","秦汉兴亡真梦寐，苏张轗轲莫吁嗟。","孔融座上樽盈酒，靖节篱边菊有华。","何日公馀同此乐，西风一醉泛流霞。"]},{"t":"示石州刘企贤","f":"七言律诗","c":["西州来索湛然诗，笑点霜毫录鄙辞。","底事行藏元有数，斯文否泰本由时。","硕材未信明君弃，雅操何惭暴吏欺。","此语颇涉人忌讳，等閒勿使细民知。"]},{"t":"和刘子中韵","f":"五言古诗","c":["蓬山北海游，珥笔陈良谋。","徒步而南来，意气凌马周。","贪吏乱法令，如茨不可束。","子中有大志，每甘胯下辱。","他日得从龙，其锋谁敢触。","今日君子来，非为五斗粟。","君子慎择术，痛恨陪全真。","调心正是妄，堪笑学鸟伸。","一日错下脚，万劫含酸辛。","平生大梦中，不识庵中人。","一言赠吾子，宗匠宜相亲。"]},{"t":"李庭训和予诗见寄复用元韵以谢之","f":"七言律诗","c":["忝位台司岁月深，中书自笑不如岑。","殷周礼乐真予事，唐舜规模本素心。","郑五每惭难作相，胥靡终欲强为霖。","陇西妙语虚推奖，舒卷寒窗尽日吟。"]},{"t":"和黄山张敏之拟黄庭词韵","f":"七言古诗","c":["黄山无媒亦无梯，萧条白昼关荆扉。","凌晨端坐漱玉池，阑干苜蓿先生饥。","惠然寄我黄庭词，湛然一笑几脱颐。","一鹤南翔一不飞，十年一梦今觉非。","故山旧隐苍松欹，而今老尽虬龙枝。","曾学四老餐紫芝，从讥怀宝而邦迷。","尘缘一扫无孑遗，隔縠观月犹依稀。","汪洋法海无边涯，萤光讵可窥晨晞。","莲花自是生污泥，污泥不染清凉肌。","彩云易散碎琉璃，人间四相夭五衰。","有为无为俱有为，寿穷尘劫元非迟。","湛然醉摇芭蕉卮，蔷薇深蘸书淋漓。","白眼一望须弥低，黄山先生耽书痴。","退藏不露龙麟姿，对人不耻弊缊衣。","自甘贫困元知微，篱边黄菊香离披。","门前山色寒参差，不以下体遗葑菲。","新诗远寄盘龙螭，胸中满贮夷齐薇。","忘机临水狎鸥鹥，燕居申申不愆仪。","含光隐秀如文犀，乘闲纶钓垂清漪。","躬耕禾黍方离离，须信君子能自卑。","予知先生之独悲，深忧海内生民疲。","生民扰攘如棼丝，笑予素餐徒位尸。","先生识鉴如元龟，旁通发而为声诗。","照我穹庐生光辉，穷通进退元有时。","至人终不贪危机，他时天子求埙篪。","欲行周礼修周基，先生好应千年期。","沙堤行人羡轻肥，凤凰到底凤池栖。","太平钧石须君持，苍生未济无言归。"]},{"t":"寄皓公堂头同参","f":"七言绝句","c":["皓公闻道住南宫，笑写新诗托去鸿。","准备金桃三百颗，因风寄与老髯公。"]},{"t":"寄移剌子春","f":"七言律诗","c":["说与沙城刘子春，湛然垂老酷思君。","同游青冢秋将尽，共饮天山酒半醺。","茧纸题诗熟鍊字，毡庐谈道细论文。","五年回首真如梦，衰草寒烟正断魂。"]},{"t":"寄妹夫人","f":"七言律诗","c":["三十年前旅永安，凤箫楼上倚阑干。","初学书画同游戏，静阅琴棋相对闲。","聚散悲欢灯影里，兴亡成败梦魂间。","安书风送来天际，望断中州一发山。"]},{"t":"送侄九龄行","f":"七言绝句","c":["我欲归休与愿违，而方知命正宜归。","闾山自有当年月，一舸西风赋式微。"]},{"t":"送侄了真行","f":"五言古诗","c":["吾兄继世禄，袭封食东平。","幼子死王事，长安闺门英。","孀居二十年，礼佛读传灯。","一旦遇宗匠，了真训其名。","前岁阳翟破，道服潜偷生。","宁死不受辱，托疾燕山京。","湛然怜孤族，赎汝为编氓。","死生本如梦，宠辱真若惊。","莫忘离乱苦，长思厌世情。","三学有龙溪，叩参宜尽诚。","喝碎须弥山，打破乾闼城。","两头俱放下，枯木一枝荣。"]},{"t":"和少林和尚英粹中山堂诗韵","f":"五言律诗","c":["我爱嵩山堂，山堂秋寂寂。","苍烟自摇荡，白云风出入。","泠泠溪水寒，细细琴丝湿。","离尘欲无事，又有闲踪迹。"]},{"t":"和武善夫韵","f":"七言律诗","c":["不得潜身似许由，医闾辜负万山秋。","未竭犬马虽为慊，忽忆猿鹤却自羞。","黄阁赖悬新篆印，白霫元有旧渔舟。","他时雪夜寻良友，且学当年王子猷。"]},{"t":"和冯扬善韵","f":"七言律诗","c":["扬善从来慕晋卿，沧浪浊处不濯缨。","关东易学孰能与，冀北诗声莫与京。","今日穷途虽蹇剥，他时行道自亨贞。","须知遁世元无闷，莫怨龙钟出帝城。"]},{"t":"和董彦才东坡铁杖诗二十韵","f":"曲","c":["女娲未补青天裂，神液飞精散为铁。","嵇生箕踞锻洪炉，白汗翻浆滴清血。","黑虬彷佛欲飞跃，鳞介苍苍生乳节。","情知中散气凌云，肯与凡工争巧拙。","柳君传与东坡老，神物终须归俊杰。","坡仙为寿文定公，酬和新诗誇胜劣。","观妙堂名龙尾砚，雎阳并此为三绝。","雎阳城破兵火炎，神器不随烟焰灭。","了然居士出伊洛，登山度水相扶挈。","燕然分付我清溪，妙语雕镌跨先哲。","远来携赠白霫老，天理似为予所设。","湛然忝佐本无功，致王泽民愧皋契。","再游北海复何恨，与君同步龙沙雪。","大泽深山无所惊，扫除魑魅驱凶?。","轻簧历历吐微语，闲对幽人如鼓舌。","有如拈起击须弥，须弥击碎同丘垤。","云门远遁德山去，敢对髯翁开口说。","一时惊倒野狐禅，奔走不来予阃闑。","他年神武挂冠去，谁知劫外乾坤别。","横担此杖入千峰，大方独步无蹉跌。"]},{"t":"用张道亨韵","f":"七言古诗","c":["大安之季君政乖，屯爻用事符云雷。","边军骄懦望风溃，燕南赵北飞兵埃。","民财已竭转输困，元元思治如望梅。","太白经天守帝座，长星勾巳坼中台。","玄台密表告天道，灾妖变异无不该。","奸臣搆祸谋不轨，鱼鳞鳞首侵宸阶。","喋血京师万人死，君臣自此相嫌猜。","居庸失守紫荆破，天兵掣电腾八垓。","潜议迁都避凶祸，衔枚半夜宫门开。","河表偷生聊自固，京城留后除行台。","力穷食尽计安出，元戎守节甘自栽。","虬龙奋迅脱大难，微波沈滞独黄能。","王师神武本不杀，一发鹿台能散财。","威声远震陕洛惧，势同拉朽如枯摧。","髯公退缩养愚拙，白麻一旦天边来。","万里龙庭谒天子，轺车轧轧风尘埋。","言轻无用自缄嘿，浮沈鹓鹭相趋陪。","布幕毡庐庇风雨，日中一食如持斋。","瀚海波声寒汹涌，金山峰势高崔嵬。","十年行役亦艰苦，盐车强驾同驽骀。","美湩如饴润喉吻，仃伶独拨寒炉灰。","故园梦断几千里，燕然回首白云堆。","弹铗悲歌望明月，山城明月空徘徊。","往事如丝不敢忆，令人感慨生馀哀。","圣人继运践九五，欢声腾沸天之涯。","万国梯航喜奔走，币帛交列陈琼瑰。","天子恩威溢中外，远迩翕然无不怀。","四民乐业庶政举，宗臣戮力诸王谐。","行殿受朝设钟鼓，明堂祭祀陈大罍。","卿云轮菌自纷郁，妖星不复侵天街。","否道已穷受诸泰，人心已顺天心回。","制度一新从简略，禁网疏阔如天恢。","贤材尚隐若冥雁，区区弋人何慕哉。","自惭忝位司钧轴，可怜多士无梯媒。","愿学留侯引年去，不与赤松游蓬莱。","闾阳旧隐度残朽，扁舟蓑笠江湖崖。"]},{"t":"题庞居士阴德图","f":"七言绝句","c":["易易难难各一机，非难非易亦新奇。","若将三句分优劣，露挂灯笼暗皱眉。"]},{"t":"和冯扬善韵","f":"五言古诗","c":["天道不可穷，此理自古然。","大暴寿盗蹠，至仁夭颜渊。","伟材鲜遭遇，君臣难两全。","庸愚厌粱肉，广文寒无毡。","未逢知音人，伯牙故绝弦。","我爱冯公子，孔教穷高坚。","忧道不忧贫，一室如罄悬。","却笑庠序生，供荐徒备员。","诗书贮便腹，一斗吟百篇。","远蹈颜孟迹，近比苏黄肩。","宁受胯下辱，不为天下先。","升平已有期，上道化日躔。","九州成一统，刑赏归朝权。","汴梁三战定，乐浪一檄传。","先生谒承明，万里来秦川。","徒步沙碛中，往复几一年。","揲蓍说易传，应诏命席前。","十年符亿兆，一世盈十千。","男儿志在道，何论胝与胼。","一旦得荣遇，闾巷车马填。","穷通固由命，何必兴孜煎。","用之自可进，舍之便可还。","自笑髯中书，有过仍不悛。","三代不同礼，勉欲相袭沿。","贤人正退隐，强起居官联。","冰炭岂共器，安可浑愚贤。","可惜和氏姿，庸工浪雕镌。","不能作大器，取次成弃捐。","潜龙喻君子，或跃或在田。","未遂马周志，好垦扬雄廛。","伏腊粗酒脯，旦夕充羹饘。","穷途不足泣，吊影无自怜。","人生一瞬息，日月如玑璇。","学道如牧羊，后者为之鞭。","离群谢富贵，遁世安林泉。","勿学躁进人，扼腕长呼天。"]},{"t":"和秀玉韵","f":"五言古诗","c":["清溪作寱语，湛然大笑之。","仅能知大用，尚未识天机。","贪随言语转，错认二阿师。","个中关捩子，卓然绝百非。","三学未尝坐，何说非与是。","半藏未有言，奚论赞与毁。","解语非干舌，能知诚匪智。","为报清溪公，无事莫生事。"]},{"t":"示从智","f":"曲","c":["知人者明，自知者智。","仁人一言，溥哉其利。"]},{"t":"答聂庭玉","f":"七言律诗","c":["文章太守镇榆关，远寄新诗与湛然。","卓尔功名君勉力，归与活计我加鞭。","扶衰幸有东坡杖，遣兴犹存玉涧泉。","布袜青鞋任真率，东垣山水不拈钱。"]},{"t":"继柏岩大禅师韵","f":"七言律诗","c":["行尽千程与万程，谁能退步见严宸。","饶渠解释庭前雪，笑彼难除室外尘。","翡翠帘前犹是汝，琉璃殿上更何人。","直须鹤出银笼外，受用壶天不夜春。"]},{"t":"和张善长韵","f":"七言律诗","c":["下马如虹气焰雄，惊人诗笔有谁同。","银钩老字学颜体，玉振奇辞类国风。","今日白衣聊养素，他年皇屋好推忠。","经营江左须豪哲，占取云台第一功。"]},{"t":"爱栖岩弹琴声法二绝 其一","f":"七言绝句","c":["须信希声是大音，猱多则乱吟多淫。","世人不识栖岩意，祗爱时宜热闹琴。"]},{"t":"爱栖岩弹琴声法二绝 其二","f":"七言绝句","c":["多著吟猱热客耳，强生取与媚俗情。","纯音简易谁能识，却道岩栖无木声。"]},{"t":"冬夜弹琴颇有所得乱道拙语三十韵以遗犹子兰","f":"五言古诗","c":["湛然有琴癖，不好凡丝竹。","儿时已存心，壮年学愈笃。","仓忙兵火际，遗谱不及录。","回首二十秋，丝桐高阁束。","栖岩有后人，万里来相逐。","能继箕裘业，待予为季叔。","今冬六十日，对弹五十曲。","五旬记新声，十朝温已熟。","高山壮意气，秋水清心目。","阳春撼琼玖，白雪碎瑶玉。","洛浦太含悲，楚妃叹如哭。","离骚泣鬼神，止息振林木。","秋思尽雅兴，三乐歌清福。","自馀不暇数，渴心今已沃。","昔我师弭君，平淡声不促。","如奏清庙乐，威仪自穆穆。","今观栖岩意，节奏变神速。","虽繁而不乱，欲断还能续。","吟猱从简易，轻重分起伏。","一闻栖岩声，不觉倾心服。","彼此成一家，春兰与秋菊。","我今会为一，沧海涵百谷。","稍疾意不急，似迟声不局。","二子终身学，今日皆归仆。","我本嗜疏懒，富贵如桎梏。","幸遇万松师，一悟消三毒。","早晚挂冠去，闾山结茅屋。","蔬笋粗充庖，粝饭炊脱粟。","有我春雷子，岂惮食无肉。","旦夕饱纯音，便是平生足。"]},{"t":"夜坐弹离骚","f":"七言绝句","c":["一曲离骚一椀茶，个中真味更何加。","香销烛烬穹庐冷，星斗阑干山月斜。"]},{"t":"弹秋宵步月秋夜步月二曲","f":"七言绝句","c":["碧玉声中步月歌，弹来弹去不嫌多。","从教人笑成琴癖，老子佯呆不管他。"]},{"t":"弹秋水","f":"五言律诗","c":["信意弹秋水，清商促轸成。","只疑天上曲，不似世间声。","海若诚无敌，河神已请平。","三朝不弹此，心窍觉尘生。"]},{"t":"弹秋思用乐天韵二绝示景贤 其一","f":"七言绝句","c":["秋思而今不入时，平和节奏苦嫌迟。","香山旧谱重拈出，不问知音知不知。"]},{"t":"弹秋思用乐天韵二绝示景贤 其二","f":"七言绝句","c":["粼粼断似乌蛇蚹，瑟瑟徽如古殿苔。","玉涧鸣泉独受用，穹庐祗少景贤来。"]},{"t":"弹广陵散终日而成因赋诗五十韵","f":"五言古诗","c":["湛然数从军，十稔苦行役。","而今近衰老，足疾困卑湿。","岁暮懒出门，不欲为无益。","穹庐何所有，祗有琴三尺。","时复一弦歌，不犹贤博弈。","信能禁邪念，閒愁破堆积。","凊旦炷幽香，澄心弹止息。","薄暮已得意，焚膏达中夕。","古谱成巨轴，无虑声千百。","大意分四节，四十有四拍。","品弦欲终调，六弦一时划。","初讶似破竹，不止如裂帛。","忘身志慷慨，别姊情惨戚。","冲冠气何壮，投剑声如掷。","呼幽达穹苍，长虹如玉立。","将弹怒发篇，寒风自瑟瑟。","琼珠落玉器，雹坠渔人笠。","别鹤唳苍松，哀猿啼怪柏。","数声如怨诉，寒泉古涧涩。","几折变轩昂，奔流禹门急。","大弦忽一捻，应弦如破的。","云烟速变灭，风雷恣呼吸。","数作拨剌声，指边轰霹雳。","一鼓息万动，再弄鬼神泣。","叔夜志豪迈，声名动蛮貊。","洪炉煅神剑，自觉乾坤窄。","钟会来相过，箕踞方袒裼。","一旦谮杀之，始知襟度阨。","新声东市绝，孝尼无所获。","密传迨王遨，曾为山甫客。","近代有张研，妙指莫能及。","琴道震汴洛，屡陪光禄席。","器之虽有声，鍊此头垂白。","中间另起意，沈思至峻迹。","节奏似支离，美玉成破璧。","为山亏一篑，未精诚可惜。","我爱栖岩翁，翻声从旧格。","始终成一贯，雅趣超今昔。","三引入五序，始作意如翕。","纵之果纯如，将终缴而绎。","嵇生能作此，史臣书简策。","又谓神所授，传自华阳驿。","韩皋破是说，以为避晋隙。","张崇作谱序，似是未为得。","我今通此论，是非自悬隔。","商与宫同声，断知臣道逆。","权臣侔人主，不啻韩相贼。","安得聂政徒，元恶诛君侧。","上欲悟天子，下则有所激。","惜哉中散意，千古无人识。"]},{"t":"吾山吟","f":"曲","c":["吾山吾山予将归。","予将归，深溪苍松围茅亭，扃扃柴扉。","水边林下，琴书乐矣，水边林下，琴书乐矣，不许市朝知。","猿鹤悲，吾山胡不归！"]},{"t":"从万松老师乞玉博山","f":"七言律诗","c":["吾师珍惜玉山炉，可叹雕纹朴丧初。","无党无偏三足峙，不缁不磷一心虚。","礼佛诵课须资汝，示众拈香正起予。","对此好弹三涧雪，因风远寄万松书。"]},{"t":"寄万寿润公禅师用旧韵","f":"七言律诗","c":["懒答禅师一纸书，禅师佳句古谁如。","不才叹我垂垂老，美裕怜君绰绰馀。","断臂志能如慧祖，点胸终不似云居。","三关参到纵横处，识破黄龙脚似驴。"]},{"t":"寄圣安澄公禅师","f":"七言律诗","c":["澄公屡有寄来书，不著寒温问讯予。","老柏依然笼古殿，旃檀无恙锁精庐。","金鳞透网三乘外，大隐居廛千载馀。","祗有些儿堪恨处，向人刚觅护身符。"]},{"t":"寄甘泉禅师谢惠书","f":"七言绝句","c":["万松节外有孙枝，德业文章冠一时。","不惜临风寄新句，知音消得湛然诗。"]},{"t":"送房孙重奴行","f":"七言绝句","c":["汝亦东丹十世孙，家亡国破一身存。","而今正好行仁义，勿学轻薄辱我门。"]},{"t":"从龙溪乞西岩香并方","f":"七言律诗","c":["我爱龙溪新样香，西岩风韵卒难忘。","深玄欲说舌头短，妙观先通鼻孔长。","秋水弹时宜受用，碧岩读处更相当。","清香妙谱都拈出，莫惜十年旧药方。"]},{"t":"乙未元日","f":"七言绝句","c":["劫前别有一壶天，万古长空无后先。","建化门头聊尔耳，也随徒众贺新年。"]},{"t":"付从究","f":"七言绝句","c":["旷劫茫茫困路尘，回头便是故园春。","而今既遇松轩老，究取元来不死人。"]},{"t":"旦日遗从祖","f":"七言律诗","c":["尘世春风岁又迁，僚属来贺古川前。","谁知万法生心上，不觉双毛落鬓边。","人生能得几緉屐，文章不直一文钱。","威音那畔乾坤别，且道而今是几年。"]},{"t":"旦日示从同仍简忘忧","f":"五言古诗","c":["昔我驰星轺，驻车归化城。","汝方来抠衣，从同训其名。","侍予垂十年，百事无一成。","律历且及半，琴道犹未精。","禅书置一隅，尚未穷一经。","大道若沧海，万古长澄清。","酌之而不竭，注之而不盈。","偃鼠得满腹，亦足饱鲲鲸。","又如大圆镜，历劫长圆明。","中间无影像，应物不现形。","汉、胡递相照，出没能纵横。","又如万钧钟，寂然藏雄声。","随叩而即应，圆音自锵铿。","小击而小响，大撞而大鸣。","又如长明烛，积岁长荧荧。","分为百千万，光明如日星。","惠之而不费，是为无尽灯。","日月照天下，不可语瞽盲。","雷霆碎山岳，聋者未曾听。","枯木元无花，却怨春不平。","作偈以劝汝，可以为盘铭。"]},{"t":"元日劝忘忧进道","f":"五言律诗","c":["劫外风光别，人间日月迁。","南洲添一岁，北海又二年。","荣利蜗黏壁，功名蚁慕膻。","万缘都放下，好扣祖师禅。"]},{"t":"转灯","f":"五言古诗","c":["安庆作戏灯，惠然来赠我。","藏灯藉微明，细火薰其座。","乘兹风火力，盘旋如转磨。","中有角抵人，挥臂不知祸。","团团十万匝，轮回莫能躲。","此灯虽戏具，无果大因果。","三世尘沙佛，皆如转灯过。","三千大千界，成坏亦风火。","所以明眼人，重道轻利货。","生死比梦寐，荣华等涕唾。","长行此观心，人间都看破。","多少看灯人，知音无一个。"]},{"t":"录寄新诗呈冲霄","f":"七言绝句","c":["冲霄酷爱玉泉诗，愧我年来无好辞。","录寄新诗三十首，莫教俗子等闲知。"]},{"t":"寄东林","f":"七言律诗","c":["同参万里寄书来，盥手缄封手自开。","没骨舌头我难说，无根树子若能栽。","金鹏手段平翻海，任老钩竿不钓能。","何日万松轩侧畔，笑谈抵掌一开怀。"]},{"t":"借琴","f":"七言绝句","c":["龙冈居士本知音，参透渊明得趣心。","暂借桐君休吝惜，玉泉习气未忘琴。"]},{"t":"戏景贤","f":"七言绝句","c":["牧犊曾叹雉朝飞，七十无妻是以悲。","何事龙冈爱弹此，欲学白傅觅杨枝。"]},{"t":"再用前韵二首 其一","f":"七言绝句","c":["遏住行云不敢飞，一声还噎一声悲。","蛮儿深惬龙冈意，唱得香山杨柳枝。"]},{"t":"再用前韵二首 其二","f":"七言绝句","c":["妙舞盘中尘不飞，采莲一曲绕梁悲。","慕素鲁蛮独当两，贯珠歌韵柳腰枝。"]},{"t":"寄景贤","f":"七言律诗","c":["湛然有过必人知，笑寄龙冈自讼诗。","阎浮众生苦为乐，华严皇觉药能医。","十年擐甲足疾作，三月弹琴臂力衰。","因病得闲闲却病，闲中虽病也便宜。"]},{"t":"再用知字韵戏景贤","f":"七言律诗","c":["薄德从来总畏知，龙冈又有和来诗。","机关不解活龙弄，癖疾还如死马医。","大舜再逢难永诀，周公不梦觉吾衰。","凤池元是夔龙宅，山鹿野麋终不宜。"]},{"t":"复用前韵戏呈龙冈居士兼善长诗友二首 其一","f":"七言律诗","c":["君有蛮儿我已知，湛然援笔上新诗。","翠眉已惹禅心动，玉颊休教獭髓医。","旧有药炉虽竭底，新来鼎器却扶衰。","隆隆玉准能青眼，不解云霓也自宜。"]},{"t":"复用前韵戏呈龙冈居士兼善长诗友二首 其二","f":"七言绝句","c":["行雨行云一夜飞，襄王从此莫含悲。","蛮儿侍寝龙岗老，恰似柔稊生柳枝。"]},{"t":"慕乐天","f":"七言律诗","c":["荆水浑如八节滩，玉泉佳趣类香山。","韦编周易忘深意，贝叶佛经送老闲。","爽我琴书池五亩，侑人诗酒竹千竿。","乐天活计都相似，脂粉独嫌素与蛮。"]},{"t":"弹广陵散","f":"七言绝句","c":["居士闲弹止息时，胸中郁结了无遗。","乐天若得嵇生意，未肯独吟秋思诗。"]},{"t":"戏刘润之","f":"七言绝句","c":["休嗔久假不云归，长笑还书是一痴。","居士亲行万里地，政须百注杜陵诗。"]},{"t":"用刘润之韵","f":"七言律诗","c":["个中消息本忘言，一念从渠一万年。","大地遍开皆是水，顽石不击固无烟。","成佛莫落谢公后，建业从教祖氏先。","万法悉从心地起，元来祸福不由天。"]},{"t":"琴道喻五十韵以勉忘忧进道","f":"五言古诗","c":["昔我学鼓琴，豪气凌青天。","轻笑此小技，何必师成连。","宝架翻旧谱，对谱寻冰弦。","自弹数十弄，以为无差肩。","有客来劝予，因举庄生篇。","时君方诵书，轮扁居其前。","释椎而入请，何故读残编。","上古已久矣，不得见圣贤。","遗书糟粕馀，与道云泥悬。","臣年七十秋，双鬓如垂绵。","斲轮固小巧，巧性非方圆。","心手两相应，不能语子焉。","是知圣人道，安得形言诠。","至今千载间，此论不可迁。","琴书纸上语，妙趣焉能传？","不学妄穿凿，是为谁之愆。","今方谒弭君，服膺乃拳拳。","相对授指诀，初请歌水仙。","吟猱不踰矩，节奏能平平。","起伏与神会，态状如云烟。","朝夕从之游，琴事得大全。","小艺尚如此，大道宁不然。","当年嗜佛书，经论穷疏笺。","公案助谈柄，卖弄猾头禅。","一遇万松师，驽骀蒙策鞭。","委身事洒扫，抠衣且三年。","圆教摄万法，始觉担板偏。","回视平昔学，尚未及埃涓。","渐能入堂奥，稍稍穷高坚。","疑团一旦碎，桶底七八穿。","洪炉片雪飞，石上栽白莲。","佛祖立下风，俯视威音先。","忘忧西域时，师我求真筌。","经今十五春，进退犹迁延。","望涯自退缩，甘心嗟无缘。","将求无价宝，未肯酬一钱。","未启半篑土，欲酌九仞泉。","美玉付良工，良工得雕镌。","良金不受冶，徒费炉韝煽。","闻君近好琴，停烛夜不眠。","弹之未期月，曲调能相联。","君初未弹时，曾不知勾蠲。","学道亦如此，惟患无精专。","谁无摩尼珠，谁无般若船。","立志勿犹豫，叩参宜勉旃。","他时大彻悟，沛然如决川。","毛端吞巨海，芥子含大千。","瞬息一世过，生死相萦缠。","此生不得觉，旷劫徒悲煎。","吾言真药石，疗子沈疴痊。"]},{"t":"弹琴逾时作解嘲以呈万松老师","f":"七言律诗","c":["一曲悲风历指寒，昔年曾奉万松轩。","本嫌浮脆删吟抑，为爱轩昂变撞敦。","高趣酿成真有味，烦襟洗尽了无痕。","禅人若道声尘妄，孤负观音正法门。"]},{"t":"勉景贤","f":"五言律诗","c":["既慕东坡才，当如东坡志。","君才如东坡，其志未相似。","诗似东坡诗，字如东坡字。","胡不学东坡，且学长不死。"]},{"t":"刘润之馆于忘忧门下作述怀诗有弟子二三同会食谁曾开口问先生之句余感而和之","f":"七言绝句","c":["从来重士还相重，到底轻人却自轻。","醴废翻然便归去，至今高尚穆先生。"]},{"t":"刘润之作诗有厌琴之句因和之","f":"七言绝句","c":["学士既归夫子道，吾儒宜识仲尼心。","当年删出诗三百，时复弦歌不废琴。"]},{"t":"怀古一百韵寄张敏之","f":"五言古诗","c":["兴亡千古事，胜负一枰棋。","感恨空兴叹，悲吟乃赋诗。","三皇崇道德，五帝重仁慈。","礼废三王谢，权兴五伯漓。","焚书嫌孔孟，峻法用高斯。","政出人思乱，身亡国亦随。","阿房修象魏，徐福觅灵芝。","偶语真虚禁，长城信谩为。","只知秦失鹿，不觉楚亡骓。","约法三章日，恩垂四百基。","汉兴学校启，文作典章施。","黩武疲中夏，穷兵攘四夷。","嗣君恩稍失，刘氏德难衰。","新室虽兴难，真人已御期。","魏吴将奋起，灵献自荒嬉。","贼子权移汉，奸臣坞筑郿。","三朝如峙鼎，四海若棼丝。","才奉山阳主，已生司马师。","仲谋服孟德，葛亮倍曹丕。","惟晋成独统，平吴混八维。","有初终鲜克，居治乱谁思。","蝉鬓充兰掖，羊车绕竹岐。","孙谋无远虑，神器委痴儿。","国事归椒室，民饥询肉糜。","为人昧菽麦，闻蟆问官私。","卫瓘尝几谏，何曾已预知。","五胡云扰攘，六代电奔驰。","川谷流腥血，郊原厌积尸。","天光分耀日，地里裂瓜时。","历数当归李，驱除暂假隋。","西陲开鄯善，东鄙讨高丽。","鸾驾如江国，龙舟泛汴漪。","锦帆遮水面，粉浪污河湄。","府藏金帛积，生灵气力疲。","盗贼天下起，章奏禁中欺。","海内空龙战，河东有凤姿。","元戎展鹰犬，颉利助熊罴。","奉表遵朝命，尊王建义旗。","经营于盗手，禅让托君辞。","豪哲归吾彀，要荒入我羁。","太宗真令主，贞观有皇规。","正美开元治，俄成天宝悲。","曲江还故里，林甫领台司。","裂土封三国，缠头爱八姨。","霓裳犹未罢，鼙鼓恨来迟。","逆寇陵丹阙，君王舍翠眉。","两京贼党灭，方镇重权移。","朱李元堪叹，石刘亦可嗤。","九州重搆乱，五代荐荒饥。","辽宋分南北，翁孙讲礼仪。","宣和风侈靡，教主德庸卑。","背约绝邻好，兴师借寇资。","悬知丧唇齿，何事撤籓篱。","失地人皆怨，蒙尘悔可追。","辽家遵汉制，孔教祖宣尼。","焕若文章备，康哉政事熙。","朝廷严衮冕，郊庙奏埙篪。","校猎温驰射，行营习正奇。","南州走玉帛，诸国畏鞭笞。","天祚骄人上，朝鲜叛海涯。","未终三百祀，不免一朝危。","鸭绿金朝起，桑乾玉玺遗。","后辽兴大石，西域统龟兹。","万里威声震，百年名教垂。","武元平宋地，殷礼杂宗姬。","治国崇文事，拔贤尚赋词。","邦昌君洛汭，刘豫立青淄。","大定民兴咏，明昌物适宜。","日中须景昃，月满必光亏。","肘腋独夫难，丘墟七庙隳。","北朝天辅佑，南国俗疮痍。","天子潜巡狩，宗臣严守陴。","山西尽荆枳，河朔半豺狸。","食尽谋安出，兵羸力不支。","长围重数匝，久困再周期。","太液生秋草，姑苏游野麋。","忠臣全节死，馀众入降麾。","文献生三子，东丹第八枝。","虚名如画饼，遗业学为箕。","自笑蓬垂鬓，谁怜雪满髭。","抚膺长感慨，搔首几嗟咨。","车盖知何处，衣冠问阿谁。","自天明下诏，知我素通蓍。","发轫装琴剑，登车执策绥。","穹庐或白黑，驿骑半黄駓。","肥脔白如瓠，琼浆甘似饴。","天山连北府，瀚海过西伊。","天马穷渤澥，神兵过月氏。","感恩承圣敕，寄住到寻罳。","春色多红树，秋波总绿陂。","不须赊酒饮，随分有驴骑。","畎亩栖禾粟，园林足果梨。","舂粳光璨玉，煮饭滑流匙。","圣祖方轻举，明君应乐推。","龙庭陈大礼，原庙献明粢。","万国朝金陛，千官列玉墀。","求贤为辅弼，举我忝丞疑。","才德真为慊，颠危不解持。","愿从麋鹿性，岂恋凤凰池。","投老谁为伴，黄山有敏之。"]},{"t":"示忘忧","f":"七言绝句","c":["历代兴亡数张纸，千年胜负一盘棋。","因而识破人间梦，始信空门一著奇。"]},{"t":"和金城宝宫旭公禅师三绝 其一","f":"七言绝句","c":["知公已得夜明符，任运腾腾无所拘。","见说金城多长者，有人青眼待君无。"]},{"t":"和金城宝宫旭公禅师三绝 其二","f":"七言绝句","c":["南北东西总一家，才生拟议便生瑕。","人人错认髯居士，只有禅师不眼华。"]},{"t":"和金城宝宫旭公禅师三绝 其三","f":"七言绝句","c":["旭老今年锥也无，粪堆却得旧明珠。","穹庐半夜无灯烛，请尽平安一纸书。"]},{"t":"再和世荣二十韵寄薛玄之","f":"五言古诗","c":["尚记承平日，为学体自强。","经书兴我志，功业逼人忙。","蛰窟长思震，葵心本慕阳。","蛟龙初得雨，日月近依光。","事主心无隐，遭时策建长。","引君当正道，陈事上封章。","亦既尊仁义，胡为失毅刚。","箴规尽忠赤，人物敢雌黄。","断似南山定，言令北斗昂。","劝君师魏郑，嫉恶法张纲。","青眼蒙高顾，白眉忝最良。","谁知天有数，不觉汉亡疆。","人笑段干木，谁师田子方。","上苍垂大命，天阙册明王。","殷室君虽灭，仁人道未亡。","南州远烟水，北海几星霜。","仁政时将治，明君国寖昌。","卿云知有庆，嘉谷又呈祥。","名遂宜思退，机危乃自戕。","归欤今好赋，闻道故园荒。"]},{"t":"兰仲文寄诗二十六韵勉和以谢之","f":"五言古诗","c":["我爱仲文公，敦纯有古风。","科名擢乙选，制策肯宸衷。","作事能谋始，为人克有终。","养如邹轲气，成自仲尼镕。","致主忠诚恳，容人便腹空。","一朝淹骥足，百里试鸠功。","牛刃聊施割，囊锥已脱锋。","屯方雷雨动，泰末地天通。","聚散悲欢里，兴亡梦寐中。","势倾秦失鹿，奸殒鲧为熊。","不学东方朔，谁徵皇甫嵩。","洛阳传白傅，江夏誉黄童。","上国平诸域，舆情达四聪。","百司将布置，多士想登庸。","未识荆州面，徒思卫玠容。","中原期混一，天子访英雄。","嘉运人皆幸，亨时君又逢。","污俗风已变，明主德方隆。","施雨皇恩布，如流直谏从。","凯元咸戮力，稷契各言忠。","我愧凡庸士，恩沾造化工。","兵氛箕尾没，剑气斗牛冲。","西华将归马，南阳莫卧龙。","孝廉为选举，仁义作帡幪。","历运千年合，衣冠万国同。","草仪独有子，行待泰山封。"]},{"t":"又和仲文二首 其一","f":"七言律诗","c":["仲文才笔冠人间，工部坛前第一班。","世上久无孔北海，云中谁识谢东山。","忘怀诗酒醒还醉，适意琴书乐且闲。","野有遗贤犹未用，中书宁得不胡颜。"]},{"t":"又和仲文二首 其二","f":"七言律诗","c":["室中忝预万松筹，脱得中间与两头。","反覆人心厌殷室，咄嗟天下属宗周。","直须勇退中书事，未肯荣贪留国侯。","收拾纶竿与蓑笠，华亭却觅旧渔舟。"]},{"t":"用曹桢韵","f":"七言律诗","c":["征南都护得旋旆，平北将军已罢师。","寰海讴歌归大舜，明堂钟鼓奏咸池。","咸阳父老倾心日，鲁国书生得志时。","收拾琴书我归去，朝廷人物有皋夔。"]},{"t":"怨浩然","f":"七言律诗","c":["先难后易真交契，醉许醒违盖世情。","玉涧白输六居士，升元乌有一先生。","昔蒙佳句诚欢忭，今得芳缄且叹惊。","一入侯门深似海，骚人空梦帐中声。"]},{"t":"从国才索闲闲煎茶赋","f":"七言绝句","c":["闻君久得煎茶赋，故我先吟投李诗。","为报君侯休吝惜，照人琼玖算多时。"]},{"t":"赠高善长一百韵","f":"曲","c":["君本辽阳人，家居华表傍。","随任来燕然，卜筑金台坊。","幼蒙父兄训，读书登上庠。","大义治三传，左氏为纪纲。","诗书究微理，易道宗京房。","吏学亦精妙，议论如馨香。","行道有馀力，下笔能诗章。","典雅继李杜，浮华笑陈梁。","当年辟科举，郡国求圭璋。","御围屡不捷，在前饶秕糠。","先生乃医隐，退身慕羲皇。","难素透玄旨，针砭能起僵。","可并华扁迹，可联和缓芳。","门生皆良医，西海高名扬。","昔我知君名，方且王事忙。","兵尘隔东西，忽成参与商。","君初涉洛瀍，我已达燉煌。","瀚海浪奔激，金山路徬徨。","西游几万里，两鬓今苍苍。","西方好风土，大率无蚕桑。","家家植木绵，是为垄种羊。","年年旱作魃，未识舞?鴹。","决水溉田圃，无岁无丰穰。","远近无饥人，四野栖馀粮。","是以农民家，处处皆池塘。","飞泉绕曲水，亦可斟流觞。","早春而晚秋，河中类馀杭。","濯足或濯缨，肥水如沧浪。","杂花间侧柏，园林如绣妆。","烂醉蒲萄酒，渴饮石榴浆。","随分有弦管，巷陌杂优倡。","佳人多碧髯，皎皎白衣裳。","市井安丘坟，畎亩连城隍。","货钱无孔郭，卖饭称斤量。","甘瓜如马首，大者狐可藏。","采杏兼食核，餐瓜悉去瓤。","西瓜大如鼎，半枚已满筐。","芭榄贱如枣，可爱白沙糖。","人生为口腹，何必思吾乡。","一住十馀年，物我皆相忘。","神祖上仙去，圣主登明堂。","驲骑徵我归，忝位居岩廊。","河表寒旧盟，鄜秦成战场。","翠华乃南渡，鸾驭声锵锵。","六军临孟津，偏师出太行。","间路入斜谷，南鄙侵寿唐。","犄角皆受敌，应战实未遑。","一旦汴梁破，何足倚金汤。","下诏求名医，先生隐药囊。","驰轺来北阙，失措空仓惶。","我于群鸡中，忽见孤凤凰。","下马执君手，涕泪其如滂。","我叹白头翁，君亦嗟髯郎。","停灯话旧事，谈笑吐肺肠。","酬酢觅佳句，沈思搜微茫。","湛然访医药，预备庸何妨。","高君略启口，确论闻未尝：「医术与治道，二者元一方。","武事类药石，文事如膏粱。","膏粱日日用，药石藏巾箱。","一朝有急病，药石施锋铓。","病愈速藏药，膏粱复如常。","缓急寇难作，大剑须长枪。","寇止兵弗戢，自焚必不长。","发表勿攻里，治内无外伤。","朝廷有内乱，安可摇边疆。","疆场或警急，中变决自戕。","阴病阳脉生，阳症阴脉亡。","暴法譬之阴，仁政喻之阳。","太平虽日久，恣暴降百殃。","大乱遍天下，行仁降百祥。","一君必二臣，佐使仍参详。","不殊世间事，烝民无二王。","国老似甘草，良将比大黄。","一缓辅一急，一柔济一刚。","病来不速治，安居养豺狼。","疾作傥无药，遇水泛舟航。","病固有寒热，药性分温凉。","疗热用连糵，理寒宜桂姜。","君子与小人，礼刑令相当。","虚者补其嬴，实者泻其强。","扶衰食枸杞，破血服槟榔。","抑高举其下，天道犹弓张。","损馀补不足，贫富无低昂。","寒多成冷痼，热盛为疮疡。","政猛民伤残，政慢贼猖狂。","保生必求源，胃府为太仓。","四时胃为主，端居镇中央。","朝廷天下本，本固邦家昌。","实实而虚虚，其谋元不臧。","五行不偏胜，所以寿而康。","太宗平府兵，是致威要荒。","未病宜预治，未乱宜预防。","贼臣弑君父，祸难生萧墙。","辨之由不早，即渐成坚霜。","心腹尚难治，况复及膏肓。","」湛然闻此语，不觉兴胡床。","谢君赠诲言，苦口如药良。","问一而得二，和璧并夜光。","走笔书新诗，一笑呈龙冈。"]},{"t":"再赓仲祥韵寄之","f":"五言古诗","c":["能谈仁义兵，经传宗素臣。","字画类闲闲，句法如之纯。","淡然与世疏，渭水独垂纶。","蒿莱塞庭除，尘土沾衣绅。","归我夫子门，三月无违仁。","后生来从学，善诱能循循。","颜巷不改乐，范甑长生尘。","仰不愧于天，俯不怍于人。","进德方乾乾，慎行而修身。","旅食秦晋间，骑驴三十春。","珠玉炙人口，丽藻嘉彬彬。","今年又绝粮，生涯如在陈。","歌咏犹不辍，真为葛天民。","新诗过子卿，离骚齐灵均。","亡机天壤间，举措皆天真。","濯足沧浪中，鸥鹭来相亲。","胸中万卷书，下笔端如神。","素负经济才，人品伊皋伦。","桂林祇一枝，亦何惭郗诜。"]},{"t":"寄金城士大夫","f":"七言绝句","c":["金城人士本多奇，何事庠宫久蔑资。","周急无轻五秉粟，伤时因寄一篇诗。"]},{"t":"诚之索偈","f":"七言绝句","c":["诚之久侍万松师，何事十年下手迟。","劫火光中须退步，青春宁有再来时。"]},{"t":"遗侄淑卿香方偈","f":"曲","c":["我有一香香，秘之不敢说。","心生种种法生，心灭种种法灭。","退身一念未生前，此是真香太奇绝。","邪神恶鬼永沈踪，外道天魔皆胸裂。"]},{"t":"为子铸作诗三十韵","f":"五言古诗","c":["皇祖辽太祖，奕世功德积。","弯弓三百钧，天威威万国。","一旦义旗举，中原如捲席。","东鄙收句丽，西南穷九译。","古器获轩鼎，神宝得和璧。","南陬称子孙，皇业几三百。","赫赫东丹王，让位如夷伯。","藏书万卷堂，丹青成画癖。","四世皆太师，名德超今昔。","我祖建四节，功勋冠黄閤。","先考文献公，弱冠已卓立。","学业饱典坟，创作乙未历。","入仕三十年，庙堂为柱石。","重义而疏财，后世遗清白。","我受先人体，兢兢常业业。","十三学诗书，二十应制策。","禅理穷毕竟，方年二十七。","万里渡流沙，十霜泊西域。","自愧无才术，忝位人臣极。","未能扶颠危，虚名徒伴食。","汝方志学年，寸阴真可惜。","孜孜进仁义，不可为无益。","经史宜勉旃，慎毋耽博弈。","深思识言行，每戒迷声色。","德业时乾乾，自强当不息。","幼岁侍皇储，且作春宫客。","一旦冲青天，翱翔腾六翮。","儒术勿疏废，祖道宜薰炙。","汝父不足学，汝祖真宜式。","酌酒寿汝年，五福自天锡。"]},{"t":"请旭公禅师住应州宝宫寺疏","f":"七言绝句","c":["孙枝出入万松中，便好移来植宝宫。","覆荫人天正今日，不妨鼓动劫前风。"]},{"t":"请希庵主住晋祠奉圣寺开堂疏","f":"七言绝句","c":["晋祠山水冠人间，好请希公向此闲。","饭了蒙头三觉睡，逢人休说赵州关。"]},{"t":"请学庵主住翠微山宝林寺开堂出世疏","f":"七言绝句","c":["金城元有翠微山，宝刹禅林积岁闲。","笑请学公来领略，一瓶游戏白云间。"]},{"t":"请石州海秀首座住文水寿宁寺疏","f":"七言绝句","c":["闻道霖师退寿宁，秀公难弟亦难兄。","新诗远寄石州去，贬起眉毛便好行。"]},{"t":"重修宣圣庙疏","f":"七言绝句","c":["精蓝道观已重新，独有庠宫尚垝垣。","试问中州士君子，谁人不出仲尼门。"]},{"t":"德兴府?峪云岩寺请东林老人住持疏","f":"七言绝句","c":["昔日山中养圣胎，峪中松桧手亲栽。","院荒松老无龙象，便请东林更一来。"]},{"t":"请柏岩俨公疏","f":"七言绝句","c":["良弼施宅创天宁，却请天宁旧衲僧。","为报柏岩休逊让，闲中续出祖师灯。"]},{"t":"邳州重修宣圣庙疏","f":"七言绝句","c":["宣尼万古帝王师，可叹荆榛没古祠。","重整庠宫阐文教，颙观日月再明时。"]},{"t":"安庆织万佛疏","f":"七言绝句","c":["十方三世万如来，不犯梭头宝座开。","单手元知不成拍，三台须要大家催。"]},{"t":"请聪公和尚住山阴县复宿山疏","f":"七言绝句","c":["昔日文殊曾复宿，当年聪老可重来。","此山便是真佛窟，何必区区礼五台。"]},{"t":"万寿寺创建厨室上梁文 其一","f":"曲","c":["抛梁东，香积移来不犯功。","却笑维摩无手段，但将盂饭到尘中。"]},{"t":"万寿寺创建厨室上梁文 其二","f":"曲","c":["抛梁南，底个因缘最好参。","试问助缘多少众，前三三与后三三。"]},{"t":"万寿寺创建厨室上梁文 其三","f":"曲","c":["抛梁西，巧匠骑驴倒上梯。","四面无门何用锁，十方没壁不须泥。"]},{"t":"万寿寺创建厨室上梁文 其四","f":"曲","c":["抛梁北，柱石宛有擎天力。","欲模此样向诸方，?杀僧繇描不得。"]},{"t":"万寿寺创建厨室上梁文 其五","f":"曲","c":["抛梁上，手不伤材真大匠。","虚堂穷劫镇丛林，借与儿孙为榜样。"]},{"t":"万寿寺创建厨室上梁文 其六","f":"曲","c":["抛梁下，聊倩般输成大厦。","朝朝香饭供诸佛，承事悉无空过者。"]},{"t":"和林城建行宫上梁文 其一","f":"曲","c":["抛梁东，万里山川一望中。","灵沼灵台未为比，宸宫不日已成功。"]},{"t":"和林城建行宫上梁文 其二","f":"曲","c":["抛梁南，一带南山挹翠岚。","创筑和林建宫室，酂侯功业冠曹参。"]},{"t":"和林城建行宫上梁文 其三","f":"曲","c":["抛梁西，碧海寒涛雪拍堤。","臣庶称觞来上寿，嵩呼拜舞一声齐。"]},{"t":"和林城建行宫上梁文 其四","f":"曲","c":["抛梁北，圣主守成能润色。","明堂壮丽镇龙沙，万世巍巍威万国。"]},{"t":"和林城建行宫上梁文 其五","f":"曲","c":["抛梁上，栋宇施功遵大壮。","鸣鞘声散翠华来，五云深处瞻天仗。"]},{"t":"和林城建行宫上梁文 其六","f":"曲","c":["抛梁下，柱石相资成大厦。","君臣钟鼓乐清时，喜见山阳归战马。"]},{"t":"为武川摩诃院创建佛牙塔疏","f":"七言绝句","c":["佛日增辉国政和，灵牙有诏赐摩诃。","因风吹火何劳力，垂手同修窣堵波。"]},{"t":"和润之韵","f":"七言绝句","c":["疏笋篱边正脱绷，故山清处便宜行。","镜湖他日应属我，好向湖边访四明。"]},{"t":"赠景贤","f":"七言绝句","c":["茶邻药物成邪气，琴伴箫声变郑音。","可惜龙冈老居士，却教邪教污真心。"]},{"t":"寄东林","f":"七言绝句","c":["东林已秀两三枝，覆荫人天正此时。","贪向龙宫翻贝叶，恼人不寄玉泉诗。"]},{"t":"寄万寿润公禅师","f":"七言绝句","c":["林泉人笑凤凰枝，我慕林泉叹后时。","盼得人来问消息，太平和尚又无诗。"]},{"t":"寄甘泉慧公和尚","f":"七言绝句","c":["东林枝胜桂林枝，不惜甘泉济旱时。","铁额钢头含笑面，可人能字更能诗。"]},{"t":"遗龙冈鹿尾二绝 其一","f":"七言绝句","c":["秋水清声忽变商，龙冈曾遗二山羊。","今年祗奉诗三首，为报先生鹿尾浆。"]},{"t":"遗龙冈鹿尾二绝 其二","f":"七言绝句","c":["去岁山羊酬过价，今年鹿尾不值钱。","龙冈药物都竭底，只得髯翁诗数篇。"]},{"t":"和景贤赠鹿尾二绝 其一","f":"七言绝句","c":["日暮长杨猎骑归，西风弓硬马初肥。","今年鹿尾休嫌少，且喜君王不合围。"]},{"t":"和景贤赠鹿尾二绝 其二","f":"七言绝句","c":["禁脔酷思浓鹿汁，香蔬久厌小儿拳。","龙冈采得班龙尾，一串穿来寄玉泉。"]},{"t":"中秋召景贤饮","f":"七言绝句","c":["中秋北海景凄凄，好拚今宵醉似泥。","快请龙冈疾过我，与君同泛玉东西。"]},{"t":"请定公住大觉疏","f":"七言绝句","c":["龙龛宝藏照人寒，奥老功成住圣安。","却请定公来领略，收拾香火礼旃檀。"]},{"t":"补大藏经板疏","f":"七言绝句","c":["十年天下满兵埃，可惜经文半劫灰。","欲析微尘出经卷，随缘须动世间财。"]},{"t":"武川摩诃院创建瑞像殿疏","f":"七言绝句","c":["邦人创刻旃檀像，寺众新修窣堵波。","两段因缘非细事，成功须仗大檀那。"]},{"t":"请奥公住崇寿院","f":"七言绝句","c":["泥湫昔日隐蛰龙，一震重新大觉宫。","却请收云归旧壑，晨昏香火礼师翁。"]},{"t":"寄圣安澄老乞药","f":"七言绝句","c":["登高回首望燕山，试道新诗怨圣安。","赚得护身符子去，二年不寄大还丹。"]},{"t":"信之和余酬贾非熊三字韵见寄因再赓元韵以复之 其一","f":"七言律诗","c":["鴳鹑徒羡大鹏南，驽马终须后袅骖。","至理犹删万归一，庸儒刚说二生三。","透关活眼嫌金屑，恋土痴人宿草庵。","寄与云川贤太守，洗心涤虑与君参。"]},{"t":"信之和余酬贾非熊三字韵见寄因再赓元韵以复之 其二","f":"七言律诗","c":["恼人捷径起终南，虚忝沙堤相国骖。","幻术莫惊殷七七，真诠谁识后三三。","家邻荆水宜裁竹，缘在香山好结庵。","斫断葛藤窠已后，闲家破具不须参。"]},{"t":"信之和余酬贾非熊三字韵见寄因再赓元韵以复之 其三","f":"七言律诗","c":["鸿雁翩翩自北南，归欤何日驾归骖。","潜龙在下宜初九，即鹿无虞戒六三。","洛下好游白傅寺，济源重觅侍中庵。","衰翁自揣何多幸，昨梦斋中得罢参。"]},{"t":"信之和余酬贾非熊三字韵见寄因再赓元韵以复之 其四","f":"七言律诗","c":["旧隐翳闾白霫南，故山佳处好停骖。","贪嗔痴者元无一，诗酒琴之乐有三。","菱芡香中横短艇，松筠声里称危庵。","有人问道来相访，一碗清茶不放参。"]},{"t":"云汉远寄新诗四十韵因和而谢之","f":"曲","c":["兑爻符太一，天相忝文昌。","泛海难追蠡，封留欲学良。","秽形伴珠玉，朽木厕松樟。","直节心虽赤，衰年鬓已苍。","伴食居相府，无德报君王。","草甲濡春雨，葵心倾太阳。","大权归禁阙，成算出岩廊。","自北王师发，平南上策长。","皇朝将革命，亡国自颓纲。","汉水偏师渡，长河一苇航。","股肱无敢惰，元首载歌康。","号令传诸域，英雄守四方。","大勋虽已集，遗命未尝忘。","万国来驰币，诸侯敬奉璋。","兆民涵舜德，百郡仰天光。","大有威如吉，重乾体自强。","硕贤起编户，良将出戎行。","太庙陈笾豆，明堂服冕裳。","宋朝微寖灭，皇嫡久成戕。","政乱人思变，君愚自底亡。","右师潜入剑，元子直临襄。","杀气侵南斗，长庚壮玉堂。","弓犹藏宝玉，剑未识干将。","皇业超千古，天威耸八荒。","元戎施虎略，勇士展鹰扬。","武继元封迹，文联贞观芳。","宫庭敢谏鼓，帷幄上书囊。","伫待卿云见，行观丹凤翔。","武文能迭用，威德足相当。","多士思登用，遗贤肯退藏。","诗书搜鸟篆，功业抑龙骧。","国用恒无缺，民财苦不伤。","八音歌颂雅，百戏屏优倡。","圣泽传朝露，明刑肃暮霜。","永垂尘劫祚，一混九州疆。","重任司钧石，微才匪栋梁。","思归心似醉，感愧泪如滂。","严子终辞汉，黄公合隐商。","穷通真有数，忧乐实难量。","虽受千钟禄，何如归故乡。","乙未闰月上旬日，玉泉书。"]},{"t":"德新先生惠然见寄佳制二十韵和而谢之","f":"曲","c":["当年职都水，曾不入其门。","德重文章杰，年高道义尊。","虽闻传国士，恨不识王孙。","韵语如苏武，离骚类屈原。","烟霞供好句，江海入雄吞。","意气轻三杰，才名冠八元。","著述归至赜，议论探深源。","藉藉名虽重，区区席不温。","家贫谒鲁肃，国难避王敦。","北鄙来云内，西边退吐蕃。","勉将严韵继，不得细论文。","远害虽君智，全身亦圣恩。","大才宜应诏，豪气傲司阍。","学识光先哲，风流遗后昆。","莫寻三岛客，好谒万松轩。","六度真光发，三毒妄影奔。","素丝忘染习，古镜去尘昏。","炉上飞寒雪，胸中洗热烦。","到家浑不识，得象固忘言。","心月孤圆处，澄澄泯六根。","乙未闰月上休日，玉泉书。"]},{"t":"子铸生朝润之以诗为寿予因继其韵以遗之","f":"五言古诗","c":["岩松傲岁寒，枝干腾千尺。","男儿若稽古，功名垂竹帛。","我祖东丹王，施仁能善积。","我考文献公，清白遗四壁。","盛名流万世，馨香光赫赫。","余生叹不辰，西域十年客。","贫困志不渝，未肯忘平昔。","昔日出燕然，辰当摄提格。","鹑尾得凤毛，续后予无责。","汝知学不学，何啻云泥隔。","为山亏一篑，龙门空点额。","远袭周孔风，近追颜孟迹。","优游礼乐方，造次仁义宅。","继夜诵诗书，废时毋博弈。","勤惰分龙猪，三十成骨骼。","孜孜寝食废，安可忘朝夕。","行身谨而信，于礼顺而摭。","祥麟具五蹄，溟鹏全六翮。","为人备五常，奚忧仕与谪。","成功不自满，始知谦受益。","慎毋忘此诗，吾言真药石。"]},{"t":"扈从旋师道过东胜秦帅席上继杜受之韵","f":"五言律诗","c":["去国十年久，还乡两鬓皤。","三川犹梗涩，百越正干戈。","东胜城无恙，西征事若何。","凭高吟望久，樽酒酹长河。"]},{"t":"用梁斗南韵","f":"七言律诗","c":["丁年学道道难成，却得中原浪播名。","否德自惭调鼎鼐，微才不可典玑衡。","谁知东海潜姜望，好向南阳起孔明。","收拾琴书作归计，玉泉佳处老馀生。"]},{"t":"赠侄正卿","f":"七言律诗","c":["辽室东丹九叶芳，曾陪剑佩侍明昌。","学书写尽千林叶，习射能穿百步杨。","兴废人间战白蚁，荣枯枕上梦黄粱。","故山咫尺宜归去，莫使因循三径荒。"]},{"t":"寄张鸣道","f":"七言律诗","c":["张君宗派自留侯，壮岁成名入士流。","一代诗声如玉振，千钧笔力挽银钩。","平山邂逅初青眼，汴水伶仃已白头。","遥想荷花好时节，故人吟倚仲宣楼。"]},{"t":"送省掾郭仲仁行","f":"七言绝句","c":["兰省而今已预名，还乡衣锦也为荣。","辽阳干事须详悉，速驾星轺上玉京。"]},{"t":"送燕京高庆民行","f":"七言绝句","c":["国事烦多我政忧，上章清选倅徵收。","好陪刘晏勤王事，早使钱如地上流。"]},{"t":"和赵庭玉子贽韵","f":"七言律诗","c":["万里龙庭白草秋，时时归梦旧渔舟。","酌残白酒难成醉，老尽黄花无限愁。","久识人心多厌政，喜逢天下已归刘。","而今子入中州去，莫惜寒梅寄陇头。"]},{"t":"赠东平主事王玉","f":"五言绝句","c":["圣主方思治，边臣未奉行。","凭君达此意，无得负苍生。"]},{"t":"周敬之修夫子庙","f":"七言绝句","c":["天皇有意用吾儒，四海钦风尽读书。","可爱风流贤太守，天山创起仲尼居。"]},{"t":"寄万寿堂头乞湖山","f":"七言绝句","c":["削玉剜琼出自然，依晞岩窦吐云烟。","禅师手段掀山岳，便好移来向玉泉。"]},{"t":"寄东林同参","f":"七言绝句","c":["东林屡有寄来诗，忙里何尝报一辞。","岂是玉泉生吝惜，言无滋味不宜时。"]},{"t":"寄简堂头","f":"七言绝句","c":["巨川生下此村牛，千百头中祗一头。","鼻孔撩天无主伴，不风流处也风流。"]},{"t":"寄孔雀便面奉万松老师","f":"七言绝句","c":["风流彩扇出西州，寄与白莲老社头。","遮日招风都不碍，休从侍者索犀牛。"]},{"t":"答倪公故人","f":"曲","c":["玉泉回报故人书，问子参玄着意无。","且趁万松炉?热，疾忙索取护身符。"]},{"t":"送王璘行","f":"七言绝句","c":["天涯九日出龙沙，冬后冬前却到家。","馈运功成须报我，好游天汉上浮槎。"]},{"t":"继介丘穆景华韵","f":"七言律诗","c":["北海慵倾北海樽，予怀为向景华伸。","奇才管葛堪为匹，何事唐虞不得臣。","行道欲期丹凤出，忘机且与白鸥亲。","龙庭万里休辞远，六出奇画正赖陈。"]},{"t":"继平陶张才美韵","f":"七言律诗","c":["才美风流自一时，因风来寄湛然诗。","新朝制度知将近，晚节功名未是迟。","识子固为天下士，微君孰抚我民痍。","援毫欲继清新句，笑我却无黄绢辞。"]},{"t":"德柔尝许作鞍玉辔且数年矣作诗以督之","f":"七言绝句","c":["异物当时许晋卿，几年思渴动诗情。","龙庭风细沙堤软，玉辔雕鞍正好行。"]},{"t":"卜邻一绝寄郑景贤","f":"七言绝句","c":["龙沙幽隐子真家，自拨寒泉出浅沙。","我愿卜邻穹帐侧，旋分清酌煮新茶。"]},{"t":"寄岳君索玉博山","f":"七言绝句","c":["玉炉精巧若裁肪，寄与髯翁也不妨。","古庙多年无气息，直消一炷返魂香。"]},{"t":"云中重修宣圣庙","f":"七言绝句","c":["槐宫悉混玉石焚，庙貌依然惟古云。","须仗吾侪更脩葺，休教风世丧斯文。"]},{"t":"寄光祖","f":"七言绝句","c":["渔阳光祖冠当时，笔法词源我独知。","君有家鸡君自厌，为何偏爱玉泉诗。"]},{"t":"送德润南行","f":"七言绝句","c":["燕然民庶久疮痍，摩抚疮痍正此时。","暴吏猾胥谄君日，开缄三复味予诗。"]},{"t":"再和万寿润禅师书字韵五首 其一 忧道","f":"七言律诗","c":["不肯参禅不读书，徒喧口鼓说真如。","未能即色明真色，只道无馀已有馀。","法眼凋残浮海去，沩山寂寞少人居。","一从三圣承当后，季世寥寥无瞎驴。"]},{"t":"再和万寿润禅师书字韵五首 其二 述怀","f":"七言律诗","c":["宝藏翻穷贝叶书，方知真理本如如。","一心不动无生灭，万古长空岂欠馀。","妙药更灵难忌口，长安虽贵不堪居。","毛吞大海浑闲事，谁讶瓢中出白驴。"]},{"t":"再和万寿润禅师书字韵五首 其三 警世","f":"七言律诗","c":["看尽人间万卷书，较量佛法总难如。","本无妄疾刚寻药，幸有回波好乞馀。","方丈名山真碧海，含元古殿是皇居。","行人半老家何在？","终日骑驴却觅驴。"]},{"t":"再和万寿润禅师书字韵五首 其四 伤时","f":"七言律诗","c":["金马门前数上书，子虚新赋笑相如。","万言警策才无敌，六国纵横智有馀。","千里兵车讨奸宄，五更朝马候兴居。","功名赚得头如雪，不悟团团如磨驴。"]},{"t":"再和万寿润禅师书字韵五首 其五 投老","f":"七言律诗","c":["囊里瑶琴驾上书，个中真味更何如。","伴闲美竹千竿许，养老田园二顷馀。","睡起焚香诵圆觉，兴来缓轸品幽居。","夕阳半下山偏好，吟入烟霞稳跨驴。"]},{"t":"赠景贤玉涧鸣泉琴","f":"七言律诗","c":["玉泉珍惜玉泉琴，不遇高人不许心。","素轸四三排碧玉，明徽六七粲黄金。","临风好奏朝飞曲，对月宜弹清夜吟。","赠与龙冈老居士，须教下指便知音。"]},{"t":"丙申元日为景贤寿","f":"七言律诗","c":["龙沙一住二十年，独识龙冈郑景贤。","诗笔饶君甘在后，琴棋笑我强争先。","冷官何啻广文乐，归计犹存谷口田。","劫外壶天寿无量，请公勤叩祖师禅。"]},{"t":"景贤作诗颇有思归意因和元韵以勉之","f":"五言律诗","c":["我访龙冈老，珠玑咳唾间。","酒熟香馥馥，琴滑水潺潺。","王吉中栽菊，和林也有山。","但能心放下，何处不安闲。"]},{"t":"景贤召予饮以事不果翌日予访景贤值出予开樽尽醉而归留诗戏之","f":"七言绝句","c":["昨朝命我初无兴，今日寻君不在家。","不问主人都饮尽，醉吟倒载黑毡车。"]},{"t":"和景贤召饮韵","f":"七言绝句","c":["书满穹庐酒满樽，龙冈召我谢殷勤。","琴中别有无弦曲，醉里开怀举似君。"]},{"t":"丙申上元夜梦中有得","f":"七言绝句","c":["超佛越祖透真空，也与沩山说梦同。","面貌眼睛鼻孔里，大千沙界一沤中。"]},{"t":"送门人刘德真征蜀","f":"七言律诗","c":["门弟辽阳刘德真，刚直木讷近乎仁。","怜君粗有才学术，师我精通天地人。","今日从军征两剑，他时拥旆入三秦。","三辰测验须吾子，创作天朝宝历新。"]},{"t":"送门人刘复亨征蜀","f":"七言律诗","c":["诚之识我二十年，不读经书不学禅。","误尔儒冠好投笔，过人勋业好加鞭。","浣花溪畔春如画，濯锦江边酒似川。","壮岁从军真乐事，邓侯遗躅勉争先。"]},{"t":"赵州柏树颂","f":"七言绝句","c":["古佛犹存旧道场，庭前依旧柏苍苍。","莫谤诸州无此语，禅林奔走错商量。"]},{"t":"黄龙三关颂 其一 我手何似佛手","f":"七言绝句","c":["称头斤两须端的，短少毫釐不可欺。","函关辨认合同券，未肯轻轻放过伊。"]},{"t":"黄龙三关颂 其二 我脚何似驴脚","f":"七言绝句","c":["行令如同车脚圆，你三文后我三钱。","直饶道底分明是，也是当年鹦鹉禅。"]},{"t":"黄龙三关颂 其三 如何是上座生缘","f":"七言绝句","c":["只打野盘无寺宿，不供糊口趁村斋。","上户莫桩虚物力，僧司无得错推排。"]},{"t":"和太原元大举韵","f":"七言律诗","c":["魏帝儿孙气似龙，而今飘泊困尘中。","君游泉石初无闷，我秉钧衡未有功。","元氏从来多慷慨，并门自古出英雄。","李唐名相沙堤在，好与微之继旧风。"]},{"t":"喜和林新居落成","f":"七言绝句","c":["登车凭轼我怡颜，饱看和林一带山。","新构幽斋堪偃息，不闲闲处得闲闲。"]},{"t":"题新居壁","f":"七言绝句","c":["旧隐西山五亩宫，和林新院典刑同。","此斋唤醒当年梦，白昼谁知是梦中。"]},{"t":"太原修夫子庙疏","f":"七言绝句","c":["并门连岁不年丰，证父攘羊礼义空。","既倒狂澜扶不起，直须急手建庠宫。"]},{"t":"和林建佛寺疏","f":"七言绝句","c":["龙沙玄教未全行，故筑精蓝近帝城。","须仗檀那垂手力，一轮佛日焕然明。"]}]};